\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 1\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -222d\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Gerardus de Malliaco: Sermones de tempore (T1-T65)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 1: \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 In aduentu domini. Sermo de epistola\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Abiciamus ergo opera\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 tenebrarum\plain \f1\lang1033\fs24\chcbpat8  (Rm 13,12). \plain \f1\i\lang1033\fs24\chcbpat8 Quoniam in presenti tempore recitat mater ecclesia aduentum filii dei in mundum \plain \f1\lang1033\fs24\chcbpat8 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 qui finis est eterna beatitudo, ad quam nos perducat ille, qui est benedictus in secula. Amen\plain \f1\lang1033\fs24\chcbpat8 . \endash  (4\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 2; (6\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 3; (10\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 5; (13\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 6; (16\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 7; (18\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 13; (21\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 16; (25\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 17; (29\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 18; (33\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 19; (37\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 20; (39\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 21; (43\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 23; (46\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 24; (50\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 25; (52\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 26; (55\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 27; (59\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 30; (59\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 31; (62\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 32; (66\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 34; (69\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 37; (74\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 38; (80\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 40; (85\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 42; (89\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 43; (92\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 44; (97\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 45; (101\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 46; (105\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 47; (110\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 48; (113\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 49; (118\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 51; (122\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 52; (127\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 54; (131\plain \f1\super\lang1033\fs24\chc