\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 149\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -191\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Tractatus de silentio et taciturnitate
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Incipit prefacio in tractatum de silencio et taciturnitate religiosa et salutari\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Iterum atque iterum cogitante michi dudum iam multo tempore, quomodo aliqualiter breue et compendiosum verbum inuenirem\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (154\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Quid sit loqui, quid sit lingua et quorum et quid sit locucio, quidve os, quid sit verbum quidque tacere opposito modo. Capitulum primum\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Lingua quantum ad presens est omne id, quo sibi vel aliis aliquid innotescit\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quia sicut conuersio multa quidem indiget humilitate. Ita hec omnis est argmentum elacionis\plain \f1\lang1033\fs24\chcbpat8 ||. Vermutlich Textabbruch. \endash  191\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 -192\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Ungedruckt.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 193\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -220\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Tractatus de observantia regulari
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Quia, fratres karissimi, quanto in presenti lacrimarum valle pigri sine quottidiano profectu conspicimur, viatores tanto celestem adipisci patriam reddimur tardiores\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 velut naturaliter ex consuetudine incipiemus custodire non tam timore gehenne quam amore Christi, qui nos pariter ad uitam eternam perducat\plain \f1\lang1033\fs24 . \endash  \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Incipit Speculum beati Bernardi abbatis de honestate vite\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Ungedruckt.}

