\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 128\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -129\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Isidorus Hispalensis: Synonyma de lamentatione animae peccatricis
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Incipit de soliloquiis Ysidori\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Te ipsum censorio iudicio\plain \f2\b\i\lang1041\fs20\chcbpat8\cf1  \plain \f1\i\lang1033\fs24 discute, et statim cognoscis quia quecunque \plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 afflictiones\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\i\lang1033\fs24  pateris in hoc seculo\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 si ita est, si certum habes, si perpensum est, si exploratum est, aufer iniquitatem, crimen remoue a te\plain \f1\lang1033\fs24  (PL 83, 827B-837A). \endash  (128\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De subitanea morte\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24 Spiritus, qui ad peccandum succendit, peccantem sepe subito rapit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 antequam tartara me rapiant\plain \f1\lang1033\fs24  (PL 83, 838C-841C). \endash  (128\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De verissima penitencia\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Flete me, celum et terra\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 audi vocem peccatoris clamantis\plain \f1\lang1033\fs24  (PL 83, 842A-843C). \endash  (129\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 De fornicatione\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De oracione\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De visu\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De humilitate\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De timore\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De odio\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  (129\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De inuidia\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De vana gloria\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De vano sermone\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Item vanus sermo cito polluit mentem \plain \f1\i\lang1033\fs24 et facile agitur quod libenter auditur\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 i\plain \f1\i\lang1033\fs24 n malis autem promissis rescinde fidem, in turpi voto muta decretum\plain \f1\lang1033\fs24  (PL 83, 856A-858C). \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Explicit de soliloquio Ysidori\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: PL 83, 825-868C. \endash  Edition: CCL 111B, S. 5-147. \endash  Lit.: \plain \f1\scaps\lang1033\fs20\cf1 D\u237 \'edaz y D\u237 \'edaz\plain \f1\lang1033\fs20\cf1 , Index, S. 31 Nr. \plain \f1\lang1033\fs20 105; \plain \f1\lang1033\fs20\cf1 CPL \plain \f1\lang1033\fs20\chcbpat8 1203\plain \f1\lang1033\fs20 ; CPPM IIB, 3425.}

