\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 50\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Versus de festis mobilibus 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 per istos uersus sequentes \u8230 \'85 celebrantur V mobiles festiuitates in qualibet anno\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Ad sextum decimum numerum quinto\plain \f1\lang1033\fs24\cf1  (!)\plain \f1\i\lang1033\fs24\cf1  dato primum\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 viginti sex dato trinis\plain \f1\lang1033\fs24\cf1  (19 Verse). \u220 \'dcber den Versen die zugeh\u246 \'f6rige Erl\u228 \'e4uterung: \plain \f1\i\lang1033\fs24\cf1 Ad sextum decimum etc. Expositio istorum uersuum talis est: Isti XIX uersus deseruiunt XIX annis cicli solaris\plain \f1\lang1033\fs24\cf1  \u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secundus uersus continens numeros ad inueniendum V festiuitates mobiles\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Sexdecim / sex / viginti que/ ter octo/ bis et sex\plain \f1\lang1033\fs24\cf1  \u8230 \'85 (f\u252 \'fcnf Spalten, vier Zeilen).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\super\scaps\lang1033\fs20 1\plain \f1\scaps\lang1033\fs20 Schaller/K\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 nsgen\plain \f1\lang1033\fs20  208. Alfred \plain \f1\scaps\lang1033\fs20 Cord\plain \f1\scaps\lang1033\fs20 ol\plain \f1\scaps\lang1033\fs20 i\plain \f1\scaps\lang1033\fs20 ani\plain \f1\lang1033\fs20 , Contribution \u224 \'e0 la litt\u233 \'e9rature du comput eccl\u233 \'e9siastique au Moyen \u194 \'c2ge, in: Studi medievali 3, 2 (1961), S. 169-208, hier S. 182. \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 Nicht nachweisbar.}

