\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 60\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -63\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Missa de corpore Christi
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Im Kopfsteg: \plain \f1\i\lang1033\fs24 Sancti spiritus assit nobis gratia\plain \f1\lang1033\fs24 . \endash  In.: \plain \f1\i\lang1033\fs24 Panem de celo\plain \f1\lang1033\fs24  (Cantus g02537); InV: \plain \f1\i\lang1033\fs24 Omnes gentes plaudite\plain \f1\lang1033\fs24  (Cantus g01079c; Usuarium g01963; vgl. GW M24660 = BSB-Ink M-452, Bl. 124\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24 Gloria patri\plain \f1\lang1033\fs24 ; Co.: \plain \f1\i\lang1033\fs24 Da, quesumus, misericors deus\plain \f1\lang1033\fs24  (Usuarium: GW M24355 = BSB-Ink M-433, Bl. 112\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24 Quicumque\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Epistola et ewangelium ut in die sancto\plain \f1\lang1033\fs24 ; Gr.: \plain \f1\i\lang1033\fs24 Caro mea vere est cibus\plain \f1\lang1033\fs24  (Cantus g02538); GrV: \plain \f1\i\lang1033\fs24 Qui manducat meam carnem\plain \f1\lang1033\fs24  (Cantus g02273.1); Al.: \plain \f1\i\lang1033\fs24 O Ihesu, pastor pie\plain \f1\lang1033\fs24  (Cantus g02559); Sq.: *\plain \f1\i\lang1033\fs24 Salue corpus\plain \f1\lang1033\fs24  (s. 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ); Of.: \plain \f1\i\lang1033\fs24 Celeste sacrificium\plain \f1\lang1033\fs24  (Cantus g02539); \plain \f1\i\lang1033\fs24 Sequitur secretum\plain \f1\lang1033\fs24  (60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Sec.: \plain \f1\i\lang1033\fs24 Clementissime saluator mundi, domine Ihesu Christe, qui te salutis hostiam\plain \f1\lang1033\fs24  (Usuarium: GW M24355 = BSB-Ink M-433, Bl. 112\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); Cm.: \plain \f1\i\lang1033\fs24 Repleti corporis Christi et sanguinis misteriis\plain \f1\lang1033\fs24  (Cantus g02560); Pc.: \plain \f1\i\lang1033\fs24 Corporis sacri et pretiosi sanguinis tui sumpta misteria\plain \f1\lang1033\fs24  (Usuarium: GW M24355 = BSB-Ink M-433, Bl. 112\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24 Secuntur alique sequentie\plain \f1\lang1033\fs24 . Sq.: \plain \f1\i\lang1033\fs24 Salue corpus, vas dilectum\plain \f1\lang1033\fs24  (AH 9, S. 37f. Nr. 44); (62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) H.: \plain \f1\i\lang1033\fs24 Aue panis dulcissime\plain \f1\lang1033\fs24  (AH 54, S. 259f. Nr. 169); (62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) H.: \plain \f1\i\lang1033\fs24 Ave, caro Christi regis veneranda\plain \f1\lang1033\fs24  (AH 54, S. 261 Nr. 170); Tc.: \plain \f1\i\lang1033\fs24 Laudate dominum omnes gentes\plain \f1\lang1033\fs24  (Cantus g00715); \plain \f1\i\lang1033\fs24 Alia oratio de corpore Christi\plain \f1\lang1033\fs24 . Or.: \plain \f1\i\lang1033\fs24 Deus, qui gloriosum corporis et sanguinis domini nostri Ihesu Christi misterium nobiscum manere voluisti\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Lambot\plain \f1\lang1033\fs24 /\plain \f1\scaps\lang1033\fs24 Fransen\plain \f1\lang1033\fs24 , S. 97 Nr. 17); (63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Sec.: \plain \f1\i\lang1033\fs24 Ipse tibi, domine sancte\plain \f1\lang1033\fs24  (Usuarium 1956; \plain \f1\scaps\lang1033\fs24 Lambot\plain \f1\lang1033\fs24 /\plain \f1\scaps\lang1033\fs24 Fransen\plain \f1\lang1033\fs24 , S. 97 Nr. 18); Co.: \plain \f1\i\lang1033\fs24 Refecti vitalibus alimentis\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Lambot\plain \f1\lang1033\fs24 /\plain \f1\scaps\lang1033\fs24 Fransen\plain \f1\lang1033\fs24 , S. 97 Nr. 19); Cm.: \plain \f1\i\lang1033\fs24 Item communio. Quocienscumque manducabitis\plain \f1\lang1033\fs24  (Cantus 503001; Usuarium g01132).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Abk\u252 \'fcrzungen f\u252 \'fcr die liturgischen Gattungen nach der Cantus-Datenbank (https://cantus.uwaterloo.ca/genre). \endash  Siglen: Cantus s. Abk\u252 \'fcrzungsverzeichnis; \plain \f1\scaps\lang1033\fs20 Lambot\plain \f1\lang1033\fs20 /\plain \f1\scaps\lang1033\fs20 Fransen\plain \f1\lang1033\fs20  = L'office de la F\u234 \'eate-Dieu primitive. Textes et m\u233 \'e9lodies retrouv\u233 \'e9s, ed. Cyril \plain \f1\scaps\lang1033\fs20 Lambot\plain \f1\lang1033\fs20  / Paul-Ir\u233 \'e9n\u233 \'e9e \plain \f1\scaps\lang1033\fs20 Fransen\plain \f1\lang1033\fs20 . Maredsous 1946; Usuarium = A Digital Library and Database for the Study of Latin Liturgical History in the Middle Ages and Early Modern Period (https://usuarium.elte.hu/).}

