\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 63\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -65\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes ante eucharistiam VI
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 [Ad patrem] \plain \f1\i\lang1033\fs24 Domine, sancte pater, omnipotens eterne deus, qui vnigenitum tuum misisti in mundum, vt carne sua nos cibaret\plain \f1\lang1033\fs24  \u8230 \'85 \endash  Weitere Gebete (Initien s. Register): \plain \f1\i\lang1033\fs24 Ad filium\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad spiritum sanctum\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad sanctam trinitatem\plain \f1\lang1033\fs24 ; (64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad sanctam Mariam virginem\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Item alia oratio ad Beatam Mariam virginem\plain \f1\lang1033\fs24 ; (64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad angelos sanctos\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad patriarchas et prophetas\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad apostolos et ewangelistas\plain \f1\lang1033\fs24 ; (65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad martiros\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad confessores\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ad virgines\plain \f1\lang1033\fs24 ; (65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad omnes sanctos\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: San Marino, Huntington Library, HM 1176, 117\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -120\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; vgl. Guide to Medieval and Renaissance Manuscripts in the Huntington Library, ed. Consuelo Wager \plain \f1\scaps\lang1033\fs20 Dutschke\plain \f1\lang1033\fs20 . Bde. 1-2. San Marino (California) 1989, hier Bd. 2, S. 532f.}

