\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 75\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -79\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Collectae ad horas de passione domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift im Kopfschnitt, beschnitten: [\u8230 \'85] \plain \f1\i\lang1033\fs24 de passione ordo\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Ad primam\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, princeps omnium regum terre, qui pro nobis hora diei prima contumeliose ad instar latronis Pilato presentari\plain \f1\lang1033\fs24  \u8230 \'85 \endash  Weitere Gebete (Initien s. Register): \plain \f1\i\lang1033\fs24 Ad tertiam\plain \f1\lang1033\fs24 ; (76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad sextam\plain \f1\lang1033\fs24 ; (76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad nonas\plain \f1\lang1033\fs24 ; (77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad vesperas secundas\plain \f1\lang1033\fs24 ; (77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad completorium\plain \f1\lang1033\fs24 ; (78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Iterum in primis vesperis\plain \f1\lang1033\fs24 ; (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Iterum ad completorium\plain \f1\lang1033\fs24 ; (79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad matutinas\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: Mainz, StB, Hs I 290, 105\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -111\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; Weimar, HAAB, Oct 52, 188\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -191\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; Oct 62, 126\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -132\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

