\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 85\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -92\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Meditatio passionis domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Ad dignam et fructuosam misse celebracionem seu alias sacre eucaristie sumpcionem omnino prehibenda est a quolibet sacerdote et fideli christiano devota\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 pro tua ergo amarissima passione et morte, domine Jhesu Christe, fili dei viui\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . \endash  Anschlie\u223 \'dfend Gebete und Bibelstellen zur Passion Christi: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Oratio bona de passione domini\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 O domine Ihesu Christe, fili dei viui, qui pro redempcione mundi voluisti circumcidi et a iudeis reprobari\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quo tecum perduxisti latronem crucifixum, te deum viuum confitentem\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 Amen\plain \f1\lang1033\fs24\chcbpat8 . \endash  \plain \f1\super\lang1033\fs24\chcbpat8 3\plain \f1\lang1033\fs24\chcbpat8 (93\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 V\plain \f1\i\lang1033\fs24 ere filius dei erat iste \plain \f1\lang1033\fs24 (Mt 27,54); Lc 23,42; Ps 21,19; (93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Mt 8,20 / Lc 9,58; Ps 21,18; Is 1,6; Lam 1,12. \endash  \plain \f1\super\lang1033\fs24\chcbpat8 4\plain \f1\lang1033\fs24\chcbpat8 (93\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Tenebre facte sunt, dum crucifixissent Ihesum iudei\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 et omnis \plain \f1\i\lang1033\fs24 terra tremuit\plain \f1\lang1033\fs24  (vgl. Mt 27,45ff., Mc 15,33ff., Lc 23,44ff). \endash  \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24  \u8230 \'85 (beschnitten)\u8249 \'8b \plain \f1\i\lang1033\fs24 O domine Ihesu Christe, per illam amaritudinem, quam sustinuisti in cruce\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 6\plain \f1\i\lang1033\fs24 Aspice in me infelicem, pietas immensa, respice in me crudelissima \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 dele vniuersitatem criminum multitudinem\plain \f1\lang1033\fs24  (!, recte multitudine) \plain \f1\i\lang1033\fs24 misericordiarum tuarum Amen. Hec Augustinus cum flexis genibus\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 (Nr. 1) Parallel\u252 \'fcberlieferung: Augsburg, SuStB, 8\u176 \'b0 Cod. 116, 190\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -197\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20\cf1 . \endash  (Nr. 6) \plain \f1\lang1033\fs20 Ps.-Augustinus, Sermo 117, ed. PL 39, 1977.}

