\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 96\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -104\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Psalterium Iesu
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Prologus in subiectum opusculum elaboratum. Rithmis et sensu uerborum consociatum\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Psalterium Ihesu, sic est opus hoc vocatum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 Edidit hoc carmen quidam monachus Griseorum\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Ad laudem domini Ihesu studiumque bonorum\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (AH 35, S. 52). \endash  (97\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24 Ave, Ihesu, beatorum spes et salus miserorum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 Aue, Ihesu bonus | Suaue cordis mei onus | Angelorum tibi pronus | Digne plaudit dulce sonus\plain \f1\lang1033\fs24  (AH 35, S. 44-51 Nr. 3).}

