\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 37\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -41\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Bonaventura: Instructio sacerdotis ad se praeparandum ad celebrandam missam
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Capitulum septimum decimum de condicionibus missarum celebracione. Bonauentura in stimulo amoris\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ad missam celebrandam sex considero accidencia. Primum est rationis discrecio respectu veritatis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 \u8230 \'85 sed sicut cogitat bene, sic eciam opus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 adimpleat, quid nobis concedat\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: Bonaventura, Opera omnia 12, ed. Adolphe Charles \plain \f1\scaps\lang1033\fs20 Peltier\plain \f1\lang1033\fs20 . Paris 1868, S. 288a-290a. \endash  Lit.: \plain \f1\scaps\lang1033\fs20\cf1 Glorieux\plain \f1\lang1033\fs20\cf1 , R\u233 \'e9pertoire 2, S. 48 Nr. 305cw\plain \f1\lang1033\fs20 ; \plain \f1\scaps\lang1033\fs20\cf1 Distelbrink, \plain \f1\lang1033\fs20\cf1 Bonaventurae scripta, S. 146 Nr. 146\plain \f1\lang1033\fs20 .}

