\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 67\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -74\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 De sacerdote
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Im Fu\u223 \'dfsteg: \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De sacerdotibus per negligenciam non celebrantibus\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24 Sacerdos qui legittimum non habet impedimentum, quando se valeat disponere ad celebrandam missam vel qui sibi ipsi inpedimentum fecerit sine magna et vtili et neccessaria causa ewangelicum preceptum primum \plain \f1\lang1033\fs24\chcbpat8 \u8218 \'82\plain \f1\i\lang1033\fs24 Querite regnum dei\plain \f1\lang1033\fs24\chcbpat8 \lquote \plain \f1\i\lang1033\fs24  et omnium doctorum katholicorum et sanctorum virorum ac patrum consilia dicencium operi dei nil fore preponendi\plain \f1\lang1033\fs24  \u8230 \'85 \endash  Mit den Kapitel\u252 \'fcberschriften: \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sacerdos negligens\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; (67\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Peccatores mortales\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Peccatores veniales\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; (68\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Peccatores letales\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Qui temptantur\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; (68\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Justi merita\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sancti in patria\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Angeli beati\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; (69\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Dyabolum\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Deus omnium\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  (73\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) expl.:\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 unde beatus Augustinus dicit sustinere penam: Inde Christum tradentis et Pylati ipsum dampnantis, quam sacerdotis indigne consecrantis, a quo nos triste dicit: Jesus Christus, virginis filius. In secula seculorum semper benedictus. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: Wolfenb\u252 \'fcttel, HAB, Cod. Guelf. 19.29 Aug. 4\u176 \'b0, 40\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -42\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (dort Matthaeus Cracoviensis zugewiesen).}

