\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 98\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -106\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Benedictus de Nursia: Regula
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Im Kopfsteg: \u8250 \'9b\plain \f1\i\lang1033\fs24 Registrum Regule Sancti Benedicti\plain \f1\lang1033\fs24 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24 Abbas diligenter cogitet quid sit\plain \f1\lang1033\fs24   \u8250 \'9b\plain \f1\i\lang1033\fs24 2\plain \f1\lang1033\fs24 \u8249 \'8b; \plain \f1\i\lang1033\fs24 Abbas Christi nomine est appellandus\plain \f1\lang1033\fs24   \u8250 \'9b\plain \f1\i\lang1033\fs24 63\plain \f1\lang1033\fs24 \u8249 \'8b; (98\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) im Kopfsteg: \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 1452\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; (106\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24 Zelus bonus et malus vel amarus\plain \f1\lang1033\fs24   \u8250 \'9b\plain \f1\i\lang1033\fs24 42\plain \f1\lang1033\fs24 \u8249 \'8b \endash  \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Explicit registrum Regule 1452\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b.
