\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 207\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -209\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Defensor Locogiacensis: Liber scintillarum (Exz.)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Capitulum xl\plain \f1\i\super\lang1033\fs24 m\plain \f1\i\lang1033\fs24  ex scintillario de monachis 28\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Dominus dicit in Ewangelio: Cum uoveris votum domino deo tuo, non tardabis reddere\plain \f1\lang1033\fs24  \u8230 \'85 (Dt 23,21) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sic tinea exterminat vestimentum, sic detractio animam monachi\plain \f1\lang1033\fs24  (CCL 117, ed. Henri \plain \f1\scaps\lang1033\fs24 Rochais\plain \f1\lang1033\fs24 , S. 149-152). \endash  209\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 211\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Nicolaus de Dinkelspuhel: Lectura Mellicensis (Exz.)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Vtrum mali possit conferre sacramentum baptismi et eciam rem sacramenti. Arguitur quod non, quia dicit Ambrosius et ponitur prima questione primo articulo, \plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 baptismus\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\i\lang1033\fs24  non sana baptismus \plain \f1\lang1033\fs24 (mit Verweisungszeichen zur Wortumstellung)\plain \f1\i\lang1033\fs24  perfidi omnino mundat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 per quos waptizatur, igitur mali sacramentum conferre non possent et a forciori nec rem sacramenti\plain \f1\lang1033\fs24  (vgl.\plain \f1\lang1033\fs22  \plain \f1\scaps\lang1033\fs24 Madre\plain \f1\lang1033\fs24 , S. 101 Nr. 27). \endash  212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 216\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -228\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Henricus Egher de Kalkar: Informatio meditationis de passione domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Deuotissima contemplacio passionis Ihesu Christi\plain \f1\lang1033\fs24 \u8249 \'8b Prolog: \plain \f1\i\lang1033\fs24 In Deuteronomio legitur, quod, cum sanctus Moyses\plain \f1\lang1033\fs24  (mit Verweisungszeichen zur Wortumstellung)\plain \f1\i\lang1033\fs24  daret populo precepta legis, dixit: Meditaberis in eis sedens in domo tua\plain \f1\lang1033\fs24  (Dt 6,7) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et debet omnes sensus suos in huiusmodi meditacione salutifera occupare\plain \f1\lang1033\fs24  (Ed. S. 71 Z. 5-27). \endash  (Z. 22) \plain \f1\i\lang1033\fs24 Igitur peracto completorio, reuoluat deuotus homo in animo suo quibus cogitacionibus, rebus, operibus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et habeas quasi in cordis tui sarcophago tumulatum ipsum dilectum dominum Ihesum, deum tuum, cui cum patre\plain \f1\lang1033\fs24  \u8230 \'85 (Ed. S. 72 Z. 30-S. 83 Z. 423). \endash  (225\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 6) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Auxilientur mihi, domine Ihesu Christe, filii dei uiui, omnes passiones tue et defendant me ab omni tribulacione\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ideo de hac immensa pietate confisus, precor te per omnes tuas piissimas passiones, ut benigne protegas me semper auxilio et continua pietate conseruabor. Qui cum domino patre finitus in vigilia pasche 1453 in Castello per fratrem Fridericum professum monasterii S. Emmerami in Ratispona et eiusdem dyocesis. Et dicitur Formula devote meditandi passionem domini nostri Ihesu Christi etc. Item sequitur de aliis bonis meditacionibus, scilicet de passione et resurrectione et ascensione\plain \f1\lang1033\fs24 . \endash  (225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De resurrectione et ascensione dominico dei\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Die dominico cogita de resurrectione domini nostri Ihesu Christi. Et primo debes deo patri congloriari et congratulari, qui dilectum filium suum in carne assumpta\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui tamen omni tempore in hora querendus est digne. Dominus noster Ihesus Christus, qui cum patre et spiritu sancto vivit et regnat in secula seculorum. Amen\plain \f1\lang1033\fs24  (Ed. S. 83 Z. 424-S. 88 Z. 573). \plain \f1\i\lang1033\fs24 Et sic finitur 1453 secunda feria pasche\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Edition und Lit.: Henri \plain \f1\scaps\lang1033\fs20 Lindeman\plain \f1\lang1033\fs20 , Een Tractaat over de overweging van\rquote s Heeren lijden aan Hendrik von Calcar toegeschreven, in: Ons geestelijk erf 7 (1933), S. 62-88, Edition S. 71-88, zu Werk und \u220 \'dcberlieferung S. 62-70; Heinrich \plain \f1\scaps\lang1033\fs20 R\u252 \'fc\plain \f1\scaps\lang1033\fs20 thing\plain \f1\lang1033\fs20 , Der Kart\u228 \'e4user Heinrich Egher von Kalkar 1328-1408. G\u246 \'f6ttingen 1967 (Studien zur Germania Sacra 8), S. 108-112; \plain \f1\scaps\lang1033\fs20 Ders\plain \f1\lang1033\fs20 ., in: \u178 \'b2VL 2 (1980), Sp. 379-384, hier Sp. 382; CALMA 5 (2017), S. 387f. Nr. 19. \endash  Der Abschnitt auf 225\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -228\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  geh\u246 \'f6rt nach der Edition zur Informatio, wird aber hier gesondert aufgef\u252 \'fchrt.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Verdana;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 229\plain \f1\super\lang1033\fs24\cf1 rv\plain \f2\lang1033\fs18\cf1  \plain \f1\b\lang1033\fs24\cf1 Henricus Egher de Kalkar (?): Exercitatorium monachorum (Exz.)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Ante missam\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si autem oblaturus fueris, prosterne mentem tuam ante dominum Ihesum tractans mente uel voce talia: O mi domine, accedam ad mensam tuam\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 et nobis hic ambulantibus pro uiatico spem, fidem et caritatem et finaliter vitam sempiternam. Hec ex libello de puritate, quomodo doleat homo, ut purgetur a peccatis. 1453 dominica Misericordia domini in Castello\plain \f1\lang1033\fs24\chcbpat8 . \endash  230\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 -231\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Edition: Karl \plain \f1\scaps\lang1033\fs20 Hirsche\plain \f1\lang1033\fs20 , Prolegomena zu einer neuen Ausgabe der Imitatio Christi nach dem Autograph des Thomas von Kempen. Bd. 1. Berlin 1873, cap. 6-7, S. 492-483 Z. 19. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 R\u252 \'fcthing\plain \f1\lang1033\fs20 , Heinrich Egher von Kalkar (wie oben 216\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), S. 150-154; \plain \f1\scaps\lang1033\fs20\cf1 Bloomfield \plain \f1\lang1033\fs20\cf1 (mit Supplement)\plain \f1\lang1033\fs20  6533.}

