\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 II (Bl. 82-113)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 82\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 -105\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\b\lang1033\fs24\chcbpat8 Sermones de tempore (T1-T56)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 [C]\plain \f1\i\lang1033\fs24 vm appropinquasset Ihesus\plain \f1\lang1033\fs24  (Mt 21,1). \plain \f1\i\lang1033\fs24 Nota, quod quinque ponuntur in hoc ewangelio, primus ad incarnandum motiua scilicet misericordia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui posset esse fideiussor noster pro nobis nisi dominus. Ecclesiasticus xli\u176 \'b0: Graciam fideiussoris tui ne obliuiscaris\plain \f1\lang1033\fs24  (Sir 29,20). \endash  (82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 1; (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 2-4; (83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 5; (84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 6-7; (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 8-9; (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 10; (85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 11-12; (86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 13-15; (86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 16-17; (87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 18; (87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 19-20; (88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 21-22; (88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 23-25; (89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 26-27; (89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 28-29; (90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 30; (90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 31-32; (91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 33-34; (91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 35; (92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 36; (92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 37-38; (93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 39; (93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 40; (94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 41-42; (94\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 43; (95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 44-45; (95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 46-47; (96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 48-49; (96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 50; (97\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 51; (97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 52; (98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 53; (98\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 54; (99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 55-57; (99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 58; (100\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 59-60; (100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 61-62; (101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 63; (101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 64-65; (102\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 66; (102\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 67; (103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 68-69; (103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 70; (104\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 71-72; (104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 73-74; (105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Nr. 75-76. \endash  (105\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Nr. 77: \plain \f1\i\lang1033\fs24 Erat quidam regulus\plain \f1\lang1033\fs24  (Jo 4,46). \plain \f1\i\lang1033\fs24 Nota quod peccator comparatur febricitanti propter vii, primo quia appetit sua contraria\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 in tempore placito exaudiui te et in die salutis adiuui te\plain \f1\lang1033\fs24  (Is 49,8).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20\cf1 Vorliegende Sammlung umfasst 78 Kurzpredigten. Die Hs. ist bei \plain \f1\scaps\lang1033\fs20\cf1 Schneyer\plain \f1\lang1033\fs20\cf1 , Rep. 8, S. 698-702, ohne Ber\u252 \'fccksichtigung der ersten Predigt ausgewertet worden. Die Nummern beziehen sich auf Schneyer, wobei die erste Predigt ungez\u228 \'e4hlt bleibt. \endash  Weitere P\plain \f1\lang1033\fs20 arallel\u252 \'fcberlieferung:\plain \f1\lang1033\fs20\cf1  Clm 2717, 226\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -244\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1  (s. \plain \f1\scaps\lang1033\fs20\cf1 Schneyer\plain \f1\lang1033\fs20\cf1 , Rep. 8, S. 586-590);\plain \f1\lang1033\fs20  Kremsm\u252 \'fcnster, StiftsB, CC 286, 91\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -110\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

