\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 38\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -39\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Jacobus de Voragine: De sancto Benedicto
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24 De sancto Benedicto de nomine\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Benedictus dictus est uel quia multa benedixit, vel in hac vita multas benedictiones habuit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ut ab illo montis cacumine vsque ad inferiora descendebat et sic de singulis\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Edition: \plain \f1\scaps\lang1033\fs20 Graesse\plain \f1\lang1033\fs20 , S. 204-206 Z. 25\plain \f1\lang1033\fs20\chcbpat8 ; \plain \f1\super\lang1033\fs20 2\plain \f1\scaps\lang1033\fs20 Maggioni\plain \f1\lang1033\fs20 , Bd. 1, S. 309.1-312.47.}

