\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 91\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 -93\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Miracula sanctae Catharinae virginis et martyris
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u220 \'dcberschrift: \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Miraculum de sancta Katharina\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24 Katharine virginis. Quidam monachus Rotomagensis ad montem Syna\plain \f1\lang1033\fs24\chcbpat8 [i]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 perrexit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ad suum monasterium deportauit. Hoc ualet ad instanciam orationis et deuocionem\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Mairhofer\plain \f1\lang1033\fs24 , S. 159 Nr. 262; vgl. auch Alphabetum narrationum Nr. 430, s. 93\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). \endash  (Z. 11) \plain \f1\i\lang1033\fs24 Katharina faciem suam velauit ab eo, qui illam cognoscere non voluit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 coram te velata facie pertransiuit\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Mairhofer\plain \f1\lang1033\fs24 , S. 159 Nr. 263; vgl. auch Alphabetum narrationum Nr. 431). \endash  (92\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De sancta Katharina\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24 Katharine\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Adolescens bone indolis, filius cuiusdam clarissimi comitis, patre quidam orbatus \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 tandem tricesimo anno post hec comes et comitissa bonis operibus pleni ad regna celestia migrauerunt \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 Mairhofer\plain \f1\lang1033\fs24 , S. 159f. Nr. 264). \endash  (93\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancta Katharina\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Katharine virginis. Venerabilis quidam sacerdos maioris barrochiae\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 in Traiecto beate Ka\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 tharine\plain \f1\lang1033\fs24\chcbpat8 ] \plain \f1\i\lang1033\fs24\chcbpat8 deuotus\plain \f1\i\lang1033\fs24  singulis annis eius festa sollempniter celebrabat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui sui deuoti substanciam stupendo miraculo dignata est custodire\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Mairhofer\plain \f1\lang1033\fs24 , S. 160 Nr. 266).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Lit.: Daniela E. \plain \f1\scaps\lang1033\fs20 Mairhofer\plain \f1\lang1033\fs20 , Liber lacteus. Eine unbeachtete Mirakel- und Exempelsammlung aus dem Zisterzienserkloster Stams (Innsbruck, ULB, Cod. 494). Badenweiler 2009 (Codicologia 1), dort jeweils mit Nachweis weiterer Literatur.}

