\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 93\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 -102\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Arnoldus Leodiensis: Alphabetum narrationum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De usurariis\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Usurarius\plain \f1\lang1033\fs24\chcbpat8 . \plain \f1\i\lang1033\fs24\chcbpat8 Usurarii pena aliquando visibiliter demonstratur. Cesarius. \plain \f1\i\lang1033\fs24 In ciuitate Metensis\plain \f1\lang1033\fs24  (!, recte Metensi) \plain \f1\i\lang1033\fs24 defunctus est vsurarius auarus nimis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 terram reicientes fugerunt. Hoc etiam valet ad penam et dampnacionem \plain \f1\lang1033\fs24 (Nr. 803); (94\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 804. \endash  (94\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De morte\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 528; \plain \f1\lang1033\fs24 (94\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 529; (94\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 530; (94\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Nr. 531; (94\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Nr. 532; (95\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 533; (95\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 534; \plain \f1\lang1033\fs24\chcbpat8 (95\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 535. \endash  (95\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) [De muliere] N\plain \f1\lang1033\fs24 r. 536; Nr. 541; \plain \f1\lang1033\fs24\chcbpat8 (95\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 542; Nr. 544. \endash  (96\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) [De iustitia] Nr. 427. \endash  (96\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) [De iuventute] Nr. 428. \endash  (96\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) [De compassione] Nr. 168. \endash  (97\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Concordia multum\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 169. \endash  (97\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) [De concupiscentia] Nr. 170. \endash  (97\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) [De confessione] Nr. 171; Nr. 172; (97\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 173; (98\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 174; (98\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De confessione\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 176; (98\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 177; (98\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 178; (99\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 179. \endash  (99\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De furibus\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 338. \endash  (99\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De fur\plain \f1\lang1033\fs24\chcbpat8 [to]\u8249 \'8b Nr. 341. \endash  (99\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) [De cogitatione] Nr. 152; (100\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De cogitacionibus\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 153; (100\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 154; (100\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 156. \endash  (100\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) [De columba] Nr. 157. \endash  (101\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) [De commendatione] Nr. 158. \endash  (101\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De communicacione\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 161; (101\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) Nr. 162. \endash  (102\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De sepultura\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Nr. 720; Nr. 721. \endash  (102\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 ) [De delicia] Nr. 243; Nr. 244. \endash  (102\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Versus: Clericus anulatus aut fatuus aut prelatus vnde versus: Vadit gemmatus bene quilibet inveteratus\plain \f1\lang1033\fs24\chcbpat8  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 19964, nach dieser Hs.).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Edition: Arnoldi Leodiensis alphabetum narrationum, ed. Elisa \plain \f1\scaps\lang1033\fs20 Brilli\plain \f1\lang1033\fs20 . Turnhout 2015 (CCCM 160).}

