\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 2\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -54\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Silvester von Rebdorf: Meditationes de passione domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Prologus in passionem domini\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Uidens vidisti, domine, affliccionem populi tui\plain \f1\lang1033\fs24  \u8230 \'85 (vgl. Ex 3,7; Act 7,34). \plain \f1\i\lang1033\fs24 Nunc, domine, passionis tue dies vrgere nos magis deberent\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 in te totaliter igniculus amoris\plain \f1\lang1033\fs24  (Ed.: \plain \f1\scaps\lang1033\fs24 H\u246 \'f6cherl\plain \f1\lang1033\fs24 , S. 15-23 Z. 9) \endash  (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Passionem domini in octo partes diuidam, quia completorium bis ponam, videlicet in principio et in fine\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 hic est calix sanguinis mei\plain \f1\lang1033\fs24  (Ed.: ebd. S. 25 Z. 8-24). \endash  (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Contemplacio\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 O clementissime deus et verissime animarum nostrarum amator Ihesu Christe\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 hoc ignorabant discipuli, ideo dormierunt\plain \f1\lang1033\fs24\chcbpat8  (Ed. ebd. S. 41 Z. 7-S. 79). \endash  (8\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Ad matutinas\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Feria secunda\plain \f1\lang1033\fs24\chcbpat8 . \plain \f1\i\lang1033\fs24\chcbpat8 Hora matutinali excitaberis a sompno\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quam pius et benignus est et plenus karitate\plain \f1\lang1033\fs24\chcbpat8  (Ed.: ebd. S. 79-117 Z. 25). \endash  (12\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Feria tertia. Primarum hora corde doloroso et mesto meditaberis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 si posset ipsum in vita conseruare\plain \f1\lang1033\fs24\chcbpat8  (Ed. ebd. S. 117 Z. 26-S. 141 Z. 12). \endash  (17\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Ad tertias\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Ad tercias cogitabis mestus et tristis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 de quibus omnibus grati esse debemus\plain \f1\lang1033\fs24\chcbpat8  (Ed. ebd. S. 141 Z. 13-S. 171 Z. 25). \endash  (22\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Ad sextas\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Ad sextas autem cogitabis lacrimosis oculis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 et dilaceratus pependit ante te. Ihesus Christus\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 (Ed. ebd. S. 171 Z. 27-S. 225). \endash  (32\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Hora autem nona mente lugubri et deuota\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quia tota uirtus eius pendet ex te, qui cum patre\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 (Ed. ebd. S. 227-307 Z. 22). \endash  (44\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Uesperorum\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 autem hora cogitabis plenus lacrimis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 et castissimis amplexibus dulcissimi dei nostri in celesti patria. Amen\plain \f1\lang1033\fs24\chcbpat8  (Ed. ebd. S. 309 Z. 4-S. 333). \endash  (49\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 Circa secundum completorium cogitabis tristis et dolens\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 qui amore mei nudus et dilaceratus perpendit ante te Ihesus Christus, filius tuus, qui est benedictus in seculorum secula. Amen\plain \f1\lang1033\fs24\chcbpat8  (Ed. ebd. S. 335-359).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Wohl erheblich gek\u252 \'fcrzte Fassung. \endash  Edition (nach Clm 4692, 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -76\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 ): Josef \plain \f1\scaps\lang1033\fs20 H\u246 \'f6cherl\plain \f1\lang1033\fs20 , Die Passionsmeditationen des Rebdorfer Propstes Silvester. Birkeneck 2002. \endash  Lit.: \plain \f1\scaps\lang1033\fs20\cf1 Zumkeller\plain \f1\lang1033\fs20\cf1 , S. 406 Nr. 876; S. 606 Nr. 646d\plain \f1\lang1033\fs20 ; Ernst \plain \f1\scaps\lang1033\fs20 Reiter\plain \f1\lang1033\fs20 , Domus s. Johannes Baptistae in Rebdorp (Rebdorf), in: Monasticon Windeshemense. Bd. 2: Deutsches Sprachgebiet, hrsg. von Wilhelm \plain \f1\scaps\lang1033\fs20 Kohl\plain \f1\lang1033\fs20  / Ernest \plain \f1\scaps\lang1033\fs20 Persoons\plain \f1\lang1033\fs20  / Anton G. \plain \f1\scaps\lang1033\fs20 Weiler\plain \f1\lang1033\fs20 . Br\u252 \'fcssel 1977 (Archives et biblioth\u232 \'e8ques de Belgique 16,2), S. 340-362, hier S. 351, 359, 361; \plain \f1\lang1033\fs20\cf1 Karin \plain \f1\scaps\lang1033\fs20\cf1 Schneider\plain \f1\lang1033\fs20\cf1 , in: \u178 \'b2VL 8 (1992), Sp. 1248-1253, hier 1250f.; \plain \f1\lang1033\fs20 Josef \plain \f1\scaps\lang1033\fs20 H\u246 \'f6cherl\plain \f1\lang1033\fs20 , Rebdorfs Kanoniker der Windesheimer Zeit 1458-1853. Eichst\u228 \'e4tt 1992 (Sammelblatt des Historischen Vereins Eichst\u228 \'e4tt 85), S. 33 Nr. 002.}

