\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 111\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Schemata zum Wahl-, Kr\u246 \'f6nungs- und Salbungsrecht
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Maguntinensis archicancellarius tocius Germanie \plain \f1\lang1033\fs24 \u8230 \'85 (vgl. \plain \f1\scaps\lang1033\fs24 Werminghoff\plain \f1\lang1033\fs24 , S. 382f.). \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\i\lang1033\fs24 Imperator debet coronari tribus coronis \plain \f1\lang1033\fs24 \u8230 \'85 (vgl. \plain \f1\scaps\lang1033\fs24 Werminghoff\plain \f1\lang1033\fs24 , S. 383f.). \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\i\lang1033\fs24 Hii reges coronantur et inunguntur\plain \f1\lang1033\fs24 : \endash  \plain \f1\i\lang1033\fs24 Rex Iherusalem et Sicilie\plain \f1\lang1033\fs24  \u8230 \'85 (vgl. \plain \f1\scaps\lang1033\fs24 Werminghoff\plain \f1\lang1033\fs24 , S. 385 Z. 1-3). \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\i\lang1033\fs24 Hii coronantur et \plain \f1\lang1033\fs24\chcbpat8 [non] \plain \f1\i\lang1033\fs24 inunguntur: Rex Armenie, Sorbie, Cipri, Vngarie, Boemie, Polonie \plain \f1\lang1033\fs24 \u8230 \'85 (vgl. \plain \f1\scaps\lang1033\fs24 Werminghoff\plain \f1\lang1033\fs24 , S. 384 Z. 4-10). \endash  \plain \f1\super\lang1033\fs24 5\plain \f1\i\lang1033\fs24 Hii sunt feudatarii Romane ecclesie: Rex Iherusalem et Sicilie, Arroganum, Sardinie, Vngarie, Anglie \plain \f1\lang1033\fs24 \u8230 \'85 (vgl. \plain \f1\scaps\lang1033\fs24 Werminghoff\plain \f1\lang1033\fs24 , S. 384 Z. 10-12). \endash  111\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 \u220 \'dcbersichten auf der Grundlage der Edition bei Albert \plain \f1\scaps\lang1033\fs20 Werminghoff\plain \f1\lang1033\fs20 , Ein Tractatus de coronatione imperii aus dem vierzehnten Jahrhundert, in: \plain \f1\scaps\lang1033\fs20\cf1 ZRG GA 24 (1903), S. 380-390\plain \f1\lang1033\fs20\chcbpat8\cf1 . \endash  Lit.: Franz-Heinz \plain \f1\scaps\lang1033\fs20\chcbpat8\cf1 Hye\plain \f1\lang1033\fs20\chcbpat8\cf1 , Die \plain \f1\lang1033\fs20 \u8218 \'82\plain \f1\lang1033\fs20\chcbpat8\cf1 f\u252 \'fcnf gesalbten K\u246 \'f6nige\plain \f1\lang1033\fs20 \lquote \plain \f1\lang1033\fs20\chcbpat8\cf1 . Ein staatstheoretischer Begriff des Sp\u228 \'e4tmittelalters, in: \plain \f1\lang1033\fs20 Kirche und Staat in Idee und Geschichte des Abendlandes. Festschrift zum 70. Geburtstag von Ferdinand Maass, hrsg. von Wilhelm \plain \f1\scaps\lang1033\fs20 Baum\plain \f1\lang1033\fs20 . Wien/M\u252 \'fcnchen 1973, S. 113-119.}

