\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 126\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -127\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Gregorius Magnus: Homiliae in evangelia (lib. 2, homilia 34)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Rem, fratres, breuiter refero, quam uiro uenerabili Maximiano tunc patre monasterii mei\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quia advocatus noster factus est iudex noster, qui viuit et regnat cum patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24  (PL 76, 1257C-1259A; CCL 141, ed. Raymond \plain \f1\scaps\lang1033\fs24 Etaix\plain \f1\lang1033\fs24 , \u167 \'a7 18, S. 317 Z. 476-S. 318 Z. 522).}

