\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 129\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -130\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Carmen de cella
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 De cella metra, que ascribuntur beato Thome. In cella stantes cur veniamus huc meditantes\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 Hoc pater, hoc flamen, hoc filius annuat. Amen\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 8844).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Emmeramer Parallel\u252 \'fcberlieferung: Clm 14634, 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

