\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 131\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Schemata
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Septem sunt dotes, quibus beatificatur imperialis\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 ecclesia militans: Claritas, agilitas, impassibilitas, subtilitas \plain \f1\lang1033\fs24 = \plain \f1\i\lang1033\fs24 dotes corporis\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 clara et aperta visio, firma tencio, beata\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 fruicio\plain \f1\lang1033\fs24  = \plain \f1\i\lang1033\fs24 dotes anime\plain \f1\lang1033\fs24 ; mit Erl\u228 \'e4uterung. \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Septem opera pietatis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 visito\plain \f1\lang1033\fs24  \endash  \plain \f1\i\lang1033\fs24 infirmo fui et visitastis me\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 condo\plain \f1\lang1033\fs24  \endash  \plain \f1\i\lang1033\fs24 mortuus fui et sepelistis me\plain \f1\lang1033\fs24  (vgl. Mt 25,35-36).}

