\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 137\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -138\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\chcbpat8\cf1 Proverbia\plain \f1\b\lang1033\fs24\cf1  varia
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Sprichw\u246 \'f6rter in Auswahl, darunter auch Carmina medica: \plain \f1\i\lang1033\fs24 Qui vult ire vias geminas per deuia rura\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\i\lang1033\fs24 Pillea sint illis, qui carent fronte capillis\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Est mihi tam grauis cognoscere, que via nauis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Est homo res fragilis, quia durat tempore paruo\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 5691; \plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 7486). \endash  (137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sunt homini dentes xxxii commedentes\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum Nr. 18830). \endash  \plain \f1\i\lang1033\fs24 Pontifices muti, de iure suo bene tuti\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Excitat et nutrit facundia dulcis amorem \plain \f1\lang1033\fs24 \u8230 \'85 \endash \plain \f1\i\lang1033\fs24  Causidicus, medicus, meretrix semper meditantur \plain \f1\lang1033\fs24 \u8230 \'85 \endash \plain \f1\i\lang1033\fs24  Cena breuis uel cena leuis fit\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 raro molesta\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Vulpis amat fraudem, leo predam, femina laudem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 LX bis duo cccc super addita milia quinque | Tot fertur Christus pro nobis uulnera passus\plain \f1\lang1033\fs24 . \endash  (138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Corpora dant macra nobis ieiunia sacra\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 3492). \endash  \plain \f1\i\lang1033\fs24 Quando bonum faris et\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 [in]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 corde malum meditataris\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Artubus\plain \f1\lang1033\fs24  (!, recte Artibus) \plain \f1\i\lang1033\fs24 innumeris mens oppugnatur amantis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Accipiunt casum dubium matura prunella\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 270). \endash  \plain \f1\i\lang1033\fs24 Nati preconum, monachorum, presbyterorum\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 15912). \endash  138\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

