\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 I\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1 , 334\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1  Calendarium (Fliegende Vors\u228 \'e4tze)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa60\itap0 \plain \f1\lang1033\fs24\chcbpat8 (I\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Kalendervers: \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Januarius habet dies xxxi, luna xxx\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b. \endash  F\u252 \'fcnf Spalten f\u252 \'fcr: 1. Goldene Zahl \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 I\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b bis \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 XIX\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs28\chcbpat8\cf1 ; 2. \plain \f1\lang1033\fs24\chcbpat8 Sonntagsbuchstabe \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b bis \plain \f1\i\lang1033\fs24\chcbpat8 g\plain \f1\lang1033\fs24\chcbpat8 ; 3. Tagesangaben nach dem r\u246 \'f6m. Kalender; 4. nicht bestimmt; 5. Heiligenfeste, u.a. \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Erhardi episcopi\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (8.1.), \plain \f1\i\lang1033\fs24\chcbpat8 Karoli Magni regis\plain \f1\lang1033\fs24\chcbpat8  (28.1.), \plain \f1\i\lang1033\fs24\chcbpat8 Ualerij episcopi\plain \f1\lang1033\fs24\chcbpat8  (29.1.). \endash  (I\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Februarius habet dies xxviii, luna xxix\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; u.a. mit den Festen: [Obitus] \plain \f1\i\lang1033\fs24\chcbpat8 Ualtpurge uirginis\plain \f1\lang1033\fs24\chcbpat8  (25.2.), \plain \f1\i\lang1033\fs24\chcbpat8 Alexandri episcopi\plain \f1\lang1033\fs24\chcbpat8  (28.2.). \endash  (334\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Julius habet dies xxxi, luna xxx\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; u.a. mit den Festen: N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Visitatio Sancte Marie\plain \f1\lang1033\fs24\chcbpat8  (2.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Processi et Martiniani martyrum \plain \f1\lang1033\fs24\chcbpat8 (2.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Udalrici episcopi\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (4.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Translatio S. Martini episcopi et confessoris\plain \f1\lang1033\fs24\chcbpat8  (4.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Translatio S. Katharine\plain \f1\lang1033\fs24\chcbpat8  (5.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Goaris confessoris\plain \f1\lang1033\fs24\chcbpat8  (6.7.),\plain \f1\lang1033\fs24\chcbpat8\cf1  \plain \f1\lang1033\fs24\chcbpat8 N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8\cf1  \plain \f1\i\lang1033\fs24\chcbpat8 Translatio Sancti Nicolay episcopi et confessoris\plain \f1\lang1033\fs24\chcbpat8  (9.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Septem fratrum martyrum\plain \f1\lang1033\fs24\chcbpat8  (10.7.), \plain \f1\i\lang1033\fs24\chcbpat8 Translacio S. Benedicti\plain \f1\lang1033\fs24\chcbpat8  (11.7.), \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Margarete uirginis\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (12.7.),\plain \f1\lang1033\fs24\chcbpat8\cf1  \plain \f1\lang1033\fs24\chcbpat8 N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8\cf1 Heinrici imperatoris et confessoris\plain \f1\lang1033\fs24\chcbpat8\cf1  (13.7.), \plain \f1\lang1033\fs24\chcbpat8 N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Divisio apostolorum\plain \f1\lang1033\fs24\chcbpat8  (15.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Arsenii heremite et confessoris\plain \f1\lang1033\fs24\chcbpat8  (19.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Christine virginis et martyris\plain \f1\lang1033\fs24\chcbpat8  (24.7.), N\plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8 (?) \plain \f1\i\lang1033\fs24\chcbpat8 Anne matris Marie\plain \f1\lang1033\fs24\chcbpat8  (26.7.). \endash  (334\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Augustus habet dies xxxi, luna xxx\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b; mit den f\u252 \'fcr Regensburg sowie in den meisten Di\u246 \'f6zesen \u252 \'fcblichen Festen; N\plain \f1\super\lang1033\fs24\chcbpat8 2\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 Festum patronorum\plain \f1\lang1033\fs24\chcbpat8  (11.8.). \endash  II\plain \f1\super\lang1033\fs24\chcbpat8 rv\plain \f1\lang1033\fs24\chcbpat8  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Beide Vorsatzbl\u228 \'e4tter stammen aus derselben Hs., da sie von derselben Haupthand bei gleichartiger Seitengestaltung und Blattz\u228 \'e4hlung (I\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : \u183 \'b713\u183 \'b7; 334\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : \u183 \'b716\u183 \'b7) geschrieben wurden; im Juli und August wurden mehrere Feste von mindestens zwei H\u228 \'e4nden N\plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20  und N\plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20  nachgetragen. \endash  Bemerkenswert ist auf 334\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  der Eintrag \plain \f1\i\lang1033\fs20 Festum patronorum\plain \f1\lang1033\fs20  f\u252 \'fcr den 11. August, das an diesem Tag lediglich in der Di\u246 \'f6zese Merseburg begangen wurde. Zu diesem Fest vgl. Karl Eduard \plain \f1\scaps\lang1033\fs20 F\u246 \'f6rstemann\plain \f1\lang1033\fs20 , Calendarium Merseburgense, in: Neue Mitteilungen aus dem Gebiete historisch-antiquarischer Forschungen 2 (1836), Heft 2, S. 229-259, hier S. 249; Heinrich \plain \f1\scaps\lang1033\fs20 Otte\plain \f1\lang1033\fs20 , Heortologisches, die S\u228 \'e4chsischen Hochstifter betreffend, in: Neue Mitteilungen aus dem Gebiete historisch-antiquarischer Forschungen 8 (1850), Heft 3/4, S. 88-94, hier S. 90-94.}

