\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 I (Bl. III-325)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 1\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -5\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Cantica tertii nocturni (Cantica matutinales)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa60\itap0 \plain \f1\lang1033\fs24\chcbpat8 III\plain \f1\super\lang1033\fs24\chcbpat8 rv\plain \f1\lang1033\fs24\chcbpat8  leer. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 In aduentu domini Cantica. Esaie quadragesimo capitulo\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Ecce, dominus deus in fortitudine ueniet\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 Is 40,10-17; Is 42,10-16; (1\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Is 49,7-13. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 In natiuitate domini Cantica Esaie nono capitulo\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Is 9,2-7; (2\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Is 66,10-16 \plain \f1\i\lang1033\fs24\chcbpat8 Letare Iherusalem\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85; Is 26,1-12. \endash  (2\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 In quadragesima Cantica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Ier 14,17-21; Lam 5,1-7, 15-17, 19-21; (3\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Ez 36,24-28. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 In pasca canticum\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Is 63,1-5; (3\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Os 6,1-6; So 3,8-13. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Dominicis diebus Cantica Esaie 3iii\u176 \'b0\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Is 33,2-10; (4\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Is 33,13-18; Sir 36,14-19. \endash  (4\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De corpore Christi Cantica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Hab 3,2-6; Hab 3,7-12; Hab 3,13-19.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Emmeramer Parallel\u252 \'fcberlieferung: Clm 14741, 58\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ; 14744, 163\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; 14757, 149\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; 14771, 70\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; 14774, 110\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; 14828, 55\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (jeweils ohne Corpus Christi).}

