\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 264\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -289\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Lectiones f\u252 \'fcr die 3. Nokturn an Sonntagen nach Trinitatis
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa60\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Dominica prima post octauas penthecostes\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b Lc 16,19-31; (264\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Lectio 1-4: \plain \f1\i\lang1033\fs24\chcbpat8 Quem, fratres karissimi, quem diues ille\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 improbo fauore laudare\plain \f1\lang1033\fs24\chcbpat8  (Greg. M., Hom. in evang. II,40, CCL 141, S. 394-396 Z. 16-57). VD16 B 8211 (II), 84\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 . \endash  (265\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 2. Lc 14,16-24; (265\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Lectio 1-4: PD II, 38. VD16 B 8211 (II), 84\plain \f1\super\lang1033\fs24\chcbpat8 rb\plain \f1\lang1033\fs24\chcbpat8 . \endash  (266\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 3. Lc 15,1-10; (266\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Lectio 1-4: PD II, 39. VD16 B 8211 (II), 85\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 . \endash  (267\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 4. Lc 6, 36-42; Lectio 1-4: \plain \f1\i\lang1033\fs24\chcbpat8 Modo, cum legeretur euangelium\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 peccandi fomitem subministrat\plain \f1\lang1033\fs24\chcbpat8  (Caesarius Arelatensis, Sermones, sermo 148,1, CCL 104, ed. D. Germain \plain \f1\scaps\lang1033\fs24\chcbpat8 Morin\plain \f1\lang1033\fs24\chcbpat8 , S. 605f.). VD16 B 8211 (II), 86\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 . \endash  (268\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 5. Lc 5,1-11; Lectio 1-4: \plain \f1\i\lang1033\fs24\chcbpat8 Ascendens autem in unam nauim\plain \f1\lang1033\fs24\chcbpat8  (!, recte navem) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 ad superna transducunt\plain \f1\lang1033\fs24\chcbpat8  (Ambr. M., Expos. Lc IV,68-72, CCL 14, S. 131-133 Z. 846-902). VD16 B 8211 (II), 87\plain \f1\super\lang1033\fs24\chcbpat8 ra\plain \f1\lang1033\fs24\chcbpat8 . \endash  (269\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 6. Mt 5,20-24; Lectio 1-4. \plain \f1\i\lang1033\fs24\chcbpat8 Amen, dico uobis quia\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 linguam facile transferuntur\plain \f1\lang1033\fs24\chcbpat8  (Aug., Serm. in monte I, \u167 \'a7 9,21-23, CCL 35, S. 22-24 Z. 457-524). VD16 B 8211 (II), 87\plain \f1\super\lang1033\fs24\chcbpat8 vb\plain \f1\lang1033\fs24\chcbpat8 . \endash  (270\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 7. Mc 8,1-9; (270\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Lectio 1-4: \plain \f1\i\lang1033\fs24\chcbpat8 Ayt euangelista in presenti lectione\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 extra mulieres et infantes\plain \f1\lang1033\fs24\chcbpat8  (Epiphanius Beneventanus, Interpretatio Evangeliorum, cap. 60; Ed.: Sancti Epiphanii episcopi interpretatio Evangeliorum, ed. Alvar \plain \f1\scaps\lang1033\fs24\chcbpat8 Erikson\plain \f1\lang1033\fs24\chcbpat8 . Leipzig 1939, S. 163 Z. 8-S. 164 Z. 17). VD16 B 8211 (II), 88\plain \f1\super\lang1033\fs24\chcbpat8 va\plain \f1\lang1033\fs24\chcbpat8 . \endash  (271\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) Dominica 8. Mt 7,15-21; Lectio 1-4: \plain \f1\i\lang1033\fs24\chcbpat8 Attendite a fal