\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 326\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -332\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Directorium f\u252 \'fcr die Adventszeit
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Si fuerit littera dominicalis, tunc Aduentus domini semper inchoatur in vigilia seu profesto sancte Barbare virginis et est breuissimus Aduentus, qui euenire potest, de quo talis breuiatura teneri valeat, que sequitur\plain \f1\lang1033\fs24 . \endash  \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24 Prima dominica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 prout in libris habetur, in omnibus peragitur\plain \f1\lang1033\fs24 . \endash  b (Montag): \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Barbare virginis\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  (4.12.) \plain \f1\i\lang1033\fs24 Post laudes \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 antiphona\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Angelus domini\plain \f1\lang1033\fs24  (Cantus 001414); \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Post\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\i\lang1033\fs24  Magnificat \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 antiphona\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Jerusalem respice\plain \f1\lang1033\fs24  (Cantus 003481). \endash  \plain \f1\i\lang1033\fs24 c\plain \f1\lang1033\fs24  (Dienstag): \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Inuitatorium\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Regem uenturum dominum\plain \f1\lang1033\fs24  (Cantus 001149); \plain \f1\i\lang1033\fs24 Venite ado\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 remus\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\lang1033\fs24  (Ps 96,4); \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Ymnus\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Verbum supernorum\plain \f1\lang1033\fs24  (AH 2 Nr. 19) \u8230 \'85 \endash  (Z. 13) \plain \f1\i\lang1033\fs24 d\plain \f1\lang1033\fs24  (Mittwoch): \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Nicolai episcopi\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  (6.12.) \plain \f1\i\lang1033\fs24 Post laudes\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 antiphona\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 De Syon exibit\plain \f1\lang1033\fs24  (Cantus 002119); \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 Post\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\i\lang1033\fs24  Magnificat \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24 antiphona\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Veniet forcior \plain \f1\lang1033\fs24 (Cantus 005339) \u8230 \'85 \endash  (Z. 21) \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Secunda dominica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 peragitur, prout in libris continetur\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 (Z. 29) \plain \f1\i\lang1033\fs24 d\plain \f1\lang1033\fs24  (Mittwoch): \plain \f1\i\lang1033\fs24\chcbpat8 Lucie virginis\plain \f1\lang1033\fs24\chcbpat8  (13.12); (326\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  Z. 3) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Tercia dominica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 peragitur, ut patet in libris\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85; (Z. 17) \plain \f1\i\lang1033\fs24\chcbpat8 e\plain \f1\lang1033\fs24\chcbpat8  (Donnerstag): \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Thome apostoli\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (21.12.); (Z. 27) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 A\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Quarta dominica\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 est vigilia sancta\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (327\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 B\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si fuerit littera dominicalis, tunc Aduentus domini inchoatur in die sancti Virgilii episcopi et est longissimus, qui euenire valet\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (328\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 C\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si littera dominicalis, tunc Aduentus domini inchoatur proxima die post festum sancti Virgilii\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (329\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 D\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si fuerit littera dominicalis, tunc Aduentus domini inchoatur in vigilia sancti Andree apostoli\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (330\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 E\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si fuerit littera dominicalis, tunc Aduentus domini inchoatur in die sancti Andree apostoli\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (331\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 F\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si littera dominicalis fuerit, tunc Aduentus domini inchoatur proxima die post Andree, id est kalendis Decembris\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  (332\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 G\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Si fuerit littera dominicalis, tunc Aduentus domini inchoatur in octava sancte Katherine, hoc est quarto nonis Decembris\plain \f1\lang1033\fs24\chcbpat8 . \endash  (332\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) Schreibervers mit Jahresangabe: \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Laus et honor tibi, Christe, unacum regnante patre almoque simul flamini, uni sub trino nomine\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b (nach AH 51 Nr. 140 Str. 7) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 1504\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  333\plain \f1\super\lang1033\fs24\chcbpat8 rv\plain \f1\lang1033\fs24\chcbpat8  leer.}

