\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 27\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -57\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Commentarius in Sallustium (Anonymus Monacensis B)
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 27\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -40\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Bellum Catilinae
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\i\lang1033\fs24 Matheria Salvstii est Catilina et sui contemporanei facientes ciuile bellum vel Romani impugnantes rem publicam et defendentes\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (Z. 7) \plain \f1\i\lang1033\fs24 Prologus eius dicitur esse de libro et non de libro\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed pocius causa adquirende glorie, quam debeo querere\plain \f1\lang1033\fs24 . \endash  (Z. 12) Commentarius: \plain \f1\i\lang1033\fs24 Nam\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 omnis homines\plain \f1\lang1033\fs24\chcbpat8 \lquote  (BC 1,1), \plain \f1\i\lang1033\fs24\chcbpat8 id est omnis condicionis homines\plain \f1\lang1033\fs24\chcbpat8 , \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 qui student\plain \f1\lang1033\fs24\chcbpat8 \lquote  \plain \f1\i\lang1033\fs24\chcbpat8 ad hoc, ut stent pre\plain \f1\lang1033\fs24\chcbpat8  \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 ceteris animalibus\plain \f1\lang1033\fs24\chcbpat8 \lquote , \plain \f1\i\lang1033\fs24\chcbpat8 vel qui student, ut prestent ceteris hominibus\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quia uero quidam amicum et cognatum\plain \f1\lang1033\fs24\chcbpat8 , \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 merorem\plain \f1\lang1033\fs24\chcbpat8 \lquote  (BC 61,9) \plain \f1\i\lang1033\fs24\chcbpat8 in corde\plain \f1\lang1033\fs24\chcbpat8 , \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 luctum\plain \f1\lang1033\fs24\chcbpat8 \lquote  \plain \f1\i\lang1033\fs24\chcbpat8 in mente agitabant\plain \f1\lang1033\fs24\chcbpat8 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Segoe UI;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 40\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -57\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Bellum Iugurthinum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Materia huius auctoris in hoc prologo sunt quidam inertes incusantes naturam suam, quod ad nullam gloriam peruenire ualeant\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 de quibus ita admirans inchoat\plain \f1\lang1033\fs24 . \endash  (Z. 25) Commentarius: \plain \f1\i\lang1033\fs24 Admiranda est prauitas humani generis, quod\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 humanum\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 g\plain \f1\lang1033\fs24\chcbpat8 [eneris] \plain \f1\i\lang1033\fs24\chcbpat8 queritur\plain \f1\lang1033\fs24\chcbpat8 \lquote  (BI 1,1) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 et non solum in Numidia triumphauit sed etiam in Gallia, quia\plain \f1\lang1033\fs24\chcbpat8  \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 postquam bellum\plain \f1\lang1033\fs24\chcbpat8 \lquote  (BI 114,3) \plain \f1\i\lang1033\fs24\chcbpat8 et post uictoriam Gallie\plain \f1\lang1033\fs24\chcbpat8 . \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 Ex\plain \f1\lang1033\fs24\chcbpat8  (!, recte Et) \plain \f1\i\lang1033\fs24\chcbpat8 ea tempestate\plain \f1\lang1033\fs24\chcbpat8 \lquote  (BI 114,4).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Kommentar ohne kommentierten Text. Vorliegende Hs. ist nach \plain \f1\scaps\lang1033\fs20 Osmond\plain \f1\lang1033\fs20 /\plain \f1\scaps\lang1033\fs20 Ulery\plain \f1\lang1033\fs20  der \u228 \'e4lteste vollst\u228 \'e4ndige Textzeuge. \endash  Teiledition: Karl \plain \f1\scaps\lang1033\fs20 Besler\plain \f1\lang1033\fs20 , Kommentare zu Sallust aus Handschriften der Staatsbibliothek M\u252 \'fcnchen. [M\u252 \'fcnchen 1977], S. 14-84 passim (BC, nach dieser Hs. mit der Sigle c), S. 84-101 passim (BI, nach dieser Hs. mit der Sigle c); C. Lukas \plain \f1\scaps\lang1033\fs20 Bohny\plain \f1\lang1033\fs20 , Glossen und Scholien zu Sallusts Monographien \plain \f1\lang1033\fs20\chcbpat8 \u8218 \'82\plain \f1\lang1033\fs20 Catilina\lquote  und \plain \f1\lang1033\fs20\chcbpat8 \u8218 \'82\plain \f1\lang1033\fs20 Iugurtha\lquote  in einer Handschrift des 11. Jahrhunderts aus der Bibliothek des Klosters St. Emmeram in Regensburg, in: Archivum latinitatis medii aevi 70 (2012), S. 91-145; Bd. 72 (2012), S. 187-285, hier Bd. 72, S. 189-235 (BC), S. 233-285 (BI, nach Clm 14477, dem \u228 \'e4ltesten, jedoch unvollst\u228 \'e4ndigen Kommentar in der Fassung Monacensis B, der bis BI 103,6 reicht)\plain \f1\lang1033\fs20\chcbpat8 .\plain \f1\lang1033\fs20  \endash  Zur handschriftl. \u220 \'dcberlieferung s. Patricia J. \plain \f1\scaps\lang1033\fs20 Osmond\plain \f1\lang1033\fs20  / Robert W. \plain \f1\scaps\lang1033\fs20 Ulery\plain \f1\lang1033\fs20 , Sallustius Crispus, Gaius, in: Catalogus translationum et commentariorum: Mediaeval and Renaissance Latin Translations and Commentaries. Annoted lists and guides, Bd. 8, ed. Paul Oskar \plain \f1\scaps\lang1033\fs20 Kristeller\plain \f1\lang1033\fs20  / F. Edward \plain \f1\scaps\lang1033\fs20 Cranz\plain \f1\lang1033\fs20 . Washington 2003, Sp. 183-326, hier Nr. I.5, Sp. 230b-231a (BC), Nr. II.6, Sp. 288b-289a (BI), zu dem mit Monacensis B verwandten Kommentar Monacensis A s. Nr. I.4, Sp. 229a-230b (BC), Nr. II.5, Sp. 288ab (BI). \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Cardelle de Hartmann\plain \f1\lang1033\fs20 , Sallust in St. Emmeram (s. Einband), S. 1 Anm. 1, S. 7f., 16f. (Hs. jeweils genannt); \plain \f1\scaps\lang1033\fs20 dies\plain \f1\lang1033\fs20 ., Exzerpte als Rezeptionszeugnisse: Isidors \u8218 \'82Etymologiae\lquote  in Handschriften aus dem Kloster St. Emmeram, in: Das Mittelalter 14 (2009), S. 29-41, hier S. 33; \plain \f1\scaps\lang1033\fs20 Bohny\plain \f1\lang1033\fs20 , Bd. 70, hier S. 99f., 136 (Hs. genannt); \plain \f1\scaps\lang1033\fs20 Munk Olsen\plain \f1\lang1033\fs20 , L\rquote \u233 \'e9tude 5, S. 232 [Cc. 3.5].}

