\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 206\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -207\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Hugo de Sancto Victore (?):\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Excerptiones allegoricae (lib. 3)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 De Asia et partibus eius\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Asia habet prouincias multas et regiones, habet enim paradisum et tres Indias\plain \f1\lang1033\fs24  (?), \plain \f1\i\lang1033\fs24 habet insulam Taprobanam. Inter Indum et Tigrim sunt Partia, Assiria, Med\plain \f1\lang1033\fs24\chcbpat8 [i]\plain \f1\i\lang1033\fs24 a, Persia. Inter Tigrim et Eufratem est\plain \f1\lang1033\fs24  (!, vielm. sunt) \plain \f1\i\lang1033\fs24 Mesopotamia, Kaldea, Arabia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 inter mare rubrum et occeanum australem est Etiopia, que ab occidente montibus clauditur. Sub Etiopia sunt deserta Egipti\plain \f1\lang1033\fs24  (cap. 2). \endash  \plain \f1\i\lang1033\fs24 Affrice regiones ab Oriente in Occidentem porriguntur: Sunt ibi Etiopes, Cirenenses Libia, Tripolitana, Mauritan\plain \f1\lang1033\fs24\chcbpat8 [i]\plain \f1\i\lang1033\fs24 a, Kartago, Getulia\plain \f1\lang1033\fs24  (geschw\u228 \'e4rzt) \u8230 \'85 (cap. 3). \endash  (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Europe regiones sunt a fluuio Tanais secus litus oceani ad Occidentem porrecte\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 abhinc versus austrum sunt Campania, Apulia, Tuscia, Kalabria, Sicilia et Ytalia\plain \f1\lang1033\fs24  (cap. 4). \endash  \plain \f1\i\lang1033\fs24 De montibus respice in minori libello 126, de monstris in eodem 73\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Babilon est in Kaldea, Niniues in Assiria, Sys in Armenia, Nisa in India, Media in Med\plain \f1\lang1033\fs24\chcbpat8 [i]\plain \f1\i\lang1033\fs24 a, in Siria Damasus, in Siria celes Antiochia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 in Longobardia Mediolanum, Papia, Rauenna, Mantua\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Aquilegia, in Kalabria Tarentum\plain \f1\lang1033\fs24  (cap. 8) (vgl. Druck: PL 177, 209D-215B).}

