\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 64\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -66\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermones de passione Domini in parasceve
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De die parasauen\plain \f1\lang1033\fs24\chcbpat8  (!)\u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Inclinato capite emisit spiritum\plain \f1\lang1033\fs24\chcbpat8  (vgl. Mt 27,50; Io 19,30). \plain \f1\i\lang1033\fs24\chcbpat8 De passione domini dicit Bernardus\plain \f1\lang1033\fs24\chcbpat8 : \plain \f1\i\lang1033\fs24\chcbpat8 Caput tremendum angelicis spiritibus spinarum densitate configitur, oculi lucidiores sole caligant in morte\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 quoniam sanctum est, clavis cruci constringuntur\plain \f1\lang1033\fs24\chcbpat8  (Jacobus a Voragine, Legenda aurea, ed. \plain \f1\super\lang1033\fs24\chcbpat8\cf1 2\plain \f1\scaps\lang1033\fs24\chcbpat8\cf1 Maggioni\plain \f1\scaps\lang1033\fs24\chcbpat8\cf1  1,\plain \f1\lang1033\fs24\chcbpat8  cap. 51.90 S. 340f.). (Z. 5) \plain \f1\i\lang1033\fs24\chcbpat8 Ista omnia ante diu prophetata fuerant\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 qui uenturus est iudicare uiuos et mortuos et se per ignem viuens et regnans cum omnipotente patre\plain \f1\lang1033\fs24\chcbpat8  (vgl. \plain \f1\scaps\lang1033\fs24\chcbpat8 Schneyer\plain \f1\lang1033\fs24\chcbpat8 , Rep. 7, S. 621 Nr. 77). \endash  \plain \f1\super\lang1033\fs24\chcbpat8 2\plain \f1\i\lang1033\fs24\chcbpat8 Inclinato capite emisit spiritum \plain \f1\lang1033\fs24\chcbpat8 (Mt 27,50; Io 19,30). \plain \f1\i\lang1033\fs24\chcbpat8 Vt passionem domini melius intelligamus, dicendum\plain \f1\lang1033\fs24\chcbpat8  [est] \plain \f1\i\lang1033\fs24\chcbpat8 de passionis causa, efficacia, magnitudine \plain \f1\lang1033\fs24\chcbpat8 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 qui in mente reuoluit, horas bene cantat. Amen\plain \f1\lang1033\fs24\chcbpat8  (vgl. \plain \f1\scaps\lang1033\fs24\chcbpat8 Schneyer\plain \f1\lang1033\fs24\chcbpat8 , Rep. 7, S. 632 Nr. 280).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20\chcbpat8\cf18 (Nr. 2) Parallel\u252 \'fcberlieferung: Innsbruck, UuLB, Cod. 475, 37\plain \f1\super\lang1033\fs20\chcbpat8\cf18 va\plain \f1\lang1033\fs20\chcbpat8\cf18 ; Cod. 499, 197\plain \f1\super\lang1033\fs20\chcbpat8\cf18 va\plain \f1\lang1033\fs20\chcbpat8\cf18 ; vgl. auch T\u252 \'fcbingen, UB, Mc 159, 56\plain \f1\super\lang1033\fs20\chcbpat8\cf18 v\plain \f1\lang1033\fs20\chcbpat8\cf18 .}

