\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 66\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -70\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermones de commune sanctorum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\super\lang1033\fs24\chcbpat8 1\plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sermo communis\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Non potest arbor bona\plain \f1\lang1033\fs24\chcbpat8  (Mt 7,18). \plain \f1\i\lang1033\fs24\chcbpat8 Sic homo quamdiu est in mortali peccato, non potest facere fructus eterne vite meritorum. Multiplex vero dampnum incurrit homo propter peccatum\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 ut ipsi placati iam sederant in regno celorum, ut preces pro nobis ad deum fundunt\plain \f1\lang1033\fs24\chcbpat8 . \endash  \plain \f1\super\lang1033\fs24\chcbpat8 2\plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sermo de uno martire\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Beatus uir, qui inuenit\plain \f1\lang1033\fs24\chcbpat8  (Prv 3,13). \plain \f1\i\lang1033\fs24\chcbpat8 Multum laudantur, qui sciunt sibi cauere ab astuciis diaboli\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 (Bertholdus Ratisbonensis, Commune sanctorum Rusticani, \plain \f1\scaps\lang1033\fs24\chcbpat8 Schneyer\plain \f1\lang1033\fs24\chcbpat8 , Rep. 1, S. 489 Nr. 218). \endash  \plain \f1\super\lang1033\fs24\chcbpat8 3\plain \f1\lang1033\fs24\chcbpat8 (68\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sermo de vno martire\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Qui non accipit\plain \f1\lang1033\fs24\chcbpat8  (Mt 10,38). \plain \f1\i\lang1033\fs24\chcbpat8 Hic Christus hortatur nos, ut crucem tollamus et vt eum sequamur\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \plain \f1\lang1033\fs22\chcbpat8 (\plain \f1\lang1033\fs24\chcbpat8 Bertholdus Ratisbonensis, Commune sanctorum Rusticani, \plain \f1\scaps\lang1033\fs24\chcbpat8 Schneyer\plain \f1\lang1033\fs24\chcbpat8 , Rep. 1, S. 488 Nr. 211). \endash  \plain \f1\super\lang1033\fs24\chcbpat8 4\plain \f1\lang1033\fs24\chcbpat8 (69\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Sermo de apostolis\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Qui etiam pro nobis proprio filio\plain \f1\lang1033\fs24\chcbpat8  (Rm 8,32). \plain \f1\i\lang1033\fs24\chcbpat8 Item rogo ergo, ut de bonis\plain \f1\lang1033\fs24\chcbpat8  (!, recte donis) \plain \f1\i\lang1033\fs24\chcbpat8 singularibus taceam. Tria dona dat deus vnicuique homini\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 (Bertholdus Ratisbonensis, Commune sanctorum Rusticani, \plain \f1\scaps\lang1033\fs24\chcbpat8 Schneyer\plain \f1\lang1033\fs24\chcbpat8 , Rep. 1, S. 488 Nr. 208).}

