\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 48\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -57\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermo de passione Domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Audite, obsecro vniuersi populi\plain \f1\lang1033\fs24  (Lam 1,18). \plain \f1\i\lang1033\fs24 Verba proposita leguntur in libro lamentacionum et sunt verba Jeremie prophete, que pie et apte quidam hodie possunt esse domini ac saluatoris nostri Ihesu Christi, nobis conquerendo multiplicem dolorem sue passionis, sit intonando\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 Audite, obsecro\plain \f1\lang1033\fs24\chcbpat8 \lquote . \plain \f1\i\lang1033\fs24\chcbpat8 Notandum igitur, quod hodie dolor eius duplex fuit, vnus exterior et hic in corpore, alter interior et hic in anima\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui tibi imminet in anima et corpore delebit et post hanc vitam nobis omnibus vitam eternam condonabit, quod nobis prestare dignetur\plain \f1\lang1033\fs24  \u8230 \'85}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset2 Wingdings;}{\f3\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

