\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 110\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -111\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Nicolaus de Byarto: Sermo in vigilia nativitatis Jesu Christi (T6)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24 Ewangeliz\plain \f1\lang1033\fs24\chcbpat8 [o].\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Sermo de natiuitate Ihesu Christi\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Ewangeliz\plain \f1\i\lang1033\fs24\chcbpat8 o vobis\plain \f1\lang1033\fs24\chcbpat8  (Lc 2,10). \plain \f1\i\lang1033\fs24 Dicitur w\plain \f1\lang1033\fs24\chcbpat8 [u]\plain \f1\i\lang1033\fs24\chcbpat8 lgariter\plain \f1\lang1033\fs24\chcbpat8 , [quod] \plain \f1\i\lang1033\fs24\chcbpat8 nimis cito venit, qui malos rumores apportat. Et ideo a contrario: Non potest se nimis \plain \f1\i\lang1033\fs24 festinare\plain \f1\i\lang1033\fs24\chcbpat8 , qui bonos rumores apportat\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 item gaudendum est de uisitacionibus diuinis sicut dicitur Lucas primo: Ex quo facta est vox salu\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 tationis\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 t\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 uae\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 in\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 auribus\plain \f1\lang1033\fs24\chcbpat8 ] \plain \f1\i\lang1033\fs24 meis, exulta\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 vit\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 in gau\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 dio\plain \f1\lang1033\fs24\chcbpat8 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 inf\plain \f1\lang1033\fs24 [ans in utero meo] (Lc 1,44)|| vermutlich Textabbruch.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs20 Schneyer, \plain \f1\lang1033\fs20 Rep. 4, S. 230 Nr. 20.}

