\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 Prolog: \plain \f1\i\lang1033\fs24\cf1 Dilectissimo fratri Nothhelmo Beda salutem. Quae de libro regum dilucidanda tibi, frater dilectissime, misisti statim prout domino iuuante potui explicare\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 bene uale semper dilectissime in Christo frater. EXPLICIT PREFATIO. INCIPIUNT CAPITVLA\plain \f1\lang1033\fs24\cf1 . \endash  (2\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Kapitelverzeichnis. \plain \f1\lang1033\fs24\chcbpat8\cf1 \u8250 \'9b\plain \f1\i\caps\lang1033\fs24\chcbpat8\cf1 Expliciunt capitula\plain \f1\lang1033\fs24\chcbpat8\cf1 \u8249 \'8b \plain \f1\lang1033\fs24\cf1 \endash  (4\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\lang1033\fs24\chcbpat8\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8\cf1 INCIPIT IPSE LIBER QUESTIONUM IN REGUM\plain \f1\lang1033\fs24\chcbpat8\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Quod ait propheta ad Heli loquens ex persona dei \plain \f1\i\lang1033\fs24 et suscitabo mihi sacerdotem fidelem\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 intrate in gaudium domini uestri\plain \f1\i\lang1033\fs24\cf1 . AMEN\plain \f1\lang1033\fs24\cf1 . \endash  40\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 CPL 1347; \plain \f1\scaps\lang1033\fs20\cf1 Stegm\plain \f1\scaps\lang1033\fs20\cf1 \u252 \'fc\plain \f1\scaps\lang1033\fs20\cf1 ller, \plain \f1\lang1033\fs20\cf1 RB 2 (8), Nr. 1606 (jeweils ohne diese Hs.);\plain \f1\scaps\lang1033\fs20  Laistner\plain \f1\lang1033\fs20 , Bede Manuscripts, S. 63. \endash  Edition: CCL 119, ed. David \plain \f1\scaps\lang1033\fs20 Hurst\plain \f1\lang1033\fs20 , S. 293-322.}

