\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 41\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -43\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Hieronymus: Epistula ad Paulam de alphabeto hebraico psalmi CXVIII
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\i\lang1033\fs24\chcbpat8 Nudius tertius, cum centesimum octauum decimum psalmum tibi insinuare conarer\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 ut dominus Ihesus cont\plain \f1\lang1033\fs24\chcbpat8 [erat] \plain \f1\i\lang1033\fs24\chcbpat8 satanan sub pedibus nostris uelociter\plain \f1\lang1033\fs24\chcbpat8 . \endash  43\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Epistula 30. \endash  CPL 620; \plain \f1\scaps\lang1033\fs20 Lambert\plain \f1\lang1033\fs20 , BHM 4,1B, S. 30. \endash  Edition: CSEL 54, ed. Isidor \plain \f1\scaps\lang1033\fs20 Hilberg\plain \f1\lang1033\fs20 , S. 243-249.}

