\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 70\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -79\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Isidorus Hispalensis: Allegoriae quaedam sanctae Scripturae. Ex novo testamento
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\chcbpat8 Fortsetzung von 60\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 -67\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 . \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 EIUSDEM ADNOTATIONES DE EUANGELIIS\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 QUATTUOR EUANGELISTAE DOMINUM NOSTRUM IHESUM CHRISTUM sub quattuor animalium uultibus figuraliter exprimunt\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 in qua omnes sancti per Christum aeternae beatitudinis refectione saturabuntur. Amen\plain \f1\lang1033\fs24\chcbpat8  (PL 83,116D-130B). \endash  80\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8  leer.}

