\uc1
\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 119\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Einbandfragment: Martyrologium\plain \f1\lang1033\fs24\cf1  (hinterer fliegender Vorsatz)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\chcbpat8 F. \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Quinto k\plain \f1\lang1033\fs24\chcbpat8 [alendas] \plain \f1\i\lang1033\fs24\chcbpat8 Avg\plain \f1\lang1033\fs24\chcbpat8 [usti]\u8249 \'8b (28.7.) \plain \f1\i\lang1033\fs24\chcbpat8 Apud Nicomediam passio beati Pantaleonis, qui tentus pro fide Christi a Maximiano eculei pena\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24\chcbpat8 G\plain \f1\lang1033\fs24\chcbpat8 . \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Quarto\plain \f1\lang1033\fs24\chcbpat8  \plain \f1\i\lang1033\fs24\chcbpat8 k\plain \f1\lang1033\fs24\chcbpat8 [alendas] \plain \f1\i\lang1033\fs24\chcbpat8 Avg\plain \f1\lang1033\fs24\chcbpat8 [usti]\u8249 \'8b (29.7.) \plain \f1\i\lang1033\fs24\chcbpat8 Rome, uia Aurelia, natale beati Felicis pape, qui a Constantio augusto ob katholice fidei defenssionem \plain \f1\lang1033\fs24\chcbpat8 (!) \plain \f1\i\lang1033\fs24\chcbpat8 a sede sua deiectus\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 A. Tertio k\plain \f1\lang1033\fs24\chcbpat8 [alendas] \plain \f1\i\lang1033\fs24\chcbpat8 Avg\plain \f1\lang1033\fs24\chcbpat8 [usti]\u8249 \'8b (30.7.) \plain \f1\i\lang1033\fs24\chcbpat8 Rome natale sanctorum Abdon et Sennes subre\plain \f1\lang1033\fs24\chcbpat8 [gulorum]|| Textabbruch (Druck: S. 420 Z. 14-35). \endash  (119\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8 ) [Nono kalendas Augusti (24.7.)] \plain \f1\i\lang1033\fs24\chcbpat8 Eodem die natale sanctorum Nicee et Aquiline, que predicatione beati Christofori martyris ad Christum conuerse martyrii\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24\chcbpat8 C\plain \f1\lang1033\fs24\chcbpat8 . \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Octavo k\plain \f1\lang1033\fs24\chcbpat8 [alendas] \plain \f1\i\lang1033\fs24\chcbpat8 Avg\plain \f1\lang1033\fs24\chcbpat8 [usti]\u8249 \'8b (25.7.) \plain \f1\i\lang1033\fs24\chcbpat8 Natale beati Iacobi apostoli, fratris Iohannis euangeliste, qui ab Herode rege decollatus est\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 Ciuitate Parisius translacio sancti Germani episcopi et confessoris. Mettis Cladesinde uirginis\plain \f1\lang1033\fs24\chcbpat8  (Chlodesindis, Glodesinde, \u196 \'c4btissin in Metz). \endash  \plain \f1\i\lang1033\fs24\chcbpat8 D.\plain \f1\lang1033\fs24\chcbpat8  \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 Septimo k\plain \f1\lang1033\fs24\chcbpat8 [alendas] \plain \f1\i\lang1033\fs24\chcbpat8 Avg\plain \f1\lang1033\fs24\chcbpat8 [usti]\u8249 \'8b (26.7.) \plain \f1\i\lang1033\fs24\chcbpat8 Natale sancti Herade, qui Philippis a beato Pau\plain \f1\lang1033\fs24\chcbpat8 [lo]|| Textabbruch (Druck: S. 419 Z. 18-37).
