\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 14\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -73\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sequentiae
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24\cf1 (14\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1 ) Nachgetragen: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancto Mavricio\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 186 (Sigle M, Autorschaft Notkers umstritten). \endash  Weihnachtskreis: (15\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In die sancto natalis domini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 15; (16\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 16; (18\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 10 (Sigle C); \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 sancti Stephani protomartyris\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (19\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 215; (20\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In n\plain \f1\lang1033\fs24\cf1 [ativitate] \plain \f1\i\lang1033\fs24\cf1 s. Iohannis evang\plain \f1\lang1033\fs24\cf1 [eliste]\u8249 \'8b AH 53 Nr. 168; (21\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De s. Innocentibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 157; (22\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In epiphania domini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 29 (wg. fehlerhafter Abschrift Zeile tw. radiert); (24\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In purificatione s. Marie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 99; (26\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In septuagesima\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 34. \endash  Osterkreis: (28\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In Pascha\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 36; (31\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 feria II\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 46; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 feria III\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (33\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 50; (33\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 feria IIII\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 52; (34\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 in ascensione domini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 67; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In pentecosten\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (36\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 79. \endash  De sanctis: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 de sancto Iohanne baptista\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (38\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 163; (39\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De s. Petro et Paulo\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 210; (40\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De s. Maria Magdalena\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 50 Nr. 268 (Sigle E); (43\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 de sancto Laurentio martyre\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 173; (44\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In assumptione s. Marie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 104; (45\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In nativitate s. Marie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 95; (46\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancto Emmerammo\plain \f1\lang1033\fs24\cf1  (!) \plain \f1\i\lang1033\fs24\cf1 episcopo\plain \f1\lang1033\fs24\cf1 \u8249 \'8b, AH 53 Nr. 143 (Sigle D) = \plain \f1\scaps\lang1033\fs24\cf1 Mone\plain \f1\lang1033\fs24\cf1 , Hymnen 3, Nr. 907 (nach dieser Hs. und Clm 14322); (48\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In dedicatione ecclesie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 247; (49\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancto Michahele\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 191 (Sigle R); (50\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 190 (Sigle e); (54\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In natale omnium sanctorum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 112; (55\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In natale s. Martini confessoris\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 181; (56\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancto Othmaro abbate\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 203 (Sigle Qa); (57\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De s. Andrea apostolo\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 122 (Sigle U). \endash  Commune Sanctorum: (58\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In nataliciis apostolorum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 228; (62\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De martyribus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 229; (63\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De confessoribus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 243 (Sigle Q); (64\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De virginibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 246 (Sigle O). \endash  (65\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancta Trinitate\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 53 Nr. 81; (67\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancta cruce\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 50 Nr. 239 (Sigle A); (70\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 83 (Sigle K); (71\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De s. Maria\plain \f1\lang1033\fs24\cf1 \u8249 \'8b AH 50 Nr. 265 (Sigle K); (72\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 108 (Sigle Y).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Sammlung von Sequenzen \u252 \'fcberwiegend aus dem Notker zugeschriebenen Bestand (AH 53); mit Ausnahme von 46\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -47\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  (Emmeramus) und Nachtrag 71\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -72\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  ohne Neumierung. Umfangreichere Parallel\u252 \'fcberlieferung aus St. Emmeram: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14322}}\plain \f1\lang1033\fs20 , 15\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  und{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  Clm 14083}}\plain \f1\lang1033\fs20 , 7\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (vgl. \plain \f1\scaps\lang1033\fs20 Wunderle\plain \f1\lang1033\fs20 , Catalogus IV, s. n. 2,1 mit weiterer Lit.); weitere Abschrift aus St. Emmeram: Bamberg SB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Msc. Lit. 6}}\plain \f1\lang1033\fs20 . \endash  Ed. Wolfram \plain \f1\scaps\lang1033\fs20 von den Steinen\plain \f1\lang1033\fs20 , Notker der Dichter und seine geistige Welt.\plain \f1\lang1033\fs24\cf1  \plain \f1\lang1033\fs20 Bd. 2: Editionsband. Bern 1948.}

