\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 99\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Vocabularium sive glossarium latinum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\chcbpat8\cf18 Particulum g\plain \f1\lang1033\fs24\chcbpat8\cf18 \u8230 \'85 (unleserlich) \plain \f1\i\lang1033\fs24\chcbpat8\cf18 uel per stagnum\plain \f1\lang1033\fs24\chcbpat8\cf18  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8\cf18 faber\plain \f1\lang1033\fs24\chcbpat8\cf18  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8\cf18 iacinctus labor\plain \f1\lang1033\fs24\chcbpat8\cf18  (vgl. auch \plain \f1\scaps\lang1033\fs24\chcbpat8\cf1 Munk Olsen\plain \f1\lang1033\fs24\chcbpat8\cf1 , L\rquote \u233 \'e9tude 1, S. 470).}

