\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 111\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -112\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Albericus Casinensis: Flores rethorici (cap. III \u167 \'a7 4-6)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\chcbpat8\cf18 Breuium scientiam, quia multi inpote necessariam, utilem et honestam desiderant, compendiosis aliquibus detegamus indiciis, ut proximorum inseruiamus commodis\plain \f1\lang1033\fs24\chcbpat8\cf18  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8\cf18 Salustius in Iugurtino\plain \f1\lang1033\fs24\chcbpat8\cf18 : \plain \f1\i\lang1033\fs24\chcbpat8\cf18 Iugurte, tui bello Numantino et cetera. Idem\plain \f1\lang1033\fs24\chcbpat8\cf18  [auctor] \plain \f1\i\lang1033\fs24\chcbpat8\cf18 in Catilinario\plain \f1\lang1033\fs24\chcbpat8\cf18 : \plain \f1\i\lang1033\fs24\chcbpat8\cf18 Quis sim ex eo et cetera\plain \f1\lang1033\fs24\chcbpat8\cf18 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Emmeramer Parallel\u252 \'fcberlieferung: Clm 14784, 44\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -59\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (dort mit weiterer Lit.). \endash  Edition: Alberici Casinensis Flores rhetorici, ed. Mauro \plain \f1\scaps\lang1033\fs20 Inguanez\plain \f1\lang1033\fs20  / Henry M. \plain \f1\scaps\lang1033\fs20 Willard\plain \f1\lang1033\fs20 . Montecassino 1938 (Miscellanea cassinese 14), S. 37 letzte Zeile-S. 40 letzte Zeile; online-Ressource: http://alim.unisi.it/dl/resource/280.}

