\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 105\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -107\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 De baptismo
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Incipit tractatus de baptismo\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 In babtismo\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 consideranda sunt institucio, sacramentum, res sacramenti, forma, causa et in quibus temporibus fiat. Institutio babtismatis\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 incepit, ubi dominus misit discipulos ante passionem, ut baptizarent\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 non tamen ab illo patre, qui transfundit, sed qui per eum medium a patre primo in filium descendit\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20\cf1 Parallel\u252 \'fcberlieferung: Heiligenkreuz, StiftsB, Cod. 188, 116\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 -118\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 .}

