\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 6\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1  \endash 300\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 De tempore\plain \f1\lang1033\fs24\cf1  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 Anfang unvollst\u228 \'e4ndig aufgrund Blattverlusts,  Beginn (6\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) in der lectio secunda dominica prime adventus: //[a planta] \plain \f1\i\lang1033\fs24\cf1 pedis usque ad uerticem non est in eo sanitas\plain \f1\lang1033\fs24\cf1 . \u8230 \'85 R: \plain \f1\i\lang1033\fs24\cf1 Aspiciebam\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \u220 \'dcberschriften sowie eingeschobene Erkl\u228 \'e4rungen zur Liturgie und Tabulae zumeist rubriziert, beginnend (8\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Notandum quod a dominica prima de aduentu usque ad natiuitatem\plain \f1\lang1033\fs24\cf1  \u8230 \'85\u8249 \'8b; ab (238\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) werden die lectiones unterbrochen von Psalmen (\u252 \'fcberwiegend in biblischer Abfolge) und hymni, darunter (239\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -240\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) AH 50 Nr. 4, AH 51 Nr. 31, 40, (244\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) Nr. 25, (250va) Nr. 26, (256\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) AH 50 Nr. 22, (256\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 27, (261\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) AH 50 Nr. 23, AH 51 Nr. 28, (269\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 29, (274\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -275\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) Nr. 32, 30, (284\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) Nr. 34, (285\plain \f1\super\lang1033\fs24\cf1 ra-rb\plain \f1\lang1033\fs24\cf1 ) Nr. 35, AH 50 Nr. 18, (286\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Nr. 19, (287\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Nr. 20, (289\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 36, (290\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 37, (291va) Nr. 38, (294vb) Nr. 40, (296\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -299\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 47-50; (299\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tabula subscripta continet modum scilicet quem debent disponi istorie mensis septembris\plain \f1\lang1033\fs24\cf1  \u8230 \'85\u8249 \'8b, (300\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Tabula breuis et nouissima super ordinem dominicarum ab octaua pentecostes usque ad aduentum\plain \f1\lang1033\fs24\cf1 . \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Notandum est quod ab octava Pentecostes usque ad aduentum sunt ad plus XXVIII dominice\plain \f1\lang1033\fs24\cf1  \u8230 \'85 (300\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 DEO GRATIAS. 1466 Marcus de Cribelariis ciuis Vincencie scripsit\plain \f1\lang1033\fs24\cf1 \u8249 \'8b. (Colophons Nr. 12961).
