\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 Am Anfang fehlt 1 Bl., Beginn in der passio s. Andreae // \plain \f1\i\lang1033\fs24\cf1 esse hominum comprobationis iudicem tuum qui in celo est cognosceres\plain \f1\lang1033\fs24\cf1  \u8230 \'85, (301\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 lectio \u8729 \'b7III\plain \f1\lang1033\fs24\cf1 \u8729 \'b7\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Egeas dixit\plain \f1\lang1033\fs24\cf1  \u8230 \'85 - Zwischen den Lectiones Hymni eingestreut, u.a. de s. Antonio (351\plain \f1\super\lang1033\fs24\cf1 rb-vb\plain \f1\lang1033\fs24\cf1 ) AH 4 Nr. 155, 156; (363\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 50 Nr. 96, Str. 9-13; (368\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 188; (375\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) AH 52 Nr. 42, 43, (378\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) 44; (412\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -413\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) de s. Clara AH 52 Nr. 159, 160, (416\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) 161; (425\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) de s. Ludovico AH 4 Nr. 345, 347; (429\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) 349; (449\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) in festo stigmatum s. Francisci AH 4 Nr. 254, (454\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) de Michaele archangele AH 50 Nr. 156, (456\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) 146: (458\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 -459\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) de s. Francisco AH 52 Nr. 195, 196, (463\plain \f1\super\lang1033\fs24\cf1 ra-rb\plain \f1\lang1033\fs24\cf1 ) 197, 198; (477\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr. 129, (479\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) 130. \endash  (495\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -526\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit comune sanctorum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \u8230 \'85, (525\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) AH 51 Nr: 102 Str. 5-9.}

