\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequentes versus dicuntur in fine ymnorum ad horas minores scilicet primas, tercias\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 sextas, nonas\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  completorium specialibus temporibus signatis\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b Schluss-Strophe und Doxologie einiger Hymnen zu den Kleinen Horen besonderer Feste. Ostern \plain \f1\i\lang1033\fs24 Qvesumus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 auctor omnium \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Gloria tibi\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  qui surrexisti a mortuis \plain \f1\lang1033\fs24 \u8230 \'85  AH 2 Nr. 44 (7+8); Christi Himmelfahrt \plain \f1\i\lang1033\fs24 Da nobis illuc sedula \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Gloria tibi\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  qui scandis super sydera \plain \f1\lang1033\fs24 \u8230 \'85 AH 2 Nr. 48 (8+9); Pfingsten \plain \f1\i\lang1033\fs24 Hinc\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  Criste\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 nunc paraclitus \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Sit laus patri cum filio \plain \f1\lang1033\fs24 \u8230 \'85 AH 2 Nr. 50 (9) + Nr. 51 (7); Fronleichnam \plain \f1\i\lang1033\fs24 O\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 salutaris hostia \plain \f1\lang1033\fs24 \u8230 \'85 AH 50 Nr. 388 (5+6); Weihnachten \plain \f1\i\lang1033\fs24 Memento\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 salutis auctor \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Gloria\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 tibi domine\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 qui natus es de virgine\plain \f1\lang1033\fs24  \u8230 \'85 AH 2 Nr. 22 (3+7); (II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Marienfeste \plain \f1\i\lang1033\fs24 Maria\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  mater gracie\plain \f1\lang1033\fs24  \u8230 \'85\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 AH 52 Nr. 55 (4), Doxologie wie an Weihnachten; Apostel \plain \f1\i\lang1033\fs24 Uos sancti iusti iudices \plain \f1\lang1033\fs24 \u8230 \'85 AH 51 Nr. 108 (2+6); M\u228 \'e4rtyrer, Bekenner, Jungfrau(en) \plain \f1\i\lang1033\fs24 Huius\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 o Criste\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 meritis \plain \f1\lang1033\fs24 \u8230 \'85  AH 52 Nr. 70 (3+4).}

