\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 xii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -\plain \f1\scaps\lang1033\fs24 xiii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Morgen-, Schutz- und Elevationsgebete
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 In mane quando surgis dicatur oracio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 In nomine domini nostri Ihesu Cristi surgo qui me precioso sangwine suo redemit\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Ipsum adoro\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  laudo\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  benedico \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Haimerl\plain \f1\lang1033\fs24 , Fr\u246 \'f6mmigkeit, S. 124 Anm. 738; \u8250 \'9b\plain \f1\i\lang1033\fs24 Benediccio quam misit Leo papa regi Ciprie contra omnia pericula\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Pax domini nostri Ihesu Cristi et virtus eius\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 sit triumphalis hodie \plain \f1\lang1033\fs24 \u8230 \'85 ebd. S. 72 Anm. 392; \u8250 \'9b\plain \f1\i\lang1033\fs24 Benediccio Benedicti pape xii\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Benedicat me imperialis maiestas \plain \f1\lang1033\fs24 \u8230 \'85 ebd. S. 86 Anm. 507; (\plain \f1\scaps\lang1033\fs24 xii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Gracias tibi ago\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 omnipotens deus qui me dignatus es in hac nocte custodire \plain \f1\lang1033\fs24 \u8230 \'85 ebd. S. 7 Anm. 17; \u8250 \'9b\plain \f1\i\lang1033\fs24 De proprio angelo suo\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 O benedicte angele dei qui es deputatus custos vite et anime mee\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 precor te \plain \f1\lang1033\fs24 \u8230 \'85 vgl. Ebstorf, StiftsB, IV 17, 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio dicenda ante eleuacionem sacramenti\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Domine Ihesu Criste\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 hec est illa hora sacratissima in qua de pane visibili efficitur sacratissima caro tua \plain \f1\lang1033\fs24 \u8230 \'85; (\plain \f1\scaps\lang1033\fs24 xiii\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 In eleuacione hostie oracio quam Innocencius papa confirmauit dicens\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ave\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  principium nostre creacionis \plain \f1\lang1033\fs24 \u8230 \'85 vgl. M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs24  Cod. ms. 192, 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; \u8250 \'9b\plain \f1\i\lang1033\fs24 Innocencius papa quartus sub eleuacione\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Aue\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  verum Cristi corpus natum ex Maria \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 xiii\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  virgine \plain \f1\lang1033\fs24 \u8230 \'85 mit Anhang \plain \f1\i\lang1033\fs24 O clemens\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  o pie\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  o dulcissime Ihesu\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  fili Marie\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  propicius esto michi peccatori\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . Vgl. AH 54 Nr. 167; \u8250 \'9b\plain \f1\i\lang1033\fs24 Iohannes papa xxii in eleuacione corporis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 O anima Cristi\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  sanctifica me\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 o corpus Cristi\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  sana me \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Chevalier\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 1090.}

