\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Lesungen f\u252 \'fcr die Oktav von Ostern, Himmelfahrt, Pfingsten, Trinitatis, Fronleichnam sowie von Johannes dem T\u228 \'e4ufer, Peter und Paul, Mari\u228 \'e4 Himmelfahrt, zuletzt \u8250 \'9b\plain \f1\i\lang1033\fs24 Leccio infra octauam sancti Emmerammi martiris\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ecce sacerdos magnus\plain \f1\lang1033\fs24  \u8230 \'85 mit Verweis auf 339\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 .}

