\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -177\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Homiliae de communi sanctorum
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequuntur nunc ewangelia communia de sanctis\plain \f1\lang1033\fs24 \u8249 \'8b. Von Aposteln \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 PD II, 103; M\u228 \'e4rtyrern \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 PD II, 115; (169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 3\plain \f1\i\lang1033\fs24 Cum persequentur vos\plain \f1\lang1033\fs24  \u8230 \'85 (Mt 10,23). \plain \f1\i\lang1033\fs24 Hoc quod illud tempus referendum \plain \f1\lang1033\fs24 \u8230 \'85 s. Paris, BNF, Lat. 3776, 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; (170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 4\plain \f1\i\lang1033\fs24 Attendite a fermento \plain \f1\lang1033\fs24 \u8230 \'85 (Lc 12,1). \plain \f1\i\lang1033\fs24 Prescius dominus ac saluator noster multos in sancta ecclesia aduenisse perfidos et impios homines \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Barr\u233 \'e9\plain \f1\lang1033\fs24 , Les hom\u233 \'e9liaires carolingiens, S. 249; (170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 5\plain \f1\i\lang1033\fs24 Descendens Ihesus de monte \plain \f1\lang1033\fs24 \u8230 \'85 (Lc 6,17). \plain \f1\i\lang1033\fs24 Aduertite omnia diligenter quomodo dominus cvm apostolis ascendat et descendat \plain \f1\lang1033\fs24 \u8230 \'85; (171\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 6\plain \f1\i\lang1033\fs24 Videns Ihesus turbas \plain \f1\lang1033\fs24 \u8230 \'85 (Mt 5,1). \plain \f1\i\lang1033\fs24 Si queritur quid significet mons \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Barr\u233 \'e9\plain \f1\lang1033\fs24 , Les hom\u233 \'e9liaires carolingiens, S. 341; (171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) einem M\u228 \'e4rtyrer \plain \f1\super\lang1033\fs24 7-9\plain \f1\lang1033\fs24 PD II, 118. 112. 110; (173\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Bekennern \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 PD II, 109; (173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 11\plain \f1\i\lang1033\fs24 Vigilate quia nescitis \plain \f1\lang1033\fs24 \u8230 \'85 (Mt 24,42). \plain \f1\i\lang1033\fs24 Hic aperte ostenditur \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Barr\u233 \'e9\plain \f1\lang1033\fs24 , Les hom\u233 \'e9liaires carolingiens, S. 343; \plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs24 PD II, 104; (174\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 13\plain \f1\i\lang1033\fs24 Homo quidam nobilis\plain \f1\lang1033\fs24  \u8230 \'85 (Lc 19,12). \plain \f1\i\lang1033\fs24 Homo nobilis de quo sancti ewangelii leccio refert ille est cui cecus clamabat \plain \f1\lang1033\fs24 \u8230 \'85 s. Paris, BNF, Lat. 3826, 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; (175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 14\plain \f1\i\lang1033\fs24 Vos estis sal terre \plain \f1\lang1033\fs24 \u8230 \'85 (Mt 5,13). \plain \f1\i\lang1033\fs24 Ostendit dominus fatuos esse iudicandos \plain \f1\lang1033\fs24 \u8230 \'85 s. Augsburg, UB, Cod. II.1.2\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs24  126, 213\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; (175\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) einem Bekenner \plain \f1\super\lang1033\fs24 15\plain \f1\lang1033\fs24 PD II, 107; (176\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Jungfrauen \plain \f1\super\lang1033\fs24 16-17\plain \f1\lang1033\fs24 PD II, 122. 123. \endash  177\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

