\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 507\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -508\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Officium capitulare
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Officium capitulare extra conuentum\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 In viam et legem mandatorum suorum dirigat nos omnipotens pius pater et misericors dominus\plain \f1\lang1033\fs24 .\plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24 ; Vers \plain \f1\i\lang1033\fs24 Preciosa in conspectu domini mors sanctorum eius \plain \f1\lang1033\fs24 \u8230 \'85; Antiph., Benedictiones, Orationes.}

