\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Cum aduentus domini secundum conuenienciam temporis breuietur et prolongetur\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 complecio et repeticio antiphonarum secundum consuetudinem nostri monasterii sic tenetur\plain \f1\b\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 B quando fuerit littera dominicalis \plain \f1\lang1033\fs24 \u8230 \'85}

