\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 III (Bl. 132-273)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 132\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -137\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermones dominicales de tempore et de sanctis II
\par \pard\fi0\li0\tx4605\ql\ri0\sb240\sa240\itap0 \plain \f1\super\lang1033\fs24\chcbpat8 131\plain \f1\lang1033\fs24 Im Kopfsteg: \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De aduentu domini sermo\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\chcbpat8 127\plain \f1\lang1033\fs24\chcbpat8  = .\plain \f1\i\lang1033\fs24\chcbpat8 i\plain \f1\i\super\lang1033\fs24\chcbpat8 us\plain \f1\lang1033\fs24\chcbpat8 . \plain \f1\i\lang1033\fs24\chcbpat8 Egredietur virga\plain \f1\lang1033\fs24\chcbpat8  (Is 11,1). \plain \f1\i\lang1033\fs24\chcbpat8 Prophetia est de natiuitate beate uirginis, que per uerbum\plain \f1\lang1033\fs24\chcbpat8  \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 egredietur\plain \f1\lang1033\fs24\chcbpat8 \lquote  \plain \f1\i\lang1033\fs24\chcbpat8 designatur\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 per scalam possumus ascendere ad illum altissimum et dulcissimum fructum uentris sui, quod nobis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Schneyer,\plain \f1\lang1033\fs24  Rep. 4, S. 834 Nr. 233: \plain \f1\lang1033\fs24\chcbpat8 Philippus Cancellarius\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 132\plain \f1\lang1033\fs24 (133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 128\plain \f1\lang1033\fs24  = .\plain \f1\i\lang1033\fs24 ii\plain \f1\lang1033\fs24 . \plain \f1\lang1033\fs24\chcbpat8 \u8250 \'9b\plain \f1\i\lang1033\fs24\chcbpat8 De purificatione\plain \f1\lang1033\fs24\chcbpat8 \u8249 \'8b \plain \f1\i\lang1033\fs24\chcbpat8 Adorna thalamum tuum\plain \f1\lang1033\fs24\chcbpat8  (Cantus 006051). \plain \f1\i\lang1033\fs24\chcbpat8 Loquitur sancta ecclesia ad Syon virginalem, scilicet beatam uirginem in statu, in quo fuit ante conceptionem filii dei\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 mundet nos ab omni inquinando mentis et corporis et ornet uirtutibus suis, quod nobis\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24\chcbpat8 133\plain \f1\lang1033\fs24\chcbpat8 (134\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 ) \plain \f1\i\lang1033\fs24\chcbpat8 129\plain \f1\lang1033\fs24\chcbpat8  = .\plain \f1\i\lang1033\fs24\chcbpat8 iii\plain \f1\lang1033\fs24\chcbpat8 . \plain \f1\i\lang1033\fs24\chcbpat8 As\plain \f1\i\lang1033\fs24 cendet\plain \f1\lang1033\fs24  (!, recte descendet) \plain \f1\i\lang1033\fs24 sicut pluvia\plain \f1\lang1033\fs24  (Ps 71,6). \plain \f1\i\lang1033\fs24 Pluuie comparatur Christus, quia pluuia mundat, rigat, fecundat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 scilicet filiorum flagellationem. Vnde\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Uirga tua, et baculus tuus, ipsa me consolata sunt\plain \f1\lang1033\fs24  (Ps 22,4). \endash  \plain \f1\super\lang1033\fs24 134\plain \f1\lang1033\fs24 (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 130\plain \f1\lang1033\fs24  = .\plain \f1\i\lang1033\fs24 iiii\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Schneyer,\plain \f1\lang1033\fs24  Rep. 5, S. 149 Nr. 23: Richardus Fishacre. \endash  \plain \f1\super\lang1033\fs24 135\plain \f1\lang1033\fs24 (136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 131\plain \f1\lang1033\fs24  = .\plain \f1\i\lang1033\fs24 v\plain \f1\lang1033\fs24 .}

