\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Wasserzeichen (geteilt): \plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20 Ochsenkopf, mit einkonturiger Stange und lat. Kreuz, einkonturig, mit Augen innen; \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 Ochsenkopf 1 mit Augen und zweikonturiger Stange, Krone, dar\u252 \'fcber Blume mit sieben Bl\u252 \'fctenbl\u228 \'e4ttern; \plain \f1\super\lang1033\fs20 3\plain \f1\lang1033\fs20 Ochsenkopf 2 mit Augen und einkonturiger Stange, dar\u252 \'fcber Blume mit sieben Bl\u252 \'fctenbl\u228 \'e4ttern; \plain \f1\super\lang1033\fs20 4\plain \f1\lang1033\fs20 Ochsenkopf 3 mit Augen und einkonturiger Stange sowie einkonturiger Schlange, dar\u252 \'fcber Blume mit sieben Bl\u252 \'fctenbl\u228 \'e4ttern, Typ WZIS DE5580-Clm14150_XXXXXX; \plain \f1\super\lang1033\fs20 5\plain \f1\lang1033\fs20 Dreiberg mit zweikonturiger Stange und lateinischem Kreuz, Kreuzbalken gerade, Grundlinie einfach; \plain \f1\super\lang1033\fs20 6\plain \f1\lang1033\fs20 Ochsenkopf 4 mit Augen, oben und unten einkonturige Stange, oben Blume, unten Dreieck mit Schragen, drei Punkten und zwei Kreuzsprossen, Typ WZIS DE5580-Clm14119_XX, DE5580-Clm14127_116, DE5580-Clm14141_XXX, DE5580-Clm14301_188; \plain \f1\super\lang1033\fs20 7\plain \f1\lang1033\fs20 Ochsenkopf 5 mit Augen, mit zweikonturiger Stange und lateinischem Kreuz, dar\u252 \'fcber einkonturiger Stern, sechsstrahlig, Typ WZIS DE5580-Clm14090_177; \plain \f1\super\lang1033\fs20 8\plain \f1\lang1033\fs20 Ochsenkopf 6 mit Augen und zweikonturiger Stange, Stangenende einkonturig, dar\u252 \'fcber Blume mit sieben Bl\u252 \'fctenbl\u228 \'e4ttern, H\u246 \'f6rner nach innen gebogen, Typ WZIS DE5580-Clm14254_X, DE5580-Clm14301_151; \plain \f1\super\lang1033\fs20 9\plain \f1\lang1033\fs20 Ochsenkopf 7 mit Augen und zweikonturiger Stange, Stangenende einkonturig, dar\u252 \'fcber Blume mit sieben Bl\u252 \'fctenbl\u228 \'e4ttern, H\u246 \'f6rner nach au\u223 \'dfen gebo