\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 19\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -23\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Jacobus de Voragine: Dominica II in Quadragesima. Sermo primus
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Quadragesima. \endash  \plain \f1\super\lang1033\fs24 8\plain \f1\i\lang1033\fs24 Miserere mei, fili d\plain \f1\lang1033\fs24 [omine] \plain \f1\i\lang1033\fs24 D\plain \f1\lang1033\fs24 [avid]: \plain \f1\i\lang1033\fs24 filia mea male a demone vexatur\plain \f1\lang1033\fs24  (Mt 15,22). \plain \f1\i\lang1033\fs24 Originaliter recitatiue in missali officio. Pro introductione. Sciendum, quod quos volen\plain \f1\lang1033\fs24\chcbpat8 [te]\plain \f1\i\lang1033\fs24 s adire ad regem pro aliquo arduo supplicantibus\plain \f1\lang1033\fs24  (!, recte supplicio?), \plain \f1\i\lang1033\fs24 accepit secum libenter\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Sicut mulier ista uolens ad Christum accedere et sanitatem filie obtinere\plain \f1\lang1033\fs24  \u8230 \'85 (Lesung durch Wasserschaden erschwert); (Z. 17) \plain \f1\i\lang1033\fs24 Item in presenti ewangelio mencio fit de quinque personis: De Christo, in quo erat magna miseracio, de muliere cha\plain \f1\lang1033\fs24\chcbpat8 [nanea], \plain \f1\i\lang1033\fs24\chcbpat8 in qua erat instans postulatio\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 tercio reuelacione nam in festo omnium sanctorum vidit quidam vir sanctus per reuelacionem, quod beata virgo Maria, que cum angelis omnibusque sanctis processionaliter accessit ad deum omnipotentem supplicatura pro genere humano\plain \f1\lang1033\fs24\chcbpat8 . \endash  Zusatz: \plain \f1\i\lang1033\fs24\chcbpat8 Probatur eciam in legenda sancti patroni nostri Wolfgangi, vbi sanctus Othmarus ei apparuit seque fautorem suorum precum facere asseruit sueque intercessionis cura comparatum ipsum adepturum presignauit\plain \f1\lang1033\fs24\chcbpat8 . \endash  \plain \f1\lang1033\fs24 (22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Conclusio\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Sic ergo\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 karissimi, infrascripto\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 sacro tempore oracioni deuocius quam alio tempore uti exemplo istius mulieris didicimus videlicet sapienter petentes, que nobis necessaria sunt\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ut uitam consequimur eternam\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 quam et dabit nobis, si eligentes,\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 [ut] \plain \f1\i\lang1033\fs24 dixi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 inuenti fuerimus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 ad quam nos perducat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Mt 15,21-28.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: Jacobus de Voragine, Sermones aurei, hrsg. von Rodolphe \plain \f1\scaps\lang1033\fs20 Cluyt\plain \f1\lang1033\fs20 . Mainz: Peter Cholinus, 1616 (VD17 12:108987Y), S. 91b Z. 3-93b.}

