\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 120\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -124\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermo in Mt 15,28
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Quadragesima. \endash  \plain \f1\super\lang1033\fs24 26\plain \f1\i\lang1033\fs24 O mulier, magna est fides tua\plain \f1\lang1033\fs24  (Mt 15,28). \plain \f1\i\lang1033\fs24 Ita ewangelista sanctus Mattheus intonat in capitulo sui ewangelii. Recitantur autem predicta uerba in missali officio ad laudem dei etc. Pro quorum nostrorum introductione sciendum\plain \f1\lang1033\fs24 , \plain \f1\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24 quod tunc fides dicitur esse magna, quando est cum obtinendi fiducia; si hoc non adest, est fides dubitantium siue debilium \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quarto, quia sepe repulsa prestitit. Ideo a domino audire meruit verbum preallegatum dominica uoce\plain \f1\lang1033\fs24 . \endash  (Z. 27) \plain \f1\i\lang1033\fs24 O mulier\plain \f1\lang1033\fs24  (Mt 15,28). \plain \f1\i\lang1033\fs24 Sermo hic diuidetur in tres partes. Primo dicetur ewangelium, secundo, quid tum fides est quottuplex, tertio per quid approbetur et qui fuit effectus fidei\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quartum vitam eternam sine defectione. Ad He\plain \f1\lang1033\fs24\chcbpat8 [\plain \f1\lang1033\fs24 breos\plain \f1\lang1033\fs24\chcbpat8 ] \plain \f1\i\lang1033\fs24\chcbpat8 11\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Sancti per fidem vicerunt regna, operati sunt justiciam\plain \f1\lang1033\fs24  (Hbr 11,33). \endash  Rest der Seite und 124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Zitatbeleg: (a): Jacobus de Voragine, Sermones aurei (s.o. 19\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), hier Dom. 2 sermo 2, S. 94b drittletzte Zeile-S. 95a Z. 28; \plain \f1\lang1033\fs20\chcbpat8 vgl. \plain \f1\scaps\lang1033\fs20\cf1 Schneyer, \plain \f1\lang1033\fs20\cf1 Rep. 3, S. 224 Nr. 45.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 125\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -128\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Johannes Herolt: Sermo in Io 8,59
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Passio Christi. \endash  \plain \f1\super\lang1033\fs24 27\plain \f1\i\lang1033\fs24 Tulerunt lapides iudei\plain \f1\lang1033\fs24  (Io 8,59). \plain \f1\i\lang1033\fs24 Pro introductione scribit Aristoteles 8 Ethicorum d\plain \f1\lang1033\fs24\chcbpat8 [icens]:\plain \f1\i\lang1033\fs24  Vera amicicia habet remuneracionem. Et que verior quam illa quam Christus nobis ostendit pro nobis animam ponens animam secundum illud Johannis 15\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et cum hec fecerimus, obuiabunt verba thematis pro recogitacione prima prius expressa, scilicet\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 \u8218 \'82\plain \f1\i\lang1033\fs24\chcbpat8 Tulerunt lapides\plain \f1\lang1033\fs24\chcbpat8 \lquote \plain \f1\lang1033\fs24 . \endash  (Z. 14) \plain \f1\i\lang1033\fs24 Exhortatiuncula hec diuidetur in tres partes. Primo dicetur ewangelium cum aliquali attinentia, secundo quot quattuor mortes\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 uolebant iudei inferre Christo, tertio de remediis passionis Christi et sic est finis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 item esse ex deo est fidem et dilectionem perseueranter obseruare, sed deus caritas est\plain \f1\lang1033\fs24 . \endash  Textl\u252 \'fccke: Rest von 125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  sowie 126\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24  leer. \endash  \plain \f1\super\lang1033\fs24 a\plain \f1\lang1033\fs24 (127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 6) \plain \f1\i\lang1033\fs24 Pro secundo notandum, quod quattuor mortes uolebant iudei Christo inferre. Primo eum occidere uolebant\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 [cum] \plain \f1\i\lang1033\fs24 gladio\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 de quibus apostolus ad Hebreos 6\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Rursum crucifigentes filium dei\plain \f1\lang1033\fs24  (Hbr 6,6) (Ed.: S. 263a Z. 11-S. 263b letzte Zeile) \endash  \plain \f1\super\lang1033\fs24 b\plain \f1\lang1033\fs24 (127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 6-10) \plain \f1\i\lang1033\fs24 Nam, hew, plures sunt, qui passionem Christi non honorant\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed malus christianus blasphemans tociens, quociens execrabiliter iurat\plain \f1\lang1033\fs24  (Ed. S. 873b Z. 7-19). \endash  \plain \f1\super\lang1033\fs24 c\plain \f1\lang1033\fs24 (127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 11-29) \plain \f1\i\lang1033\fs24 Et tales grauiter puniendi sunt, quemadmodum exemplum habemus in ueteri testamento Leuitico 24\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Cum quidam blasphemasset nomen domini, adductus est ad Moy\u776 ?sen at Aaron\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et si hoc deus in puero quinque annorum \plain \f1\i\lang1033\fs24\chcbpat8 [sic vindicavit], quid de adultis sit facturus uel faciet\plain \f1\lang1033\fs24\chcbpat8  (Ed. S. 705b Z. 9-S. 706a Z. 12). \endash  \plain \f1\super\lang1033\fs24\chcbpat8 d\plain \f1\lang1033\fs24\chcbpat8 (128\plain \f1\super\lang1033\fs24\chcbpat8 r\plain \f1\lang1033\fs24\chcbpat8 -128\plain \f1\super\lang1033\fs24\chcbpat8 v\plain \f1\lang1033\fs24\chcbpat8  Z. 11) \plain \f1\i\lang1033\fs24\chcbpat8 Tercio videndum est de remediis passionis Christi, nam remedium est contra omnia peccata. Primo contra superbiam, quia Christi humilitas reprobat nostram superbiam\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 ut veram remunceracionem eius amicicie rependamus, ne ingrati videamur\plain \f1\lang1033\fs24\chcbpat8 . \endash  \plain \f1\super\lang1033\fs24\chcbpat8 e\plain \f1\lang1033\fs24\chcbpat8 (Z. 12-16) \plain \f1\i\lang1033\fs24\chcbpat8 Nam Bernardus in persona Christi\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 cum te ingratum experior\plain \f1\lang1033\fs24\chcbpat8  (Ed. S. 283b Z. 31-39). \endash  \plain \f1\super\lang1033\fs24 f\plain \f1\lang1033\fs24 (Z. 18-28) \plain \f1\i\lang1033\fs24 Legimus de quodam heremita sancte vite, qui Christo supplicat, ut sibi ostenderet\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et quilibet homo mihi exhibet mihi\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 acceptissimum seruicium, cum quottidie rememoraueritis deuote passionem meam et disparuit\plain \f1\lang1033\fs24  (Ed. S. 283a). \endash  129\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Johannes Herolt, Sermones Discipvli de tempore et sanctis. Mainz 1612 (VD17 12:641136H): (a) Dominica in passione domini. Sermo 45, S. 261b-267a. \endash  (b) De iustitia. Sermo 154, S. 869a-875a. \endash  (c) De blasphemia. Sermo 123, S. 699b-706b. \endash  (d) Nicht identifiziert. \endash  (e-f) De memoria passionis Christi. Sermo 48, S. 279a-283b.}

