\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 146\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermo in Mt 9,18 (Predigtfragment)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 33\plain \f1\i\lang1033\fs24 Domine, filia mea modo defuncta est\plain \f1\lang1033\fs24  (Mt 9,18). \plain \f1\i\lang1033\fs24 Pro introductione thematis nota, quod dicit filia et non ancilla, ut plus moueat Christum adveniendum secum. Sed dicens Marcus quinto capitulo dicit\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Procidit ad pedes eius\plain \f1\lang1033\fs24  \u8230 \'85 (Mc 5,22-23). \plain \f1\i\lang1033\fs24 Et Lucas octavo capitulo dicit\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Venit vir, cui nomen Yairus\plain \f1\lang1033\fs24  \u8230 \'85 (Lc 8,41-42) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 dicens\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Filia mea modo defuncta est\plain \f1\lang1033\fs24  (Mt 9,18). \plain \f1\i\lang1033\fs24 Hec fuere verba thematis\plain \f1\lang1033\fs24 // Wohl Textabbruch. \endash  146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 149\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -151\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Johannes Herolt: Sermo in Io 8,59
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Passio Christi. \endash  \plain \f1\super\lang1033\fs24 34\plain \f1\i\lang1033\fs24 Tulerunt lapides iudei \plain \f1\lang1033\fs24 (Io 8,59). \plain \f1\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24 Aristoteles octavo \plain \f1\lang1033\fs24\chcbpat8 [libro]\plain \f1\i\lang1033\fs24  Ethicorum dicit, vera amicicia habet remuneracionem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 de quibus apostolus dicit ad Hebreos sexto\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\chcbpat8 [capitulo]\plain \f1\lang1033\fs24 :\plain \f1\i\lang1033\fs24  Rursum crucifigentes filium dei\plain \f1\lang1033\fs24  (Hbr 6,6). \endash  \plain \f1\super\lang1033\fs24 b\plain \f1\lang1033\fs24 (150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 25-28) \plain \f1\i\lang1033\fs24 Et hoc faciunt mali Christiani, qui passionem Christi non honorant\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quociens execrabiliter iurant\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 c\plain \f1\lang1033\fs24 (Z. 28-150\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 13) \plain \f1\i\lang1033\fs24 Hec autem iuramenta ab omnibus diligenter sunt vitanda et prohibenda\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et amplius dominus meus Ihesus Christus a nullo hominum per talem blasphemiam offenderetur\plain \f1\lang1033\fs24 . \endash  (150\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 14-151\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Io 8,46-59.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Johannes Herolt, Sermones Discipvli de tempore et sanctis. Mainz 1612 (VD17 12:641136H): (a) Dominica in passione domini. Sermo 45, S. 261b-267a, hier S. 261a-263b letzte Zeile; (b) De iustitia. Sermo 154, S. 869a-875a, hier S. 873b Z. 7-19; (c) De blasphemia. Sermo 123, S. 699b-706b, hier S. 700a Z. 18-S. 700b Z. 16.}

