\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Marienpredigt. \endash  \plain \f1\super\lang1033\fs24 40\plain \f1\i\lang1033\fs24 Nota, quod multa sunt consilia Marie, quibus consulit nobis animarum salutem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 nolentibus enim ei obedire dictura est aliquando illud Prouerbiorum i\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Despexistis omne consilium meum\plain \f1\lang1033\fs24  \u8230 \'85 (Prv 1,25f.)// Textabbruch; Rest der Seite leer.
