\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8\cf1 197\plain \f1\super\lang1033\fs24\chcbpat8\cf1 v\plain \f1\lang1033\fs24\chcbpat8\cf1  \plain \f1\b\lang1033\fs24\chcbpat8\cf1 Sermo de sancta Elisabeth (Predigtframent)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\chcbpat8 Nachtrag von N\plain \f1\super\lang1033\fs24\chcbpat8 2\plain \f1\lang1033\fs24\chcbpat8 : \plain \f1\i\lang1033\fs24\chcbpat8 Swadeo tibi emere a me\plain \f1\lang1033\fs24\chcbpat8  (Apc 3,18). \plain \f1\i\lang1033\fs24\chcbpat8 Apocalypsis tertio\plain \f1\lang1033\fs24\chcbpat8  [capitulo] \plain \f1\i\lang1033\fs24\chcbpat8 originaliter recitatiue autem assumuntur siue resumuntur in laudem dei omnipotentis ac honorem beatissime matris Elisabeth\plain \f1\lang1033\fs24\chcbpat8  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\chcbpat8 sed magnam caritatem suam nobis manifestat dicens\plain \f1\lang1033\fs24\chcbpat8 : \plain \f1\i\lang1033\fs24\chcbpat8 Vnacumque in paterna dei omnipotentis verba propterea etc\plain \f1\lang1033\fs24\chcbpat8 .}

