\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 238\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermo in Ez 17,24 (Predigtfragment)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 53\plain \f1\i\lang1033\fs24 Splendere faciam lignum aridum\plain \f1\lang1033\fs24  (vgl. Ez 17,24). \plain \f1\i\lang1033\fs24 Ad laudem honoremque sancte crucis uerba predicta proposui, quia in ea salus, uita et resurrectio nostra est, per quam saluati et liberati sumus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 res, que care soluuntur, non dantur nisi pro magno\plain \f1\lang1033\fs24 // Textabbruch. \endash  Rest der Seite sowie 239\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -243\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer.}

