\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Kalenderverse \plain \f1\i\lang1033\fs24 Ianuarius habet dies xxxi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 luna xxx \plain \f1\lang1033\fs24 \u8230 \'85; am Monatsende jeweils Doppelvers (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Baptismo Cristi gaudent solemnia Iani \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Walther, \plain \f1\lang1033\fs24 Initia carminum 2026; links r\u246 \'f6mische Tagesangaben, Sonntagsbuchstaben; rechts Tierkreiszeichen. \u8210 - Rot u.a. \plain \f1\i\lang1033\fs24 Erhardi epi.\plain \f1\lang1033\fs24  08.01.; \plain \f1\i\lang1033\fs24 Georii mr.\plain \f1\lang1033\fs24  24.04.; \plain \f1\i\lang1033\fs24 Margarethe virginis et mr.\plain \f1\lang1033\fs24  12.07.; \plain \f1\i\lang1033\fs24 Emmerami epi. et mris.\plain \f1\lang1033\fs24  22.09.; \plain \f1\i\lang1033\fs24 Translacio .s. Ruperti epi. et mr. \plain \f1\lang1033\fs24 24.09.; \plain \f1\i\lang1033\fs24 Dyonisii et sociorum eius \plain \f1\lang1033\fs24 09.10.; \plain \f1\i\lang1033\fs24 Wolfgangi epi. \plain \f1\lang1033\fs24 31.10.; \plain \f1\i\lang1033\fs24 Virgilii epi. et confess.\plain \f1\lang1033\fs24  27.11.; au\u223 \'dferdem bemerkenswert \plain \f1\i\lang1033\fs24 Ioseph nutricii domini \plain \f1\lang1033\fs24 19.03.; \plain \f1\i\lang1033\fs24 Castuli mris. \plain \f1\lang1033\fs24 26.03.; \plain \f1\i\lang1033\fs24 Ruperti epi. \plain \f1\lang1033\fs24 27.03.; \plain \f1\i\lang1033\fs24 Adalberti epi. et mr. \plain \f1\lang1033\fs24 24.04.; \plain \f1\i\lang1033\fs24 Petri mris. ordinis predicatorum \plain \f1\lang1033\fs24 29.04.; \plain \f1\i\lang1033\fs24 Translacio .s. Elizabeth\plain \f1\lang1033\fs24  02.05.; \plain \f1\i\lang1033\fs24 Gothardi epi. et. conf. \plain \f1\lang1033\fs24 05.05.; \plain \f1\i\lang1033\fs24 Gallicani mr.\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Translacio .s. Eligii epi. \