\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 139\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 [59\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 -61\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ]\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24\cf1 Preces et orationes post litaniam dicendae
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Preces; (140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Orationes. \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus cui proprium est \plain \f1\lang1033\fs24 \u8230 \'85 Corpus orationum 1143; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro prelatis\plain \f1\lang1033\fs24 \u8249 \'8b 3938c; (140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro salute viuorum\plain \f1\lang1033\fs24 \u8249 \'8b 4587c; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro pace\plain \f1\lang1033\fs24 \u8249 \'8b 1088a; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro statu ecclesie\plain \f1\lang1033\fs24 \u8249 \'8b 2404b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Contra tribulaciones\plain \f1\lang1033\fs24 \u8249 \'8b 4528; \u8250 \'9b\plain \f1\i\lang1033\fs24 Contra fulgura et tempestates\plain \f1\lang1033\fs24 \u8249 \'8b 5a; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro opere cottidiano\plain \f1\lang1033\fs24 \u8249 \'8b 74; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro omnibus fidelibus defunctis\plain \f1\lang1033\fs24 \u8249 \'8b 16; \u8250 \'9b\plain \f1\i\lang1033\fs24 Generalis\plain \f1\lang1033\fs24 \u8249 \'8b 1600; (141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro satu \plain \f1\lang1033\fs24 (situ? statu?)\plain \f1\i\lang1033\fs24  loci\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Domine deus omnipotens qui elegisti locum istum ad seruiendum tibi \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\i\lang1033\fs24 Custodi domine locum istum ab omni peccato \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\i\lang1033\fs24 Tu domine qui hanc congregacionem ad glorificandum nomen sanctum tuum in hoc loco adunari permisisti \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\i\lang1033\fs24 Domine\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  ne respicias peccata nostra\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 et per intercessionem sanctorum tuorum Emerammi\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  Dionisii\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  Wolfgangi atque omnium sanctorum tuorum quorum reliquie sunt in isto loco adiuua nos sicut tu vidis necessitatem nostram. Qui viuis \plain \f1\lang1033\fs24 \u8230 \'85}

