\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 [61\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -63\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ]\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Suffragia\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Suffragia per circulum anni\plain \f1\lang1033\fs24 \u8249 \'8b. Jeweils eine oder mehrere Antiphonen, Versiculum und Oration (nur diese in der Beschreibung zitiert), zun\u228 \'e4chst als Haupttext zu Vesper bzw. (142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Matutin f\u252 \'fcr das ganze Jahr, dann in abgek\u252 \'fcrzter Form (und daher in diese Beschreibung nicht aufgenommen) (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) speziell f\u252 \'fcr Advent und Weihnachten und (143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) f\u252 \'fcr die Nachweihnachts- und Osterzeit, immer wieder in den sechs gleichen Intentionen neu formuliert \u8250 \'9b\plain \f1\i\lang1033\fs24 De s. cruce\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus qui crucem sanctam ascendisti \plain \f1\lang1033\fs24 \u8230 \'85 bzw. Corpus orationum 4221b; \u8250 \'9b\plain \f1\i\lang1033\fs24 De beata virgine\plain \f1\lang1033\fs24 \u8249 \'8b 706 bzw. 2649; \u8250 \'9b\plain \f1\i\lang1033\fs24 De sanctis patronis nostris\plain \f1\lang1033\fs24 \u8249 \'8b 4703a bzw. (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Beatorum pontificum tuorum Emerammi Dionysii Wolfgangi et aliorum sanctorum qui in presenti requiescunt ecclesia nos\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  quesumus\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  foueat preciosa confessio \plain \f1\lang1033\fs24 \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Benedicto\plain \f1\lang1033\fs24 \u8249 \'8b 1432 bzw. 3164; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro pace\plain \f1\lang1033\fs24 \u8249 \'8b 1088a; \u8250 \'9b\plain \f1\i\lang1033\fs24 De omnibus sanctis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Omnipotens sempiterne deus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 nos famulos tuos dextera potencie tue a cunctis protege periculis \plain \f1\lang1033\fs24 \u8230 \'85 bzw. \plain \f1\i\lang1033\fs24 Fac nos\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  quesumus\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  beate Marie semper virginis subsidiis attolli\plain \f1\lang1033\fs24  \u8230 \'85; 143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

