\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Casus breves decretalium
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 de sancta trinitate et fide catholica\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Firmiter. Vide in glo\plain \f1\lang1033\fs24 [ssa] \plain \f1\i\lang1033\fs24 originali. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 D\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\ul\lang1033\fs24 ampnamus\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 abbas sumendo decretalem comprehendit solum finem \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 quasi omnia Jura. Expliciunt casus breues decretalium.\plain \f1\lang1033\fs24  \plain \f2\lang1033\fs24 \endash \plain \f1\lang1033\fs24  (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit liber Sextus de summa trinitate et fide katholica\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Fideli. Errores graecorum qui dicebant spiritum sanctum procedere a solo patre extirpato per canones\plain \f1\lang1033\fs24  ... (118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipiunt Clementine de summa trinitate et fide katholica\plain \f1\lang1033\fs24 \u8249 \'8b ... \plain \f1\i\lang1033\fs24 Expliciunt Clementin\plain \f1\lang1033\fs24 [e]. \u8250 \'9b\plain \f1\i\lang1033\fs24 Expliciunt casus breues decretalium libri VI et clementinarum secundum Johannem Andree doctorem Bononiensem\plain \f1\lang1033\fs24 \u8249 \'8b. \endash  78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Kurze Erkl\u228 \'e4rungen zu Dekretalen des Liber Extra, Liber Sextus und den Clementinen. Der Verweis auf Johannes Andreae scheint sich nur auf die Clementinen zu beziehen.}

