\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -97\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Sententiae
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Sequuntur aliquot sententiae\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Plinius. Nimia cura deterit magis\plain \f1\lang1033\fs24 ..., \plain \f1\super\lang1033\fs24 2\plain \f1\i\lang1033\fs24 Seneca. Nemo est melior altero\plain \f1\lang1033\fs24  ..., \plain \f1\super\lang1033\fs24 3\plain \f1\i\lang1033\fs24 Idem epistola LII. Voluptates precipue exturba\plain \f1\lang1033\fs24  ..., \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 (95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Pauper Henricus. Nonne sua licite ... \endash  ... stultus amator amat\plain \f1\lang1033\fs24  (Henricus de Septimelensis, De diversitate fortunae et philosophiae consolatione lib. 2 Vers 99-104, lib. 3, Vers 18), \plain \f1\super\lang1033\fs24 11 \plain \f1\i\lang1033\fs24 Qui nimis est humilis hic pro stulto reputatur, \plain \f1\lang1033\fs24 ... \plain \f1\super\lang1033\fs24 31\plain \f1\i\lang1033\fs24 Eccles. VII. Inueni mulierem amariorem morte\plain \f1\lang1033\fs24  ... (Eccles. VII,27).  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Als Quellen der Sentenzen sind angegeben: Augustinus, Bibel, Gregorius Magnus, Henricus Septimelensis, Macrobius, Martialis, Philipp Melanchthon, Plinius, Seneca.}

