\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa60\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Charitas\plain \f1\lang1033\fs24 \u8249 \'8b mit Begriffsschema; (146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Castitas\plain \f1\lang1033\fs24 \u8249 \'8b ohne Petrarca-Zitat; (151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Causa\plain \f1\lang1033\fs24 \u8249 \'8b; (152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ceruicosus\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Clementia\plain \f1\lang1033\fs24 \u8249 \'8b; (153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Cogitacio\plain \f1\lang1033\fs24 \u8249 \'8b; (154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Confessio\plain \f1\lang1033\fs24 \u8249 \'8b; (160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Coniectura\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Consanguinitas\plain \f1\lang1033\fs24 \u8249 \'8b; (161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Conscientia\plain \f1\lang1033\fs24 \u8249 \'8b; (161\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Consiliarius\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Consilium\plain \f1\lang1033\fs24 \u8249 \'8b; (165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Consolator\plain \f1\lang1033\fs24 \u8249 \'8b; (165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Constantia\plain \f1\lang1033\fs24 \u8249 \'8b; (166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24