\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Vor den Gebeten vier (?) Gesangsanf\u228 \'e4nge, lesbar: // \plain \f1\i\lang1033\fs24 humiliter\plain \f1\lang1033\fs24  // \plain \f1\i\lang1033\fs24 antiphona\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 veni sancte spiritus\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Versiculum\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Emitte spiritum tuum\plain \f1\lang1033\fs24 . Orationes: \plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 O rex glorie et domine virtutum\plain \f1\lang1033\fs24  ... (vgl. \plain \f1\scaps\lang1033\fs24 Haimerl\plain \f1\lang1033\fs24 , Fr\u246 \'f6mmigkeit, S. 125 Anm. 756); \plain \f1\i\lang1033\fs24 Alia oracio\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Domine qui dixisti\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 aperies tuum\plain \f1\lang1033\fs24  ...; \plain \f1\i\lang1033\fs24 Oracio S. Thome de Aquino\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Largire mihi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 mitissime Deus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 intellectum te cognoscentem\plain \f1\lang1033\fs24  ...}

