\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 3\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -20\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes de vita Christi\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 \lquote O domine\rquote 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 domine, qui multitudine tue pietatis assumere dignatus es\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, de uirgine natus, per partum tuum obsecro\plain \f1\lang1033\fs24\cf1  ...; (4\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, tenera membra induens nascendo\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, paruulus factus per infantiam\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, pauper factus\plain \f1\lang1033\fs24\cf1  ...; (4\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, uagiens nuper genitus \plain \f1\lang1033\fs24\cf1 ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, arridens matri\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, pannis inuolutus\plain \f1\lang1033\fs24\cf1  ...; (5\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, positus in angustia presepis\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, fugens \plain \f1\lang1033\fs24\cf1 (!)\plain \f1\i\lang1033\fs24\cf1  ubera matris\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, balneis per balneum\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, recumbens in sinum matris\plain \f1\lang1033\fs24\cf1  ...; (5\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, uix ualens loqui lingua balbuciente\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, cursitans circa matrem more paruulorum\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, uix ambulans\plain \f1\lang1033\fs24\cf1  ...; (6\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, uolens circumcidi\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, deosculans dulcia labia genitricis matris\plain \f1\lang1033\fs24\cf1  ...; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, circumcingens colla matris dilecte\plain \f1\lang1033\fs24\cf1  ...; (6\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 O\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  domine, pas