\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 52\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -75\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Cantus et orationes de Sancta Cruce
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 52\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Oratio in parasceve\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Origo omnium bonorum, benigne Ihesu, fili dei uiui, perfice in me\plain \f1\lang1033\fs24\cf1  ...; (54\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps \plain \f1\i\lang1033\fs24\cf1 Beatus uir\plain \f1\lang1033\fs24\cf1 ; \plain \f1\i\lang1033\fs24\cf1 Crux christi aperuit nobis ianuas celi\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 or\plain \f1\lang1033\fs24\cf1 [atio]: \plain \f1\i\lang1033\fs24\cf1 Deus qui beate crucis patibulum quod prius celestis erat ad penam\plain \f1\lang1033\fs24\cf1  ... (PL 78, Sp. 619C); (54\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu Christe, redemptor bone, saluator optime, recordare humane fragilitatis\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (55\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 68,2; \plain \f1\i\lang1033\fs24\cf1 O uenerabilis crux sancta, uera et certa salus credentium\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Respice, domine, super cunctam familiam tuam\plain \f1\lang1033\fs24\cf1  ...; (56\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 7778; \plain \f1\i\lang1033\fs24\cf1 Comple in me hoc uerbum pietatis\plain \f1\lang1033\fs24\cf1  ...; (56\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Arbor decora\plain \f1\lang1033\fs24\cf1  ... AH 50 Nr. 67 Str. 5; Ps 23,1; (57\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Absolue, domine, nostrorum uincula delictorum \plain \f1\lang1033\fs24\cf1 \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Munda me\plain \f1\lang1033\fs24\cf1  ... \plain \f1\i\lang1033\fs24\cf1 per amorem sancte passionis et crucis tue\plain \f1\lang1033\fs24\cf1  ...; (57\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Beati quorum\plain \f1\lang1033\fs24\cf1 . CAO 3628; (58\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Gregem tuum. Resiste, domine, per uirtutem sancte passionis\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (58\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) CAO 4744, 1287, Forts. wie PL 78 Sp. 138B; (59\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Defende me, domine, armis celestibus\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu Christe, per amorem sancte passionis et crucis tue non permitte me\plain \f1\lang1033\fs24\cf1  \u8230 \'85 vgl. Augsburg, SuStB, 8\u176 \'b0 Cod. 130, 175\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ; (59\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) CAO 5353; Cantus g001259c; (60\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 5061; \plain \f1\i\lang1033\fs24\cf1 Presta, quesumus omnipotens deus ut qui nostris excessibus\plain \f1\lang1033\fs24\cf1  \u8230 \'85(PL 78, Sp. 81A); \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu Christe, qui in cruce totum renouasti\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 saeculum \plain \f1\lang1033\fs24\cf1 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 uitam eternam possidere\plain \f1\lang1033\fs24\cf1 ; (61\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 3946, 1962, 1290; \plain \f1\i\lang1033\fs24\cf1 Quesumus, omnipotens deus, ut qui in tot aduersis \plain \f1\lang1033\fs24\cf1 \u8230 \'85; (61\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Ihesu Nazarene, pietate plene, qui es uerbum summi patris et ille magnus lapis \plain \f1\lang1033\fs24\cf1 \u8230 \'85; (62\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 4398, 6049, 6448a;  \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu Christe, precor te per uirtutem illam, quam operatus es\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (62\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 81,1; CAO 4690 (Var.), (63\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) 3104; \plain \f1\i\lang1033\fs24\cf1 Deus qui per sanguinem\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Sana me, domine, per uirtutem sancte crucis\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (63\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 91,2, CAO 8189, Ps 47,15; (64\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Concede quaesumus\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 O piissime Ihesu qui me miseram tuo precioso sanguine redemisti \plain \f1\lang1033\fs24\cf1 \u8230 \'85; (64\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) CAO 2522, Ps 118,1; (65\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps 101,2, CAO 1953, 8013 (Var.); (65\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Exaudi, o bone Ihesu, orationem meam \u8230 \'85 inuocantem te pro requie anime mee \plain \f1\lang1033\fs24\cf1 \u8230 \'85; (66\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 1951/Chevalier 3985; \plain \f1\i\lang1033\fs24\cf1 Reminiscere \plain \f1\lang1033\fs24\cf1 \u8230 \'85; (66\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) AH 53 Nr. 56 Str. 9; \plain \f1\i\lang1033\fs24\cf1 Omnes mente humili gratias agimus\plain \f1\lang1033\fs24\cf18  \u8230 \'85\plain \f1\lang1033\fs24\cf1 ; (67\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 7279 (?), 4016; \plain \f1\i\lang1033\fs24\cf1 Tua nos deus misericordia ab omni surreptione uetustatis\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (67\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Ihesu piissime, redemptor noster unice, respice in me\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (68\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps 121,1, CAO 2432, 1292; \plain \f1\i\lang1033\fs24\cf1 Omnipotens sempiterne deus, da nobis ita\plain \f1\lang1033\fs24\cf1  \u8230 \'85(PL 78, Sp. 81A); (68\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Caput totius misericordie, Ihesu fili David qui miserum et peccatorem sedulo ad te clamantem\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (69\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 1953, Ps 98,5; \plain \f1\i\lang1033\fs24\cf1 Deus cuius filius per tropheum crucis mundum redemit\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (69\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu, sana animam meam que a demonio uexatur\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (70\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Voce mea\plain \f1\lang1033\fs24\cf1 , CAO 1961, Ps 145,10; (70\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Perpetua pace nos\plain \f1\lang1033\fs24\cf1  [quaesumus], \plain \f1\i\lang1033\fs24\cf1 domine, custodi\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Ihesu, bone saluator noster optime, cui soli decenter competit miseros fouere\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (71\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) CAO 4019; (72\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Deprecationem nostram\plain \f1\lang1033\fs24\cf1  \u8230 \'85 (PL 78, Sp. 81A); (72\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Pater noster. Credo;\plain \f1\lang1033\fs24\cf1  (72\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Per misericordiam qua deus ante secula homo\plain \f1\lang1033\fs24\cf1  [dignatus es] \plain \f1\i\lang1033\fs24\cf1 fieri \plain \f1\lang1033\fs24\cf1 \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24\cf1 ...et quam dulcis est multitudo miserationum tuarum\plain \f1\lang1033\fs24\cf1 . \endash  (74\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 OR\plain \f1\lang1033\fs24\cf1 \u8249 \'8b[atio] \plain \f1\i\lang1033\fs24\cf1 Domine deus omnipotens, rex clementissime\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 placatus super me peccatricem et uniuersos consanguineos familiaresque meos\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (74\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Obsecro te, domine \u8230 \'85 ut dimittas mihi delicta mea preterita presentia \u8230 \'85 custodi os meum et linguam meam \u8230 \'85 ut placeant uerba mea in conspectu principum et om\plain \f1\lang1033\fs24\cf1 (75\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24\cf1 nium populorum\plain \f1\lang1033\fs24\cf1 .
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Mit Ausnahme der letzten zwei Gebete auch \u252 \'fcberliefert in der Hs. Graz, UB, Ms. 1501, 38\plain \f1\super\lang1033\fs20\cf1 v\plain \f1\lang1033\fs20\cf1 -54\plain \f1\super\lang1033\fs20\cf1 v\plain \f1\lang1033\fs20\cf1  (12. Jh., vermutlich aus Kloster Seckau?); trotz des sorgf\u228 \'e4ltig wirkenden Schriftbildes weist diese Hs. gegen\u252 \'fcber der Grazer Hs. viele Abweichungen auf (Ps./Ges\u228 \'e4nge h\u228 \'e4ufig ausgelassen, Varianten); einzelne Gebete auch \u252 \'fcberliefert in Ebstorf, KlosterB, IV,16, 54\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 -68\plain \f1\super\lang1033\fs20\cf1 v\plain \f1\lang1033\fs20\cf1  (14. Jh.).}

