\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 75\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -79\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Cantus et orationes in Palmis\plain \f1\lang1033\fs24\cf1  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In Palmis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b. Ps 21,2; Ps 26,1; Ps 37,2;\plain \f1\lang1033\fs24  Ps \plain \f1\lang1033\fs24\cf1 43,2; Ps 87,2; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Or\plain \f1\lang1033\fs24\cf1 \u8249 \'8b[atio] \plain \f1\i\lang1033\fs24\cf1 O domine clementissime rex regum ..., colunt te in hostiis\plain \f1\lang1033\fs24\cf1  ...; (77\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Salue rex, fabricator mundi \u8729 \'b7 salue saluator mundi \u8729 \'b7 salue redemptor mundi, qui uenisti redimere nos, redime me\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (78\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) CAO 6421, Ps 54,3, Ps 66,2; (78\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) CAO 1437 (Var.); \plain \f1\i\lang1033\fs24\cf1 Laudant te omnes angeli \u8230 \'85 et ego licet mortalis homo benedico, magnifico, adoro gratias agens peto, ut\plain \f1\lang1033\fs24\cf1  (79\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 dimittas omne delictum peccatorum meorum\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 me indignam saluam facias\plain \f1\lang1033\fs24\cf1 ; \plain \f1\i\lang1033\fs24\cf1 Mundus deus, munda me, sanctus deus, sanctifica me, fortis deus,\plain \f1\lang1033\fs24\cf1  (79\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 conforta me\plain \f1\lang1033\fs24\cf1  \u8230 \'85}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red146\green208\blue80;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 79\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -85\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Cantus et orationes in purificatione S. Mariae
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In pvrificatione sancte Marie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b Ps 23,1, Ps 98,1; \plain \f1\i\lang1033\fs24\cf1 Dominus meus et deus meus Ihesu Christe, te lau\plain \f1\lang1033\fs24\cf1 (80\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24\cf1 dant angeli, te adorant uirtutes angelorum ... te ego indigna glorifico\plain \f1\lang1033\fs24\cf1  ...; (81\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Presta mihi domine, per intercessionem iusti Symeonis\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (82\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 O domina totius orbis, per quam humano generi salus aduenit ... ego indigna clamo ad te \plain \f1\lang1033\fs24\cf1 ...; (82\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 O mundi domina, tu solite pietatis funge officio\plain \f1\lang1033\fs24\cf1  ...; (83\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Piissima domina, extingue in me incendium libidinis et malicie in extrema hora\plain \f1\lang1033\fs24\cf1  ...; (83\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Oratio\plain \f1\lang1033\fs24\cf1 \u8249 \'8b. \plain \f1\i\lang1033\fs24\cf1 Deus qui de sinu patris missus es\plain \f1\lang1033\fs24\cf1  .... (84\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24  tu domine, dignare inter me et famulas tuas stabilem firmare concordiam et omne odium quod ad me de\plain \f1\lang1033\fs24 (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 clinant mitigare et extinguere\plain \f1\lang1033\fs24  .\plain \f1\lang1033\fs24\cf1 .. \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 qui persecuntur me\plain \f1\lang1033\fs24\cf1 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red146\green208\blue80;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 85\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -96\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Cantus et orationes in resurrectione Domini 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 De res\plain \f1\lang1033\fs24 \u8249 \'8b[urrectione] \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, fili dei altissimi, cuius eternum cum patre fuit consilium, ut nostre mortalitatis carne suscepta redimeres mundum diabolica tirannide captiuatum\plain \f1\lang1033\fs24  \u8230 \'85; (89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Nunc igitur, sanctissime Petre, memor humane sortis ecclesie \u8230 \'85\plain \f1\lang1033\fs24 ; (90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Deus meus et dominus meus, Ihe[su] Christe, filius dei uiui, te suspiro, te esurio, te sitio, te uidere cupio. Et sicut mater\plain \f1\lang1033\fs24  \u8230 \'85 teilweise \u228 \'e4hnlich Anselm von Canterbury, Oratio ad deum XII, PL 158 Sp. 885C; (92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CAO 7079; (92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) CAO 2948; \plain \f1\i\lang1033\fs24 Gaudeamus et exultemus\plain \f1\lang1033\fs24 ; Cantus g00715, g00715a; \plain \f1\i\lang1033\fs24 Pater noster;\plain \f1\lang1033\fs24  CAO 8085; (93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Per gloriam sanctissime resurrectionis tue, per humilitatem\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\i\lang1033\fs24 O rex glorie, domine virtutum, fortis preliator, o potens inferni triumphator\plain \f1\lang1033\fs24  \u8230 \'85; (95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, uita et resurrectio animarum et corporum nostrorum, resuscita animam meam a uiciorum sepulchris\plain \f1\lang1033\fs24  \u8230 \'85; (95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Or\plain \f1\lang1033\fs24 \u8249 \'8b[atio] \plain \f1\i\lang1033\fs24 Domine, rogo te per amorem sancte tue resurrectionis et sancte genitricis tue et per gaudium omnis creature tue\plain \f1\lang1033\fs24  \u8230 \'85}

