\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 15\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Oremus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 pro fidelibus defunctis\plain \f1\lang1033\fs24\cf1  Ps 114,1-9; (15\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 119,1-5; (16\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps 120,1-7; (16\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 129,1-3; (17\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps 137,1-8; CAO 4159, 4115; (18\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) Ps 145,2-10; (18\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) Ps 123,1-8; (19\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro ep\plain \f1\lang1033\fs24\cf1 \u8249 \'8b[iscop]\u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 o\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 1757c, \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro sacerdote\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 913, \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro abbatibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 3809; (20\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro annivers\plain \f1\lang1033\fs24\cf1 \u8249 \'8b[ario] CO 1251; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro fratribus nostre congregationis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 2205 (var.), (20\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro parentibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 1903, 3116b; \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 pro constructoribus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b CO 4701; (21\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b\plain \f