\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) R 38; (42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 3,2-9; (42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 laudes\plain \f1\lang1033\fs24 \u8249 \'8b Ps 50,3-21; (44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 64,2-14; (45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) R 14; Ps 62,2-12; (46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ps 66,2-8; (46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Is 38,10-20; (47\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ps 148,1 - Ps 150,6; (49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Lc 1,68-79; Lc 11,25-26; (50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ps 129,1; Ps 12,1-6; (51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Sap 5,9-11; Iob 19,25-27; 22,1; 7,3; (51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) R 72; Eccl 12,1 u. 12,7; (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) R 24; \u8250 \'9b\plain \f1\i\lang1033\fs24 In secundo nocturno\plain \f1\lang1033\fs24 \u8249 \'8b Is 26,19; R 32; (52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Os 13,14-15; (53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) R 57; Dn 12,2; R 68; Ps 53,3; (53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 in tertio nocturno\plain \f1\lang1033\fs24 \u8249 \'8b I Cor 15,22-23; (54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) I Cor 15,51-52; Ps 102,14-15; R 82; Lc 5,2-5; R 83, R 38.
