\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 97\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -105\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Meditatio passionis pro infirmis vel itinerantibus
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Meditatio passionis Christi pro infirmis uel itinerantibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b. \plain \f1\i\lang1033\fs24\cf1 Omnipotens et misericors deus, da michi peccatori cum magna conpunctione\plain \f1\lang1033\fs24\cf1  [!] \plain \f1\i\lang1033\fs24\cf1 cordis et ardenti desiderio ... \endash  ... tibi dicamus graciarum actiones immensas amen\plain \f1\lang1033\fs24\cf1 .
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Parallel\u252 \'fcberlieferung BSB: Clm 3564, 256\plain \f1\super\lang1033\fs20\cf1 va\plain \f1\lang1033\fs20\cf1  (vgl. \plain \f1\scaps\lang1033\fs20\cf1 Rauner\plain \f1\lang1033\fs20\cf1 , Catalogus III, s.n. 3,1, S. 270, mit weiterer \u220 \'dcberlieferung); Clm 4634, 50\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 ; Clm 14826, 54\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 .}

