\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 115\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -118\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secuntur alie oraciones\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (116\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine deus, qui solus cuncta potes\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Obsecro, domine Ihesu Christe, per viam\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (116\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Rogo te, domine Ihesu Christe, per sanctam natiuitatem\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Obsecro te, domine Ihesu Christe, per baptismum tuum\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (117\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine Ihesu Christe, imploro te per sanctos\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (117\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Rogo te, domine Ihesu Christe, per reditum tuum\plain \f1\lang1033\fs24\cf1  \u8230 \'85; \plain \f1\i\lang1033\fs24\cf1 Oro te, domine Ihesu Christe, per prudenciam\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (118\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 O deus terribilis in consiliis super filios hominum\plain \f1\lang1033\fs24\cf1  ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 ad vitam eter\plain \f1\lang1033\fs24\cf1 // Textverlust. \endash  Unklare Korrekturvermerke am unteren Rand (117\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 , 118\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ).}

