\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 153\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -161\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes ante et post communionem
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secuntur Oraciones deuote ac bone ante communionem sanctam. Et primo oratio beati Augustini episcopi de corpore Christi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Omnipotens et misericors deus, ecce ego accedo ad sacramentum\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs24\cf1 Haimerl\plain \f1\lang1033\fs24\cf1 , Fr\u246 \'f6mmigkeit, S. 126 A. 771; (154\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Creator omnium rerum, eterne deus, ego miser et indignus peccator\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (155\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine deus benignissime et clementissime pater \u8230 \'85 da mihi facinoroso\plain \f1\lang1033\fs24\cf1  \u8230 \'85 Kremsm\u252 \'fcnster, StiftsB, CC 27, 118\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ; (156\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Ave redemptor mundi, qui pro nobis dignatus es hanc carnem\plain \f1\lang1033\fs24\cf1  \u8230 \'85 auch M\u252 \'fcnchen UB, 8\u176 \'b0 Cod. ms. 213, 31\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs20\cf1 ; \plain \f1\lang1033\fs24\cf1 (157\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Domine, si vis, potes me mundare, idcirco rogo te\plain \f1\lang1033\fs24\cf1  \u8230 \'85 wie oben, 107\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ; (158\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Suscipe, benignissime deus, oblacionem\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  (158\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 \u8250 \'9bOrationes deuote post communionem sanctam\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Gracias tibi ago, omnipotens eterne deus, pro vniversis beneficiis tuis et specialiter \plain \f1\lang1033\fs24\cf1 \u8230 \'85 auch Karlsruhe, Badische LB, L 127, 2\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ; (159\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Eya nunc gracias ago, pyssime deus\plain \f1\lang1033\fs24\cf1  \u8230 \'85 auch L\u252 \'fcneburg, RatsB, Ms. Theol. 4\u176 \'b0 54, 35\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ; (160\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Gracias tibi ago, omnipotens et misericors deus, qui me indignum famulum\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (160\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Eya deus meus, rogo tuam misericordiam \plain \f1\lang1033\fs24\cf1 \u8230 \'85}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 162\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -172\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes ad s. Mariam
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secuntur oraciones deuote ac bone ad beatam virginem Mariam. Et primo oracio beati Augustini episcopi pro extremis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Ave gaude, vale, salue, domina mea sanctissima virgo Maria\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (165\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Commendo tibi, domina sancta Maria clementissima, animam meam\plain \f1\lang1033\fs24\cf1  \u8230 \'85 auch Augsburg, SuStB, 8\u176 \'b0 Cod. 15, 118\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  (abgeschrieben in Mondsee) und Wien, \u214 \'d6NB, Cod. 1936, 119b; (166\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Sanctissima gloriosissima et pyssima virgo sacratissima Maria, ego indignus peccator tibi committo esse, nosse, posse\plain \f1\lang1033\fs24\cf1  \u8230 \'85 auch  Clm 14528, 172\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ; (168\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 O intemerata et in eternum benedicta singularis et incomparabilis virgo \u8230 \'85, Inclina aures\plain \f1\lang1033\fs24\cf1  \u8230 \'85 (viele Abweichungen gegen\u252 \'fcber \plain \f1\scaps\lang1033\fs24\cf1 Leroquais\plain \f1\scaps\lang1033\fs24\cf1 ,\plain \f1\lang1033\fs24\cf1  Livres d\rquote heures 2, S. 336f.); (170\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Obsecro te, sanctissima virgo, dei genitrix Maria, que meruisti\plain \f1\lang1033\fs24\cf1  \u8230 \'85; (171\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Gaude, Maria gloriosa, angelorum domina\plain \f1\lang1033\fs24\cf1  \u8230 \'85 auch Berlin, SBB-PK, Ms. Theol. lat. oct. 137, 118\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 , Darmstadt, Hessische UuLB, Hs 2242, 83\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ; (172\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Deus qui virginalem aulam beate Marie semper virginis in qua habitares\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs24\cf1 Leroquais\plain \f1\scaps\lang1033\fs24\cf1 , \plain \f1\lang1033\fs24\cf1 2, S. 125; (172\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Saluto te, sancta Maria, domina angelorum et regina celorum\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs24\cf1 Leroquais\plain \f1\lang1033\fs24\cf1  2, S. 271.}

