\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Lamentum poenitentiae
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Incipit lamentatio poenitentiae duplici alfabeto editum exceptis tribus litteris id est A. B. et N. in quibus aliquantis uersibus multiplicatur, ubi exorauit pro Indulgentia peccatorum. Audi Christe triste fletum amarumque canticum, quod perculsus\plain \f1\lang1033\fs24  \u8230 \'85-\u8230 \'85 \plain \f1\i\lang1033\fs24 Inclito paraclito cui laus et potestas per eterna secula. Amen.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia Carminum 1692; Chevalier 1454. \endash  Ed.: Karl \plain \f1\scaps\lang1033\fs20 Strecker\plain \f1\lang1033\fs20 , MGH Poetae 4,2-3 (1923), S. 770-783 (diese Hs. Sigle E) \endash  Abdruck auch in PL 83, 1255-1262. \endash  Die Verse werden Isidorus Hispalensis bzw. Sisbertus Toletanus zugewiesen. \u193 \'c1lvaro \plain \f1\scaps\lang1033\fs20 Cancela Cilleruelo \plain \f1\lang1033\fs20 (s.o., Einband), der eine Neuedition vorbereitet, h\u228 \'e4lt eine Entstehung des Werks im 8. Jh. in Norditalien f\u252 \'fcr wahrscheinlicher.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Arial;}{\f3\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red201\green33\blue30;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Exhortatio poenitendi
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Quur fluctuas anima merorum quassata procellis? Usquequo ...-\u8230 \'85 summis honoribus cultores efferunt mundi. Amen\plain \f3\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia carminum 3217; \plain \f1\scaps\lang1033\fs20 Chevalier\plain \f1\lang1033\fs20  4145. \endash  Ed.: MGH Poetae 4,2-3 (wie oben), S. 762-768 (diese Hs. Sigle E). \endash  Verse vom selben Autor wie das vorausgehende Lamentum poenitentiae (54\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , zur Verfasserfrage s. dort).}

