\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 167\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -168\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Notae et Excerpta
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Notabile. Sciendum, quod deus permittit differentie inter homines propter tria. Primo propter eorum pene aggrauacionem. Nam de quanto sunt in loco sublimiori, de tanto versantur in periculo maiori\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 in his, que non sunt contra deum et contra bonos mores\plain \f1\lang1033\fs24  (Conradus de Zenn, De monastica vita, lib. 1, cap. 97, \u252 \'fcberliefert in: Clm 8391, 69\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ; vgl. Hellmut \plain \f1\scaps\lang1033\fs24 Zschoch\plain \f1\lang1033\fs24 , Klosterreform und monastische Spiritualit\u228 \'e4t im 15. Jahrhundert. Conrad von Zenn OESA (1460) und sein Liber de vita monastica. T\u252 \'fcbingen 1988, S. 241, Anm. 662). \endash  \plain \f1\i\lang1033\fs24 Sciendum, quod si offensa nota est fratri, postulanda est reconciliacio\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 Gregorius: Ecce a discordantibus accipere non vult sacrificium, holocaustum recipere recusat\plain \f1\lang1033\fs24  (Ludolphus de Saxonia, Vita Jesu Christi, pars 1, cap. 34; Edition: Vita Jesu Christi e Quatuor Evangeliis et Scriptoribus Orthodoxis Concinnata per Ludolphum de Saxonia ex Ordine Carthusianorum, studio et opera Clovis \plain \f1\scaps\lang1033\fs24 Bolard\plain \f1\lang1033\fs24  / Louis-Marie \plain \f1\scaps\lang1033\fs24 Rigollot\plain \f1\lang1033\fs24  / Jean Baptiste \plain \f1\scaps\lang1033\fs24 Carnandet\plain \f1\lang1033\fs24 . Paris/Rom 1865, S. 156b, Z. 33-59). \endash  (167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Nota de lingua. Hugo 2\u176 \'b0 de anima dicit, lingua dicitur, quia lingit adulando\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui ergo custodit linguam suam, custodit animam suam\plain \f1\lang1033\fs24  (Prv 21,23) (Ps.-Bernardus Claraevallensis, Tractatus de interiori domo, cap. 28; PL 184, 537BC). \plain \f1\i\lang1033\fs24 Vnde Catho: Quoniam virtutem puto compescere linguam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Nichil tam inquietat animam, nihil est, quod ita mobilem et instabilem faciat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 temere de quocumque velle recipere vel audire. Hec Cassiodorus super primo Psalmo detrahente secreto proximo suo\plain \f1\lang1033\fs24  (Hieronymus, Ep. 148, cap. 16; Edition: CSEL 56, S. 343, Z. 16-24). \endash  (168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De aqua benedicta. Sex operatur aqua per presbiterum benedicta\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 17608). Weitere Zitate: Ovid, Fulgentius, Augustinus. \endash  168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}{\f3\fnil\fcharset0 Verdana;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red50\green92\blue132;\red224\green224\blue224;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 191\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -202\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Bonaventura:\plain \f3\b\lang1033\fs18\cf1  \plain \f1\b\lang1033\fs24\cf1 Miscellanea ascetica de signis hominis saecularis et reprobi
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Quid sit necessarium homini volenti saluari. Hominis secularis est operibus misericordie intendere, mundum non amare, nullum bonum impedire\plain \f1\lang1033\fs24  \u8230 \'85; (191\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Signa hominis reprobi\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Si multa bona huius mundi recipit et est deus ingratus\plain \f1\lang1033\fs24  \u8230 \'85; (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quare peccata vitanda sunt\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Quot modis peccetur\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Duo genera compunccionis\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Qualis debeat esse religiosus\plain \f1\lang1033\fs24 \u8249 \'8b; (193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quid sit proprium proficientis\plain \f1\lang1033\fs24 \u8249 \'8b; (194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 In collationibus patrum homini religioso sit in vita\plain \f1\lang1033\fs24 \u8249 \'8b; (194\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec conueniunt Nouiciis\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Feruor nouicialis\plain \f1\lang1033\fs24 \u8249 \'8b; (195\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Vitia nouiciorum\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Uirtutes religiosorum\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Exercicia exteriorum\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Remedia gule\plain \f1\lang1033\fs24 \u8249 \'8b; (195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec frangunt cor humanum\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Signa reprehensibilis religiosi\plain \f1\lang1033\fs24 \u8249 \'8b; (196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quid expediat religioso\plain \f1\lang1033\fs24 \u8249 \'8b; (196\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De oracione et contemplacione\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Religiosus quisque debit\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec conueniunt religioso\plain \f1\lang1033\fs24 \u8249 \'8b; (197\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec ostendunt et faciunt hominem reli\plain \f1\lang1033\fs24 [giosum]\u8249 \'8b; (197\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Considerare tibi expedit\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Signa hominis saluandi\plain \f1\lang1033\fs24 \u8249 \'8b; (198\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Proprium est perfectorum\plain \f1\lang1033\fs24 \u8249 \'8b; (198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quid sit proprium amantis\plain \f1\lang1033\fs24  (expungiert, \u252 \'fcbergeschrieben) \plain \f1\i\lang1033\fs24 orantis\plain \f1\lang1033\fs24 \u8249 \'8b; (199\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Signa si deus sit cum anima\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Quid sit proprium orantis\plain \f1\lang1033\fs24 \u8249 \'8b; (199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Caro Cristi in cruce\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Corpus Christi digne sumptum\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Hec preparant animum ad contemplacionem\plain \f1\lang1033\fs24 \u8249 \'8b; (200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Signa boni contemplatiui\plain \f1\lang1033\fs24 \u8249 \'8b; (200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Nota septem gradus contemplacionis\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Quomodo timor dei graciam contemplacionis promeretur\plain \f1\lang1033\fs24 \u8249 \'8b; (201\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quomodo inter multos poteris esse solus\plain \f1\lang1033\fs24 \u8249 \'8b; \u8250 \'9b\plain \f1\i\lang1033\fs24 Obediencie septem sunt gradus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Primus gradus libenter obedire iuxta prelatorum imperium in omnibus, que non sunt contra legem dei\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 septimus perseueranter obedire, vnde qui perseuerauerit vsque in finem, hic saluus erit\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Sentenzen zum religi\u246 \'f6sen Leben, vorwiegend par\u228 \'e4netisch, Bonaventura zugeschrieben. Titel nach \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20  I, p. 615: Miscellanea ascetica. \endash  Parallel\u252 \'fcberlieferung: Clm 14683, 28\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 -33\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 ; Basel, UB, B X 25, 46\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 ; Kremsm\u252 \'fcnster, StiftsB, CC 56, 103\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 -115\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 ; Lambach, StiftsB, Memb. LXXXII, 9-11.}

