\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 217\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -228\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Humbertus de Romanis: De eruditione religiosorum opusculum (Exz.)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Quod gaudendum sit de transitu mundi ad religionem\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Quem diuina misericordia de mundo eduxit, si diligenti consideracione predicta attendat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 nec se esse deceptos crederent\plain \f1\lang1033\fs24  (Druck: S. 25-26, Z. 10); (218\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) daran zwei, Bernhard zugewiesene, Zitate von: \plain \f1\i\lang1033\fs24 Qui est in seculo vel in mundo, fugiat ad claustrum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed homines locum sanctificant\plain \f1\lang1033\fs24  (Gabriel Biel, Sermones de sanctis, sermo XIX; Druck: VD16 B 5400, Bl. 395b, Z. 41-letzte Zeile); \u8250 \'9b\plain \f1\i\lang1033\fs24 Idem\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Bonum est nos hic esse, scilicet in claustro, quia viuit homo hic purius\plain \f1\lang1033\fs24  \u8230 \'85 (vgl. PL 184, 1131B). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Quod in transitu ad religionem nihil mundi debeat retinere\plain \f1\lang1033\fs24 \u8249 \'8b (218\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Cauendum est omnimodo illi, qui mundo relicto ad religionem venit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sic a demonibus lacerabitur\plain \f1\lang1033\fs24  (Druck: S. 37-39). \endash  (219\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De his, que debet religiosus relinquere\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Omnia relinquere debet, qui venit ad religionem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 secundum eum doleas aut leteris\plain \f1\lang1033\fs24  (Druck: S. 39-40, Z. 28). \endash  (221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De nouitiis incipientibus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Qui in statu incipientis est, cum experiencia ei desit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 incessus maturior\plain \f1\lang1033\fs24  (Druck: S. 231, Z. 16-S. 232, Z. 8). \endash  (221\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De pertinentibus ad diuersos status religionis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 In statu incipientis debet intendere claustralis destruccioni vite secularis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 nec peccatis resistitur\plain \f1\lang1033\fs24  (Druck: S. 223-224, letzte Zeile). \endash  (222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De proficientibus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Qui in statu proficiendi sunt, defectus suos debent considerare\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 impaciens non est\plain \f1\lang1033\fs24  (Druck: S. 232, Z. 8-S. 233). \endash  (223\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De triplici ordinacione virtutum\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Sequitur de ordinacione virtutum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 bona speranda et amanda\plain \f1\lang1033\fs24  (Druck: S. 179-181). \endash  (224\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De ordine caritatis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Caritatis est operibus ceterarum virtutum bonitatem prouidere\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et sibi vsurpet\plain \f1\lang1033\fs24  (Druck: S. 183f.). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 De ordine humilitatis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ad humilitatem pertinet, si homo passus sit ruinam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 de fundamento cogitas humilita\plain \f1\lang1033\fs24 [ti]\plain \f1\i\lang1033\fs24 s\plain \f1\lang1033\fs24  (Druck: S. 184f.). \endash  (225\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quod dissolucio cauenda sit in choro\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Et notandum quod, cum viro religioso, vbique sit, cauenda dissolucio\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quod debes, obtuleris\plain \f1\lang1033\fs24  (Druck: S. 198-203).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck des Grundtextes: VD16 H 5888.}

