\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 239\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -246\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Hieronymus: Ad Oceanum de opprobriis
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Epistola quedam beati Jeronimi, que intitulatur consolatoria qualibet\plain \f1\lang1033\fs24  (?)\u8249 \'8b \plain \f1\i\lang1033\fs24 Diuersorum obprobria tribulaciones multiplices\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 salutate omnes, qui diligunt dominum nostrum Jesum Christum, cui est cum deo patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. Explicit epistola\plain \f1\lang1033\fs24  (PL 30, Sp. 282-288; CPL 744).}

