\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 286\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -309\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Liber vitae de passione domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit prohemium in librum, qui intitulatur liber vite de passione domini\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Liber iste intitulatur liber vite, quia eius materia vel subiectum vel pocius nobilissimum obiectum ymo effectus, forma et finis est ipse dominus\plain \f1\lang1033\fs24  \u8230 \'85; (287\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Diuisio huius libri\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Diuiditur liber in tres partes\plain \f1\lang1033\fs24  \u8230 \'85; (287\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Preambula libri\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Considera primo nuditatem Christi et cogita, quomodo nudus egressus est de vtero virginis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 letabundus et gaudens intrare in sanctam ciuitatem Ierusalem scilicet celestem, vbi est daturus regnum dei patris in spiritu sancto, qui cum eodem patre et spiritu sancto viuit\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. Explicit liber vite\plain \f1\lang1033\fs24 . \endash  (309\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Kolophon: \plain \f1\i\lang1033\fs24 Iste libellus est finitus per me fratrem Benedictum professum ordinis s\plain \f1\lang1033\fs24 [ancti] \plain \f1\i\lang1033\fs24 Benedicti monasterii s\plain \f1\lang1033\fs24 [ancti] \plain \f1\i\lang1033\fs24 Emmerami Ratisbonensis quarta die post annuncciacionis dominice Anno domini 1488\plain \f1\lang1033\fs24  (29. M\u228 \'e4rz 1488). \plain \f1\i\lang1033\fs24 Deo gracias\plain \f1\lang1033\fs24 . \endash  309\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f4\lang1033\fs20 Parallel\u252 \'fcberlieferung: Clm 4634, 58\plain \f4\super\lang1033\fs20 v\plain \f4\lang1033\fs20 ; Clm 4727, 132\plain \f4\super\lang1033\fs20 v\plain \f4\lang1033\fs20 ; Clm 18424, 61\plain \f4\super\lang1033\fs20 r\plain \f4\lang1033\fs20 ; Augsburg, \plain \f1\lang1033\fs20 SuStB\plain \f4\lang1033\fs20 , 4\u176 \'b0 Cod. 85, 80\plain \f4\super\lang1033\fs20 r\plain \f4\lang1033\fs20 ; Mattsee, StiftsB, Hs. 42, 206\plain \f4\super\lang1033\fs20 ra\plain \f4\lang1033\fs20 ; Stuttgart, \plain \f1\lang1033\fs20 W\u252 \'fcrttembergische\plain \f4\lang1033\fs20  LB, HB I 84, 48\plain \f4\super\lang1033\fs20 ra\plain \f4\lang1033\fs20 ; HB I 187, 70\plain \f4\super\lang1033\fs20 va\plain \f4\lang1033\fs20 .}

