\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 1\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  Breviarium (fragm.)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Post eleuacionem pro statu ecclesie. Psalmus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b Ps 121; \u8479 ? \plain \f1\i\lang1033\fs24\cf1 Aspice domine\plain \f1\lang1033\fs24\cf1  (Cantus 006126); \u8483 ? \plain \f1\i\lang1033\fs24\cf1 Respice domine\plain \f1\lang1033\fs24\cf1  (Cantus 006126c). \endash  \u8483 ? \plain \f1\i\lang1033\fs24\cf1 Fiat pax\plain \f1\lang1033\fs24\cf1  (vgl. Cantus 800171); \u8479 ? \plain \f1\i\lang1033\fs24\cf1 Et abundantia\plain \f1\lang1033\fs24\cf1  (Ps 121,7); \u8483 ? \plain \f1\i\lang1033\fs24\cf1 Saluos fac\plain \f1\lang1033\fs24\cf1 ; \u8479 ? \plain \f1\i\lang1033\fs24\cf1 Deus meus\plain \f1\lang1033\fs24\cf1 ; \u8483 ? \plain \f1\i\lang1033\fs24\cf1 Memor esto congregacionis\plain \f1\lang1033\fs24\cf1  (Cantus 007279za); \u8483 ? \plain \f1\i\lang1033\fs24\cf1 Domine vobiscum\plain \f1\lang1033\fs24\cf1  (Cantus 800121). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Collecta\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Deus, a quo sancta desideria\plain \f1\lang1033\fs24\cf1  (Corpus orationum 1088a); \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Alia collecta\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Ecclesie tue, quesumus\plain \f1\lang1033\fs24\cf1  (Corpus orationum 2404b); \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Alia\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Defende, quesumus, beata Maria\plain \f1\lang1033\fs24\cf1  (vgl. Corpus orationum 1053). \endash  1\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  leer.}

