\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 206\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -218\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Collectarium
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa60\itap0 \plain \f1\lang1033\fs24 De tempore: \u8250 \'9b\plain \f1\i\lang1033\fs24 Tempore aduentus usque ad natiuitatem ad vi et ix capitula\plain \f1\lang1033\fs24 \u8249 \'8b Is 2,2; Tit 2,12-13; Is 40,10; Iac 5,8 (Bd. 1,1, 5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta ad vi\plain \f1\lang1033\fs24 \u8249 \'8b Corpus orationum 4666. 4631. 771 (Bd. 1,1. 6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). 4865b (Bd. 1,1, 6\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  (206\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feriatis diebus in Quadragesima capitula ad vi et ix\plain \f1\lang1033\fs24 \u8249 \'8b Ez 34,11-12; Ez 18,21 (Bd. 1,1, 123\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ); Is 50,6-7 (Bd. 1,1, 125\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Dn 9,15-16 (Bd. 1,1, 126\plain \f1\super\lang1033\fs24 rb-va\plain \f1\lang1033\fs24 ). \endash  (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta ad vi\plain \f1\lang1033\fs24 \u8249 \'8b Corpus orationum 367 (Bd. 1,1, 128\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). 2267. 440. 1511. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Tempore pascali dominicis diebus capitulum ad tercias\plain \f1\lang1033\fs24 \u8249 \'8b I Cor 5,7 (Bd. 2,1, 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ); (207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Corpus orationum 1669 (Bd. 2,1, 12\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Apc 1,5 (Bd. 2,1, 6\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Corpus orationum 3237 (Bd. 2,1, 12\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Apc 1, 17-18 (Bd. 2,1, 6\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); Corpus orationum 1883 (Bd. 2,1, 12\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); (208\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ymnus usque ad ascensionem domini dominicis diebus ad iii\plain \f1\lang1033\fs24 \u8249 \'8b AH 50 Nr. 215 (Bd. 2,1, 5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Feriatis diebus tempore pascali capitulum ad vi\plain \f1\lang1033\fs24 \u8249 \'8b Apc 5,12 (Bd. 2,1, 13\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); I Cor 15,3 (Bd. 2,1, 13\plain \f1\super\lang1033\fs24 rb-va\plain \f1\lang1033\fs24 ); (208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Col 1,18 (Bd. 2,1, 13\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ); Act 10,40-41 (Bd. 2,1, 13\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ); Corpus orationum 837. 1507 (beide Bd. 2,1, 14\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ); Corpus benedictionum 1889 (Bd. 2,1, 14\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ); post Corpus orationum 5033 (Bd. 2,1, 14\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  (209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Dominica prima post octavas penthecostes\plain \f1\lang1033\fs24 \u8249 \'8b Dom. 1-23 mit Corpus orationum 1245. 5346. 4745. 899. 1532. (209\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 2210. 1188. 3233b. 4145. 1952. (210\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) 3887. 3739. 3819. 875. 2418. (210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 5659. 990. 2234. 3773. 3237. 2637. (211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) 2175. 2555 (Bd. 2,1, 84\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -104\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Dominica prima post epiphaniam domini\plain \f1\lang1033\fs24 \u8249 \'8b Dom. 1-6 mit Corpus orationum 6109 (Bd. 1,1, 69\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). 3909 (Bd. 1.1, 74\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). 3849 (Bd. 1,1, 81\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). (211\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 1898 (Bd. 1,1, 86\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). 2638b (Bd. 1,1, 91\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ). 815 (Bd. 1,1, 96\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ). \endash  Nicht im Druck nachweisbar: \u8250 \'9b\plain \f1\i\lang1033\fs24 Feriatis diebus post octavas pentecostes usque ad aduentum domini exclusiue et post octauas epiphanie usque ad dominicam Inuocauit collecte ad sextas et nonas\plain \f1\lang1033\fs24 \u8249 \'8b Gebete zu den Ferialtagen: \plain \f1\i\lang1033\fs24 Deus, qui in sanctis habitas\plain \f1\lang1033\fs24  (Corpus orationum 1743); (212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Subueniat nobis, domine\plain \f1\lang1033\fs24  (Corpus orationum 5535a); \plain \f1\i\lang1033\fs24 Deus, innocencie restitutor\plain \f1\lang1033\fs24  (Corpus orationum 1261); \plain \f1\i\lang1033\fs24 Gaudeat, domine\plain \f1\lang1033\fs24  (Corpus orationum 2702); \plain \f1\i\lang1033\fs24 Fideles tuos, quesumus\plain \f1\lang1033\fs24  (Corpus orationum 2680c); \plain \f1\i\lang1033\fs24 Dies nostros, quesumus\plain \f1\lang1033\fs24  (Corpus orationum post 2228); \plain \f1\i\lang1033\fs24 Da, quesumus, domine, populo tuo\plain \f1\lang1033\fs24  (Corpus orationum 993a); (212\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Excita, domine, quesumus\plain \f1\lang1033\fs24  (Corpus orationum 2556); \plain \f1\i\lang1033\fs24 Tvere, domine, populum tuum\plain \f1\lang1033\fs24  (Corpus orationum 5981); \plain \f1\i\lang1033\fs24 Pvrifica, quesumus, domine\plain \f1\lang1033\fs24  (Corpus orationum 4780); \plain \f1\i\lang1033\fs24 Assit, domine, quesumus, propiciacio\plain \f1\lang1033\fs24  (Corpus orationum 213); \plain \f1\i\lang1033\fs24 Adesto, domine, populis tuis\plain \f1\lang1033\fs24  (Corpus orationum 110).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 Commune sanctorum: (213\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Commune sanctorum incipit pro vi et ix et primo de apostolis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Hoc est preceptum\plain \f1\lang1033\fs24  (Io 15,12); Ant. \plain \f1\i\lang1033\fs24 Maiorem caritatem\plain \f1\lang1033\fs24  (Cantus 003685) \u8230 \'85 (Bd. 1,4, 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). \endash  (213\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 17) \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta de vno apostolo ad vi\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Adiuuet ecclesiam\plain \f1\lang1033\fs24  (Corpus orationum 201); \plain \f1\i\lang1033\fs24 Exaudi, domine\plain \f1\lang1033\fs24  (Corpus orationum 2465a) (Bd. 1,4, 5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). \endash  (214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De ewangelistis\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Ecce puer\plain \f1\lang1033\fs24  (Cantus 002536); Ant. \plain \f1\i\lang1033\fs24 Spiritu sapiencie\plain \f1\lang1033\fs24  (Cantus 004995) \u8230 \'85 (Bd. 1,4, 5\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  (214\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De pluribus martiribus\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Ivstorum autem\plain \f1\lang1033\fs24  (Cantus 003539); Ant. \plain \f1\i\lang1033\fs24 Si coram hominibus\plain \f1\lang1033\fs24  (Cantus 004881) \u8230 \'85 (Bd. 1,4, 13\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  (215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De vno martire\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Qui me confessus\plain \f1\lang1033\fs24  (Cantus 004479); Ant. \plain \f1\i\lang1033\fs24 Qui sequitur me\plain \f1\lang1033\fs24  (Cantus 004496) \u8230 \'85 (Bd. 1,4, 19\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ). \endash  (215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  vorletzte Zeile) \u8250 \'9b\plain \f1\i\lang1033\fs24 De confessore ad ix antiphona\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Qui manet in me\plain \f1\lang1033\fs24  (Cantus 004478); (216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Placens deo\plain \f1\lang1033\fs24  (Sap 4,10-11) \u8230 \'85 (nicht im Druck nachweisbar). \endash  (216\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De vno confessore pontifice\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Ecce sacerdos\plain \f1\lang1033\fs24  (Cantus 002544); Ant. \plain \f1\i\lang1033\fs24 Non est inuentus\plain \f1\lang1033\fs24  (Cantus 003914) \u8230 \'85 (Bd. 1,4, 26\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ). \endash  (217\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De confessore non pontifice\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Domine quinque talenta\plain \f1\lang1033\fs24  (Cantus 002370); \plain \f1\i\lang1033\fs24 Quinque mihi\plain \f1\lang1033\fs24  (Cantus 004542) \u8230 \'85 (Bd. 1,4, 29\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ). \endash  (217\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Laudes de virginibus\plain \f1\lang1033\fs24 \u8249 \'8b Ant. \plain \f1\i\lang1033\fs24 Uidi speciosam\plain \f1\lang1033\fs24  (Cantus 005407); Ant. \plain \f1\i\lang1033\fs24 Veni electa\plain \f1\lang1033\fs24  (Cantus 005323) \u8230 \'85 (Bd. 1,4, 33\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ). \endash  (218\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Capitulum ad vi de virgine que fuit martir\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Memorata sum\plain \f1\lang1033\fs24  (Sir 51,11); \plain \f1\i\lang1033\fs24 Liberauit me\plain \f1\lang1033\fs24  (II Tim 4,18) (Bd. 1,4, 29\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 30\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Capitulum ad vi de virgine non martyre\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Uirgo cogitat\plain \f1\lang1033\fs24  (I Cor 7,34); \plain \f1\i\lang1033\fs24 Emulor enim\plain \f1\lang1033\fs24  (II Cor 11,2) \u8230 \'85 (Bd. 1,4, 30\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 \u220 \'dcbersicht \u252 \'fcber die zur Sext und Non verwendeten Capitula, Collecta und Orationes, teils auch mit Angabe der Antiphonen, Versikel und Responsorien. \endash  Druck: VD16 B 8211, Bd. 1-2; jeder Bd. besteht aus vier Teilen mit getrennter Blattz\u228 \'e4hlung: Bd. 1 Teil 1: Breviarium, De tempore, pars hiemalis; Teil 2: Psalterium; Teil 3: Breviarium, De sanctis, pars hiemalis; Teil 4: Commune sanctorum. \endash  Bd. 2 Teil 1: Breviarium, De tempore, pars aestivalis; Teil 2: Psalterium; Teil 3: Breviarium, De sanctis, pars aestivalis; Teil 4: Commune sanctorum (Bd. 1,2 = Bd. 2,2; Bd. 1,4 = Bd. 2,4); Stellennachweise mit Bd., Teil und Folioangabe.}

