\pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Officium defunctorum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 Ps 24; (219\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ant. 1 \plain \f1\i\lang1033\fs24 Delicta iuuentutis\plain \f1\lang1033\fs24  (Cantus 002146); Ps 26; (220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ant. 2 \plain \f1\i\lang1033\fs24 Credo videre\plain \f1\lang1033\fs24  (Cantus 001948); Ps 39; (221\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ant. 3 \plain \f1\i\lang1033\fs24 Complaceat tibi\plain \f1\lang1033\fs24  (Cantus 001861); Ps 40; (222\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Ant. 4 \plain \f1\i\lang1033\fs24 Sana, domine\plain \f1\lang1033\fs24  (Cantus 004696); Ps 41; (222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Ant. 5 \plain \f1\i\lang1033\fs24 Sitiuit anima\plain \f1\lang1033\fs24  (Cantus 004972). \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Lecciones maiores in primo Nocturno\plain \f1\lang1033\fs24 \u8249 \'8b Lectio 1: Iob 7,14-21; (223\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8479 ?1 \plain \f1\i\lang1033\fs24 Scio enim\plain \f1\lang1033\fs24  (Cantus 602181 = \plain \f1\scaps\lang1033\fs24 Ottosen\plain \f1\lang1033\fs24  (wie unten), Nr. 85); \u8483 ?1 \plain \f1\i\lang1033\fs24 Surgent mortui\plain \f1\lang1033\fs24  (Cantus 602181a); Lectio 2: Iob 10,1-7; (223\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8479 ?2 \plain \f1\i\lang1033\fs24 Ne tradas\plain \f1\lang1033\fs24  (Cantus 007210 = Nr. 58); \u8483 ?2 \plain \f1\i\lang1033\fs24 Memorare\plain \f1\lang1033\fs24  (Cantus 007210a); Lectio 3: Iob 10,8-12; \u8479 ?3 \plain \f1\i\lang1033\fs24 Putasne\plain \f1\lang1033\fs24  (Cantus 601919 = Nr. 70); \u8483 ?3 \plain \f1\i\lang1033\fs24 Ecce in puluere\plain \f1\lang1033\fs24  (Cantus 601919a). \endash  (224\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 In 2\u176 \'b0 nocturno leccio prima\plain \f1\lang1033\fs24 \u8249 \'8b Lectio 4: Iob 13,23-28; \u8479 ?4 \plain \f1\i\lang1033\fs24 Memento queso\plain \f1\lang1033\fs24  (Cantus 601410 = Nr. 47); \u8483 ?4 \plain \f1\i\lang1033\fs24 Vitam\plain \f1\lang1033\fs24  (Cantus 601410a); Lectio 5: Iob 14,1-6; (224\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8479 ?5 \plain \f1\i\lang1033\fs24 Manus tue\plain \f1\lang1033\fs24  (Cantus 007127 = Nr. 44); \u8483 ?5 \plain \f1\i\lang1033\fs24 Dum veneris\plain \f1\lang1033\fs24  (Cantus 007127a); Lectio 6: Iob 14,13-16; (225\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8479 ?6 \plain \f1\i\lang1033\fs24 Redemptor meus\plain \f1\lang1033\fs24  (Cantus 601986 = Nr. 79); \u8483 ?6 \plain \f1\i\lang1033\fs24 Lauda anima\plain \f1\lang1033\fs24  (Cantus 601986a). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 In tercio nocturno leccio septima\plain \f1\lang1033\fs24 \u8249 \'8b Lectio 7: Iob 17,1-15; (225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8479 ?7 \plain \f1\i\lang1033\fs24 Absolue domine\plain \f1\lang1033\fs24  (Cantus 600017 = Nr. 1); \u8483 ?7 \plain \f1\i\lang1033\fs24 Si que illi\plain \f1\lang1033\fs24  (Cantus 600017a); Lectio 8: Iob 19,20-27; (226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8479 ?8 \plain \f1\i\lang1033\fs24 Deus eterne\plain \f1\lang1033\fs24  (Cantus 006417 = Nr. 18); \u8483 ?8 \plain \f1\i\lang1033\fs24 Qui in cruce\plain \f1\lang1033\fs24  (Cantus 006417a); Lectio 9: II Mcc 12,43-46; (226\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8479 ?9 \plain \f1\i\lang1033\fs24 Libera me\plain \f1\lang1033\fs24  (Cantus 007091 = Nr. 38); \u8483 ?9 \plain \f1\i\lang1033\fs24 Virgo dei\plain \f1\lang1033\fs24  (Cantus 007091zx). Druck: Bd. 1,2, 90\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -92\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecte minus note. Et primo pro pontifice\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus, qui inter apostolicos\plain \f1\lang1033\fs24  (Corpus orationum 1757c); \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro abbate sancto\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus, qui famulum tuum\plain \f1\lang1033\fs24  (Corpus orationum 1623); \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro sacerdote\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24 atque abbatis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Da nobis, domine, ut animam famuli tui sacerdotis\plain \f1\lang1033\fs24  \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro fundatoribus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Propiciare, quesumus, domine, anime famuli tui Arnolfi imperatoris\plain \f1\lang1033\fs24  \u8230 \'85 Druck: Bd. 1,2, 89\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  Z. 23-90\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 25; ebd., 104\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  Z. 1-9. \endash  (227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Post exequias fratris nostri conuentus defuncti dicuntur psalmi\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 penitenciales\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Domine, ne in furore\plain \f1\lang1033\fs24  (Ps 6) \plain \f1\i\lang1033\fs24 cum reliquis\plain \f1\lang1033\fs24 ; Ant. \plain \f1\i\lang1033\fs24 Ne intres\plain \f1\lang1033\fs24  (Cantus 203301) \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Satisfaciat tibi, domine deus, pro anima fratris nostri sanctissime dei genitricis semperque virginis Marie et sanctorum tuorum Emmerammi, Dionisii, Wolfgangi et Benedicti\plain \f1\lang1033\fs24  \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 Infra tricesimum fratris defuncti\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 dicuntur psalmi capitulares\plain \f1\lang1033\fs24 : Ps 5 cum reliquis (Ps 6, 114, 115, 129, 141, 142); \plain \f1\i\lang1033\fs24 Tibi, domine, commendamus animam\plain \f1\lang1033\fs24  (Corpus orationum 5884). Druck: Bd. 1,2, 103\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 29-103\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  Z. 27. \endash  227\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -228\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Zum Druck s.o. 206\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . \endash  Zu Nr. 2 vgl. auch Knud\plain \f1\scaps\lang1033\fs20  Ottosen\plain \f1\lang1033\fs20 , The Responsories and Versicles of the Latin Office of the Dead. Korrigierter ND. Norderstedt 2007, S. 199, 357-360 (zu Typ 85 nach der Responsorienreihe Nr. 85, 58, 70; 47, 44, 79; 1, 18, 38).}

