\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Ars metrica
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 INGredientibus artem metricam Hec dicantur. ARS DICTANDI QVA VVLGO VTIMVR\plain \f1\lang1033\fs24 \u8249 \'8b, \plain \f1\i\lang1033\fs24 alia\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 est metrica, alia prosaica\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quia facili et breuiori mora dilabuntur\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Z. 19) \u8250 \'9b\plain \f1\i\lang1033\fs24 Diuerse manerie uersuum. Leonina. M\plain \f1\lang1033\fs24 [aneria]\u8249 \'8b \plain \f1\i\lang1033\fs24 Possunt esse uersus leonini, caudati et paracterici. Leonini autem erunt, si in eorum medio et in fine eadem consonantia reperietur hoc modo\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 dulcis amica repente cum fera bella tentat me. Cum mihi dissociaris non nisi fortia faris\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 M\u246 \'f6glicherweise verfasst von Bernardus Bononiensis. \endash  (Nr. 1) Lit.: \plain \f1\scaps\lang1033\fs20 Turcan-Verkerk\plain \f1\lang1033\fs20 , R\u233 \'e9pertoire chronologique (s. 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), Nr. 21, S. 204f.; \plain \f1\scaps\lang1033\fs20 dies\plain \f1\lang1033\fs20 ., Liber artis 1 (s. 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), S. 137. \endash  (Nr. 2) Parallel\u252 \'fcberlieferung: Clm 17209, 64\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -65\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 . \endash  Ed.: Friedrich \plain \f1\scaps\lang1033\fs20 Zarncke\plain \f1\lang1033\fs20 , Zwei mittelalterliche Abhandlungen \u252 \'fcber den Bau rhythmischer Verse, in: Berichte \u252 \'fcber die Verhandlungen der K\u246 \'f6nigl.-S\u228 \'e4chsischen Gesellschaft der Wissenschaften, Phil.-Hist. Klasse 23 (1871), S. 34-96, hier S. 87-92. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Turcan-Verkerk\plain \f1\lang1033\fs20 , La ,Ratio in dictamina\u8219 ' (s. 35\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ), S. 953 (zum terminus ,maneries\u8219 '\plain \f1\i\lang1033\fs20 /\plain \f1\lang1033\fs20 ,maneria\u8219 '); \plain \f1\scaps\lang1033\fs20 dies\plain \f1\lang1033\fs20 ., Liber artis 1 (s. 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), S. 136-139; \plain \f1\scaps\lang1033\fs20 Felisi\plain \f1\lang1033\fs20 /\plain \f1\scaps\lang1033\fs20 Turcan-Verkerk\plain \f1\lang1033\fs20 , Les ,Artes dictandi\u8219 ' latines (s. 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ), Nr. 13.4, S. 433.}

