\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Versus Super Rethoricam\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Rethoricam flores, florumque uidemus odores\plain \f1\lang1033\fs24  \u8230 \'85 (S. 106, v. 304f.); \u8250 \'9b\plain \f1\i\lang1033\fs24 Conmendatio\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 domus\plain \f1\lang1033\fs24  [Oceani]\u8249 \'8b \plain \f1\i\lang1033\fs24 Ergo sub equoreo domus est ingens apogeo\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 Tunc se mortales recreant, nido iacet ales\plain \f1\lang1033\fs24 . \endash  Besitzeintrag von Hand des 15. Jhs., eingeritzt: \plain \f1\i\lang1033\fs24 Thomas est possessor huius libri\plain \f1\lang1033\fs24 .
