\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (94\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Z. 8-96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Stiltechnische Abhandlung (cap. 15-16)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Quia duplex sit oracio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Orationes dupliciter fieri quam pluribus claret aut perfecta oratio aut inperfecta est\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \u8218 \'82\plain \f1\i\lang1033\fs24 sedeo\plain \f1\lang1033\fs24 \u8219 '\plain \f1\i\lang1033\fs24  autem \plain \f1\lang1033\fs24 \u8218 \'82\plain \f1\i\lang1033\fs24 legere\plain \f1\lang1033\fs24 \u8219 '\plain \f1\i\lang1033\fs24  non dicimus, sed \plain \f1\lang1033\fs24 \u8218 \'82\plain \f1\i\lang1033\fs24 ut legam\plain \f1\lang1033\fs24 \u8219 ' (\plain \f1\scaps\lang1033\fs24 Bognini\plain \f1\lang1033\fs24 , XV.1-XVI.9, S. 74-77).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Lit.: Repertorium der Artes dictandi 1 (s. Lit.), S. 15 Nr. 2e.}

