\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 47\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -72\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Liber vitae
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit prohemium in librum, qui intytulatur liber vite de passione domini\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Liber iste intytulatur liber vite, quia eius materia uel subiectum vel pocius nobilissimum obiectum ymo effectus, forma et finis est ipse dominus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Diuisio huius libri\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Diuiditur iste liber in tres partes\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Perambula libri\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Incipiunt preambula, que habent quibus premissis volens studere in hoc libro et proficere\plain \f1\lang1033\fs24  \u8230 \'85; (Text) \plain \f1\i\lang1033\fs24 Considera primo nuditatem Christi et cogita quomodo nudus egressus est de vtero virginis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 vbi est daturus regnum dei patris in spiritu sancto, qui cum eodem patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. Explicit liber vite per manus\plain \f1\lang1033\fs24  [Schreibername fehlt].
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: Clm 4634, 58\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -73\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; Augsburg, SuStB, 4\u176 \'b0 Cod 85, 80\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -113\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ;\plain \f1\b\lang1033\fs20  \plain \f1\lang1033\fs20 Mattsee, StiftsB, 42, 206\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -214\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 ; Salzburg, StiftsB St. Peter, Cod. b. VI. 4, 248\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -259\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ;\plain \f1\b\lang1033\fs20  \plain \f1\lang1033\fs20 Stuttgart, W\u252 \'fcrttembergische LB, HB I 84, 48\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -55\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ; HB I 187, 70\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 -77\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 .}

