\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 240\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -252\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Bonaventura: Officium de compassione BMV
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 238\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -239\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipiunt Matutine de lamentacione Beate Marie et passione eiusdem dilectissimi filii edite ab Innocencio papa xxii\u176 \'b0\plain \f1\lang1033\fs24 \u8249 \'8b Matutin: \plain \f1\i\lang1033\fs24 Domine, labia mea\plain \f1\lang1033\fs24  (Ps 50,17); Inv.: \plain \f1\i\lang1033\fs24 Cum Maria\plain \f1\lang1033\fs24  (Cantus 100100); Hymnus: \plain \f1\i\lang1033\fs24 Venite, mares et femine\plain \f1\lang1033\fs24  (AH 31 Nr. 158) \u8230 \'85; (242\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad laudes\plain \f1\lang1033\fs24 \u8249 \'8b; (244\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Z. 4-8) \plain \f1\i\lang1033\fs24 Pietatem tuam\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Peltier\plain \f1\lang1033\fs24  (wie unten), S. 157a). \endash  (244\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad primam\plain \f1\lang1033\fs24 \u8249 \'8b; (246\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad ter\plain \f1\lang1033\fs24 [tiam]\u8249 \'8b; (ebd. Z. 5-12) \plain \f1\i\lang1033\fs24 Hora qui ductus\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Peltier\plain \f1\lang1033\fs24 , S. 157b). \endash  (247\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad sextam\plain \f1\lang1033\fs24 \u8249 \'8b (ebd. Z. 5-12); \plain \f1\i\lang1033\fs24 Crucem pro nobis\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Peltier\plain \f1\lang1033\fs24 , S. 158a). \endash  (247\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad nonam\plain \f1\lang1033\fs24 \u8249 \'8b; (ebd. vorletzte Zeile-248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Z. 4) \plain \f1\i\lang1033\fs24 Beata Cristi\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Peltier\plain \f1\lang1033\fs24 , S. 158b). \endash  (248\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad vesperas\plain \f1\lang1033\fs24 \u8249 \'8b; (250\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , letzte Zeile-250\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Z. 5) \plain \f1\i\lang1033\fs24 Domine Ihesu Criste, virginis\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Peltier\plain \f1\lang1033\fs24 , S. 160a). \endash  (250\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad completorium\plain \f1\lang1033\fs24 \u8249 \'8b; (252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) explicit: \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, qui hora diei ultima de cruce depositus\plain \f1\lang1033\fs24  \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Largire, quesumus, domine\plain \f1\lang1033\fs24  (Corpus orationum 3233b). \endash  Kolophon: \u8250 \'9b\plain \f1\i\lang1033\fs24 Expliciunt matutine de lamentacione beate Marie et passione filii eiusdem. Et dantur C dies indulgencie cuilibet dicenti\plain \f1\lang1033\fs24 \u8249 \'8b.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: GW 4648, XCIIII\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 -XCVI\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  = BSB-Ink B-673,6, Teil 2. \endash  Edition: Sancti Bonaventurae opera omnia, Bd. 14, ed. Adolphe Charles \plain \f1\scaps\lang1033\fs20 Peltier\plain \f1\lang1033\fs20 , Paris 1868, S. 228-230. \endash  Grundtext mit Interpolationen aus Ps.-Bonaventura, Officium de passione Christi; Fundstellen im Textbestand nach der Edition bei \plain \f1\scaps\lang1033\fs20 Peltier\plain \f1\lang1033\fs20 , S. 155-161. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Glorieux\plain \f1\lang1033\fs20 , R\u233 \'e9pertoire 2, S. 45 Nr. 305bq; \plain \f1\scaps\lang1033\fs20 Distelbrink\plain \f1\lang1033\fs20 , Bonaventurae scripta, S. 160f. Nr. 167.}

