\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 253\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -256\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes cum indulgentiis papalibus
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 253\plain \f1\super\lang1033\fs24\cf1 rv\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Schwei\u223 \'dftuch der Veronika
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 De Veronica\plain \f1\lang1033\fs24 \u8249 \'8b Hymnus: \plain \f1\i\lang1033\fs24 Salue, sancta facies nostri redemptoris\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Mone\plain \f1\lang1033\fs24 , Hymnen 1, S. 155f. Nr. 119\plain \f1\lang1033\fs24\cf1 ; \plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24 , Livres d\rquote heures 2, S. 349f.); Ps 66; \plain \f1\i\lang1033\fs24 Gloria patri\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Kyrie\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Pater noster\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Et ne nos\plain \f1\lang1033\fs24 ; \u8483 ? \plain \f1\i\lang1033\fs24 Fac mecum signum\plain \f1\lang1033\fs24  (Cantus g00768); \u8483 ? \plain \f1\i\lang1033\fs24 Signatum est super nos\plain \f1\lang1033\fs24  (Cantus 204675); Oratio: \plain \f1\i\lang1033\fs24 Deus, qui nobis signatis lumine uultus tui\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24 , Livres d\rquote heures 2, S. 350). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Papa Johannes, ut dicitur, donauit omnibus prescriptam oracionem deuote dicentibus tria milia dierum indulgenciarum. Benedictus\plain \f1\lang1033\fs24  [papa] \plain \f1\i\lang1033\fs24 xii\u176 \'b0 hanc oracionem composuit et dedit omnibus vere penitentibus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  Versus: \plain \f1\i\lang1033\fs24 Quadraginta duo ducenta milia quinque\plain \f1\lang1033\fs24  \u8230 \'85 \u8249 \'8b (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 10052).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: GW M23582, Bl. C1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -[C2]\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  = BSB-Ink I-150. \endash  Lit.: Ernst von\plain \f1\scaps\lang1033\fs20  Dobsch\u252 \'fctz\plain \f1\lang1033\fs20 , Christusbilder. Untersuchungen zur christlichen Legende. Leipzig 1899 (Texte und Untersuchungen zur Geschichte der altchristlichen Literatur 18), S. 224f., 251f.; Nikolaus \plain \f1\scaps\lang1033\fs20 Paulus\plain \f1\lang1033\fs20 , Geschichte des Ablasses im Mittelalter. Bd. 3: Geschichte des Ablasses am Ausgange des Mittelalters. 2. Aufl. Paderborn 2000, S. 249f.; Kathryn M. \plain \f1\scaps\lang1033\fs20 Rudy\plain \f1\lang1033\fs20 , Rubrics, Images and Indulgences in Late Medieval Netherlandish Manuscripts. Leiden u.a. 2017 (Library of the Written Word 55), S. 60-66.}

