\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 178\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -179\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Petrus de Palude: Sermo de uno martyre (Sermo 128)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 De martiribus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Hic est vere martir, qui pro Christi nomine sanguinem suum fundit. Hec verba legit sancta mater ecclesia in vnius martiris historia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qui post huius mundi supplicia celestem rapuit patriam, ad quam nos\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 5, S. 548 Nr. 331; Druck: VD16 P 1919, M iv\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -M v\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red51\green51\blue51;}

