\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 187\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -189\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Ps.-Petrus de Palude: Sermo de una virgine (Sermo 62)
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 O quam pulchra\plain \f1\lang1033\fs24  (vgl. Sap 4,1). \plain \f1\i\lang1033\fs24 In summa verborum tria innu\plain \f1\lang1033\fs24 [u]\plain \f1\i\lang1033\fs24 ntur, que inuenire adoptat sponsus in sponsa\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quarto omnia periclitancia, vt possit dicere: Ecce nos reliquimus\plain \f1\lang1033\fs24  (Mt 19,27) (\plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 5, S. 542 Nr. 240; Druck: VD16 P 1919, Bl. q ii\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -q ii\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ).}

