\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 202\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -204\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Sermo in adventum Domini
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Animaduerto, quod vir sanctus\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 4 R\plain \f1\lang1033\fs24 [egum] \plain \f1\i\lang1033\fs24 4\plain \f1\lang1033\fs24  (IV Rg 4,9-10). \plain \f1\i\lang1033\fs24 Hec verba dixit quedam mulier ad virum suum. Aduentus domini distinguitur in quattuor dominicas propter quadruplicem Christi aduentum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et dicetur ei: Appensus es in statera et inventus es multum habens\plain \f1\lang1033\fs24  (Dn 5,27). \plain \f1\i\lang1033\fs24 Isti duo in thesauro celesti reponentur\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red51\green51\blue51;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 204\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Hrabanus Maurus: De symbolo
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Hec est apostolorum symbolum certissima fides, vt profiteamur patrem et cum eo pariter filium et spiritum sanctum vnius esse essencie\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et his, qui perseueranter mala cum dyabolo ignem eternum. Hec est fides catholica unius catholice ecclesie cum operibus dileccionis pacienter finetenus seruanda. Explicit regula fidei\plain \f1\lang1033\fs24  (PL 112, 1227AB, Schluss abweichend).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red51\green51\blue51;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 204\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Hrabanus Maurus: De tonsura clericorum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Tonsura ecclesiastici vsus a Nazareis, nisi fallor, exorta est\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed lectoris judicio dimittatur\plain \f1\lang1033\fs24  (PL 112, 1167C-1168C).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red51\green51\blue51;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 205\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -211\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Engelbertus Admontensis: Excerpta varia ex Speculo virtutum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Seneca ad Lucillum: Natura dedit homini racionem imperfectam quidem \plain \f1\lang1033\fs24 \u8230 \'85 (I,1, S. 95, Z. 4-7). \plain \f1\i\lang1033\fs24 Ethicorum primo dicitur: Non speculando uel meditando solum\plain \f1\lang1033\fs24  \u8230 \'85 (I,1, S. 95, Z. 29-S. 96, Z. 2). \endash  \plain \f1\i\lang1033\fs24 Seneca de voluptate: Voluptas trahit ante se desiderum, post se fastidium\plain \f1\lang1033\fs24  (I,9, S. 105, Z. 16f.). \endash  \plain \f1\i\lang1033\fs24 De virtute: Virtus est querenda propter se\plain \f1\lang1033\fs24  \u8230 \'85 (I,11, S. 108, Z. 15-20). \endash  \plain \f1\i\lang1033\fs24 De honore: Honor est exhibicio reuerencie\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Gloria vero est fama virtutis\plain \f1\lang1033\fs24  \u8230 \'85 (I,11, S. 108, Z. 24-S. 109, Z. 3). \endash  \plain \f1\i\lang1033\fs24 Seneca de filicitate\plain \f1\lang1033\fs24  (!): \plain \f1\i\lang1033\fs24 Non est tibi necesse maria transire\plain \f1\lang1033\fs24  \u8230 \'85 (I,16, S. 115, Z. 10-12). \endash  \plain \f1\i\lang1033\fs24 Boecius: Quid o mortales extra vos queritis intra vos positam felicitatem?\plain \f1\lang1033\fs24  (I,16, S. 115, Z. 12f.). \plain \f1\i\lang1033\fs24 Septimo pollicitorum dicitur: Tria faciunt hominem viruosum et bonum\plain \f1\lang1033\fs24  \u8230 \'85 (I,16, S. 118, Z. 1-3). \endash  \plain \f1\i\lang1033\fs24 Versus: Magna sunt quondam capitis reuerencia cani\plain \f1\lang1033\fs24  \u8230 \'85 (II,9, S. 129, Z. 1f.). \endash  Weitere Zitate gr\u246 \'f6\u223 \'dferen Umfangs: (205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Boecius: Wersus. Nisi tuam habueris\plain \f1\lang1033\fs24  ... (II,14, S. 142, Z. 18-S. 143, Z. 2). \endash  (206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Damascenus dicit\plain \f1\lang1033\fs24 , [quod] \plain \f1\i\lang1033\fs24 passio duarum parcium anime est ex eo\plain \f1\lang1033\fs24  \u8230 \'85 (III,8, S. 166, Z. 27-S. 167, Z. 10). \endash  (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Virgilius de paciencia: Hec tibi erunt artes\plain \f1\lang1033\fs24  \u8230 \'85 (VI,10, S. 253, Z. 15-S. 255, Z. 4, mit Auslassungen). \endash  (209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Exemplum contra crudeles: Legitur de regina Amazonum\plain \f1\lang1033\fs24  \u8230 \'85 (XI,28, S. 414, Z. 16-29). \endash  (211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De temperancia in cibo et potu. Seneca: Multa et varia fercula\plain \f1\lang1033\fs24  \u8230 \'85 (V,10, S. 225, Z. 16-22). \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [Engelbertus Admontensis, De regimine principum] \plain \f1\i\lang1033\fs24 De consilio. Philosophus. Philosophus in prologo super rhetoricam: Consiliari circa ea, que vite hominum necessaria sunt, diuinissimum est\plain \f1\lang1033\fs24  (Prolog, S. 4). \plain \f1\i\lang1033\fs24 Sed secundum eundem duo sunt, que impediunt rectum consilium, scilicet timor et error\plain \f1\lang1033\fs24  (I,7, S. 22).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 (Nr. 1) Edition: Engelbert von Admont, Speculum virtutum, hrsg. von Karl \plain \f1\scaps\lang1033\fs20 Ubl\plain \f1\lang1033\fs20 . Hannover 2004 (MGH. Staatsschriften des sp\u228 \'e4teren Mittelalters 1,2; Die Schriften des Alexander von Roes und des Engelbert von Admont 2). \endash  (Nr. 2) Druck: Celeberrimi Engelberti Abbatis Admontensis OSB De regimine principum libri seu tractatus VII, ed. Johann Georg Gottlieb \plain \f1\scaps\lang1033\fs20 Huffnagl\plain \f1\scaps\lang1033\fs20 .\plain \f1\lang1033\fs20  Regensburg 1725, S. 3-254.}

