\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 299\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -300\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Carmen sapphicum de sancto Paulo
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 Textbeginn: (300\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De sancto Paulo. Hec dies clara omni laude digna\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 In qua cunctorum caput electorum\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Paulum spirantem et minis feruentem\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 De celo strauit\plain \f1\lang1033\fs24 . \endash  Fortsetzung und Schluss: (299\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Precibus tuis vas eleccionis\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Obtine nobis veniam salutis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Gloria patri resonemus omnes\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Eius et nato jubilemus apte\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Cum quibus regnat simul et creator\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Spiritus almus\plain \f1\lang1033\fs24 . \endash  300\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Acht sapphische Strophen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red51\green51\blue51;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 301\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -306\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Modus legendi abbreviaturas in utroque iure. Divisio corporis iuris
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Per breue Alphabetum, in quo communiores Abbreuiature textuum et glosarum canonici iuris continentur. Quecumque littera alphabeti posita sola in textibus iuris habeat nomen proprium viri vel mulieris, vt P Paulus, D Dionisius, H Helena, M Martha etc\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 A\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ap. se. le. id est Apostolice sedis legatus\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ap. re. id est Apellacione remota\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 X\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 X id est decima, XX id est vigesima\plain \f1\lang1033\fs24  (Druck: Bl. a[7]\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -a[8]\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , ohne Abk\u252 \'fcrzungen f\u252 \'fcr die Kommentatoren). \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (304\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Totum corpus iuris diuiditur in Ius Canonicum et ciuile. Ius canonicum diuiditur in quatuor libros. Primus dicitur decretum, quem compilauit magister Gracianus; diuiditur autem hic liber in tres partes principales, quarum prima uocatur distincciones\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 que eodem modo in quinque libros parciales diuiduntur vt Sextus et decretales\plain \f1\lang1033\fs24  (Druck: Bl. aiii\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , Z. 6-a[5]\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , Z. 6); (305\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Z. 14) \plain \f1\i\lang1033\fs24 Allegatur autem in Clementinis sic\plain \f1\lang1033\fs24 : ... \plain \f1\i\lang1033\fs24 De rescrip gracie in Cle, id est De rescriptis in capitulo Gracie in Clementinis\plain \f1\lang1033\fs24  (Clem. 1.3.4.). \endash  (305\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ius ciuile vel Imperatorum, quod leges appellamus, comprehenditur quinque voluminibus, que dicuntur libri legales\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 allegatur eciam hic liber interdum pro decima collacione vt sic: De pa\plain \f1\lang1033\fs24 [ce] \plain \f1\i\lang1033\fs24 te\plain \f1\lang1033\fs24 [nenda], \plain \f1\i\lang1033\fs24 c. Si clericus, coll\plain \f1\lang1033\fs24 [atio] \plain \f1\i\lang1033\fs24 decima et racio est, quia post nouem collaciones autenticorum editus est\plain \f1\lang1033\fs24  (Druck: Bl. a[5]\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 3-a[6]\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 31).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: verglichen mit GW M24947 = BSB-Ink M-504, mit Paraphrasierungen, Auslassungen und Zus\u228 \'e4tzen. \endash  Lit.: Robert \plain \f1\scaps\lang1033\fs20 Feenstra\plain \f1\lang1033\fs20 , La diffusion du \u8222 \'84Modus legendi abbreviaturas in utroque iure\ldblquote : \u201 \'c9ditions des XVI\plain \f1\super\lang1033\fs20 e\plain \f1\lang1033\fs20  et XVII\plain \f1\super\lang1033\fs20 e\plain \f1\lang1033\fs20  si\u232 \'e8cles, in: \plain \f1\lang1033\fs20\cf1 ZRG KA \plain \f1\lang1033\fs20 84 (1998), S. 345-385, bes. S. 345-351.}

