\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 9\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -13\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Petrus Comestor: Sermo de eruditione sacerdotum
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 [E]\plain \f1\i\lang1033\fs24 rudimini qui iudicatis\plain \f1\lang1033\fs24  (Ps. 2,10). \plain \f1\i\lang1033\fs24 Nolite arbitrari quod alienum \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 per ignem\plain \f1\lang1033\fs24 . \endash  Zwei erkl\u228 \'e4rende Einsch\u252 \'fcbe: (11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) nach quam temporis: \plain \f1\i\lang1033\fs24 Arbitrarius qui ad arbitrium suum et sue uoluntatis cuncta facit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 auctor concordie\plain \f1\lang1033\fs24 . (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) nach palponibus: \plain \f1\i\lang1033\fs24 cecis eruditoribus et indoctis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 dictum est enim\plain \f1\lang1033\fs24 . (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) kurzer Nachtrag nach per ignem: \plain \f1\i\lang1033\fs24 Tria sunt qui mundiciam castitatis corroborant \u8230 \'85 et obsequitur ad mortem.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Abschrift von Hugos Hand. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Rep. 4, S. 640 Nr. 52. Parallel\u252 \'fcberlieferung haupts\u228 \'e4chlich in Frankreich nachgewiesen und in den Hss. aus St. Viktor in Paris Petrus Comestor zugewiesen. Diese Hs. mit kleineren Abweichungen gegen\u252 \'fcber Druck: PL 198, 1813D-1817B. \endash  Zum Verfasser s.o. 5\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

