\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 [F]\plain \f1\i\lang1033\fs24 ac tibi vincula\plain \f1\lang1033\fs24  \u8230 \'85 (Ier. 27,2). \plain \f1\i\lang1033\fs24 Verbum istud de faciendis uinculis et catenis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 mandata tua et testimonia tua vincula consilii facienda sunt\plain \f1\lang1033\fs24 .
