\uc1
\pard\fi0\li0\tx2700\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 112\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 -120\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Orationes
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 (112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio bona, qualiter homo desolatus se debet in manus dei offerre et est sequens oracio in nomine domini. Amen\plain \f1\lang1033\fs24 \u8249 \'8b (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Domine deus, sancte pater, sis nunc et in eternum benedictus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 tantum est et non amplius\plain \f1\lang1033\fs24  (lib. 3, cap. 50; Edition: \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 265-269). \endash  (116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio contra cogitaciones malas\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Domine deus meus, ne elongeris a me, deus meus, in auxilium meum respice\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et pacienter consolacionem tuam expectare\plain \f1\lang1033\fs24  (lib. 3, cap. 23; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 197). \endash  (116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio pro illuminacione mentis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Clarifica me, Ihesu bone, claritate eterni luminis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et absque te friuola sunt vniuersa\plain \f1\lang1033\fs24  (lib. 3, cap. 23; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 198f.). \endash  (117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio pro purgacione cordis et celesti sapiencia\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Confirma me, deus, per gratiam sancti spiritus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sic enim incepta pergitur via secure\plain \f1\lang1033\fs24  (lib. 3, cap. 27; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 207). \endash  (118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Qualiter instante tribulacione deus invocandus sit et benedicendus\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Sit nomen tuum, domine, benedictum in secula\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 tanto tibi facilior est hec mutacio dextere excelsi. Deo gracias\plain \f1\lang1033\fs24  (lib. 3, cap. 29; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 209f.). \endash  (119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur oracio ad implorandam graciam\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Domine deus meus, omnia bona mea tu es\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et antequam natus essem in mundo\plain \f1\lang1033\fs24  (lib. 3, cap. 3; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 139f.). \endash  (120\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Concede, benignissime Ihesu, michi graciam tuam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 vno, summo, eterno bono, dormiam et requiescam. Amen\plain \f1\lang1033\fs24  (lib. 3, cap. 15; \plain \f1\scaps\lang1033\fs24 Lupo\plain \f1\lang1033\fs24 , S. 175).
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Gebete aus Thomas a Kempis, Imitatio Christi, lib. 3. Angaben zur Edition nach \plain \f1\scaps\lang1033\fs20 Lupo\plain \f1\lang1033\fs20 , De imitatione Christi libri quatuor (wie oben, 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ).}

