\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 329\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -334\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Guibertus de Tornaco: Sermo ad novicios
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Item bonus sermo ad nigros monachos\plain \f1\lang1033\fs24 \u8249 \'8b [I]\plain \f1\i\lang1033\fs24 n nouitate vite ambulemus. Ad Romanos 6\plain \f1\i\super\lang1033\fs24 to\plain \f1\lang1033\fs24  (Rm 6,4). \plain \f1\i\lang1033\fs24 Si nouitatem eligimus, vitam habebimus scilicet eternam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 mortui estis et vita vestra abscondita est cum Christo Jhesu, domino nostro\plain \f1\lang1033\fs24  (Col 3,3). \plain \f1\i\lang1033\fs24 Qui cum deo patre et spiritu sancto\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs20\cf1 Schneyer,\plain \f1\lang1033\fs20\cf1  Rep. 2, S. 302 Nr. 230. \endash  \plain \f1\lang1033\fs20 Druck: Gilbertus Tornacensis, Sermones ad omnes status. Lyon 1511, Bl. xcvii\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 -xcix\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 .}

