\uc1
\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 387\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -393\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Modus visitandi monasteria ordinis sancti Benedicti
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift im Kopfschnitt stark beschnitten. \endash  \plain \f1\i\lang1033\fs24 Item quando intrabunt visitatores opidum\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 uel ciuitatem siue septa monasterii, tunc debent pulsari omnes campane et pulsum continuare, donec visitatores intrauerint ecclesiam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (389\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 11) \plain \f1\i\lang1033\fs24 Tunc vnus visitatorum surgens dicit: Incipiamus igitur actum nostrum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (390\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 9) \plain \f1\i\lang1033\fs24 Post hoc actum visitacionis facturus singula monachorum nomina secundum ordinem a senioribus incipiendo signet per litteras a b c\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (393\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 1) \plain \f1\i\lang1033\fs24 Iterum ipsi visitatores requirant computacionem et de omnibus bonis monasterii computare\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 qualiter autem et quomodo vnusquisque debet interrogari et quibus modis interrogandi sic ponitur post tractatum de eleccione abbatis\plain \f1\lang1033\fs24 .}

