\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 236\plain \f1\super\lang1033\fs24 r-v\plain \f1\b\lang1033\fs24  Forma absolutionis
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Forma absolucionis in mortis articulo ad personas priuilegiat\plain \f1\lang1033\fs24 [\plain \f1\i\lang1033\fs24 os\plain \f1\lang1033\fs24 ]: \plain \f1\i\lang1033\fs24 Primo dicit confessor ad infirmum cum deuocione omnj qua potest\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Pax Christi et sancte matris ecclesie sit tecum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Amen. Rubrica. Confessione autem audita dicat confesso\plain \f1\lang1033\fs24  ... (236\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 et auctoritate domini Alexandri pape quinti\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 auctoritate predicta in nomine patris et filii et spiritus sancti. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Junicode;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Briefentwurf\plain \f1\b\i\lang1033\fs24  \plain \f1\b\lang1033\fs24 (Benachrichtigung \u252 \'fcber Wahl im Orden)
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Alia littera discretj, que debet esse aperta et aliam invenies septem folijs sequentibus, que debet esse clausa\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Reuerendis in Christo patribus custodj ceterisque patribus in conuocacionem custodialem in Norlinga celebrandam confluentibus frater N. gardianus et alij fratres conuentus N. obedienciam in domino deuotam. Cum ex statutis vnum de nostris fratribus discretum\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 Anno domini 1492 feria 6\plain \f1\i\super\lang1033\fs24 a \plain \f1\i\lang1033\fs24 infra octauam pasche\plain \f1\lang1033\fs24  (27. April)\plain \f1\i\lang1033\fs24 . Secunda littera sequens post septem folia debet esse clausa\plain \f1\lang1033\fs24 .}

