\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 1\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -7\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\b\lang1033\fs24\cf1 Formula in aedificationem fratris et monachi devoti
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Opusculum beati Bernhardi abbatis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Cristus nobis tradidit hanc normam viuendi\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et a malo liberent in eternum. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Emmeramer Parallel\u252 \'fcberlieferung: Clm 14357, 57\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -59\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; Clm 14793, 148\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -153\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (dort mit weiterer Lit.). \endash  Druck: AH 33, Nr. 220.}

